    storagePolicy: { logsKeepDays: 30, agentRunEventsCompressDays: 14, webcacheMaxEntries: 0, engineTranscriptDays: 30 },
    turnIdleTimeoutMs: 600000,    // watchdog: kill a turn idle (no events) longer than this
