  '**/id_ed25519', '**/id_ed25519[-_]*', '**/id_ed25519.bak', '**/id_ed25519.backup', '**/id_ed25519.copy', '**/id_ed25519.disabled', '**/id_ed25519.key', '**/id_ed25519.old', '**/id_ed25519.orig', '**/id_ed25519.pem', '**/id_ed25519.save', '**/id_ed25519.tmp',
