  template: ['模板', '找图'], vision: ['识图', '找图'],
  // 鼠标 / 键盘
  mouse: ['鼠标'], click: ['点击', '单击'], drag: ['拖拽', '拖动'], scroll: ['滚动', '滚轮'], position: ['位置', '坐标'],
