// (裁 12000,同 textPreview 上限);未配置 = 零行为(连 transcribeError 都不落,与 ① 同口径);
// 超 25 MB / 配置缺腿 / 上游失败 → 只落 transcribeError 代码,绝不挡上传 —— 文件已落盘可下载,
// 转写是增量(26 号文 §3「原文件保留可下载」)。本函数绝不 throw:上传主路径不能被转写故障打翻。
async function maybeTranscribeAudioAttachment(file) {
  try {
    if (!file || file.kind !== 'audio' || !file.path) return;
    const config = await readConfig();
    const resolved = resolveAsrProvider(config);
    if (resolved.failure) {
      if (resolved.failure.code !== 'asr.not_configured') file.transcribeError = resolved.failure.code;
      return;
    }
    if (!(file.size > 0) || file.size > ASR_MAX_BODY_BYTES) { file.transcribeError = 'asr.too_large'; return; }
    const audio = await fsp.readFile(file.path);
    if (!audio.length) return;
    const ext = String(file.name || '').toLowerCase().match(/\.([a-z0-9]+)$/);
    const mime = { wav: 'audio/wav', mp3: 'audio/mpeg', m4a: 'audio/mp4', webm: 'audio/webm', ogg: 'audio/ogg', flac: 'audio/flac' }[(ext && ext[1]) || ''] || 'application/octet-stream';
    const prompt = await voiceLexiconAsrPromptFor(resolved.provider, '');   // 59 号文:个人词当提示(会议录音里的人名、项目名)
    const result = await transcribeAudioViaProvider(resolved.provider, resolved.asrModel, { audio, contentType: mime, filename: file.name, language: '', prompt });
    if (result.failure) { file.transcribeError = result.failure.code; return; }
    file.transcript = String(result.text || '').slice(0, 12000);
  } catch { file.transcribeError = 'asr.internal'; }
}
// v1.9 图片输入增强(与上面音频转写同模具:尽力而为、绝不 throw、未配置/缺席零行为):
//   ① maybeOcrImageAttachment —— OCR 文本兜底。当前主端点【不收图】(provider.vision !== true)时,上传即经
//      桥接的 ai_computer_control__ocr_image 把图里的文字落 record.ocrText;进提示词由 03 buildAttachmentPrompt
//      打 <attachment kind="image-ocr" untrusted> 围栏,纯文本模型也能拿到图内文字。端点收图(vision=true)时
//      不 OCR —— 像素随消息直达模型,OCR 是纯开销。
//   ② maybeCompressImageAttachment —— 超限压缩。图片 >5MB 且端点收图时,用桥接的 ai_computer_control__image_resize
//      重采样出 ≤5MB 的派生件 record.sendPath(uploads/<id>/send.jpg);04-visual-pipeline 发送时优先读它,
//      超限大图不再直接降级占位。两条都要求桥接 MCP 在场;缺席/失败 = 零行为(存量 record 形状零漂移)。
const IMAGE_OCR_MAX_CHARS = 12000;           // 与 textPreview 上限同值
const IMAGE_SEND_MAX_BYTES = 5 * 1024 * 1024; // 与 04-visual-pipeline 的 IMAGE_ATTACH_MAX 同值(那边是发送闸,这边是压缩目标)

async function bridgedToolClient(config, toolName) {
  const { route } = await collectBridgedTools(config);
  const bridge = resolveBridge(route, toolName);
  if (!bridge) return null;
  const client = await getBridgedClient(bridge.serverId, config);
  return client ? { client, toolName: bridge.toolName } : null;
}

async function maybeOcrImageAttachment(file) {
  try {
    if (!file || file.kind !== 'image' || !file.path) return;
    const config = await readConfig();
    if (typeof PrivacyGateway !== 'undefined') PrivacyGateway.assertMediaAllowed(config);
    const provider = activeOpenAiProvider(config);
    if (provider && provider.vision === true) return; // 收图端点:像素直达,不需要 OCR 文本
    const target = await bridgedToolClient(config, 'ai_computer_control__ocr_image');
    if (!target) return;
    if (typeof PrivacyGateway !== 'undefined') PrivacyGateway.assertMediaAllowed(await readConfig());
    const result = await target.client.callTool(target.toolName, { path: file.path, lang: 'zh' });
    if (!result || result.ok === false) return;
    const text = typeof result.text === 'string' ? result.text
      : (typeof result.content === 'string' ? result.content : '');
    if (text.trim()) file.ocrText = text.slice(0, IMAGE_OCR_MAX_CHARS);
  } catch (error) { file.ocrError = error.code === 'privacy.media_not_supported' ? error.code : 'ocr.internal'; }
}

async function maybeCompressImageAttachment(file) {
  try {
    if (!file || file.kind !== 'image' || !file.path) return;
    if (!(file.size > IMAGE_SEND_MAX_BYTES)) return;
    const config = await readConfig();
    if (typeof PrivacyGateway !== 'undefined') PrivacyGateway.assertMediaAllowed(config);
    const provider = activeOpenAiProvider(config);
    if (!provider || provider.vision !== true) return; // 不发像素的路径压缩了也没人看
    const target = await bridgedToolClient(config, 'ai_computer_control__image_resize');
    if (!target) return;
    const outPath = path.join(path.dirname(file.path), 'send.jpg');
    // 文件大小≈像素数:按面积开方缩一档再留 15% 余量给 JPEG 编码差;一轮不行再缩一次(共≤2 趴,
    // 仍超限就零行为 —— 发送侧的 5MB 闸会走原有占位降级,绝不发超限大包)。
    let scale = Math.min(1, Math.sqrt((IMAGE_SEND_MAX_BYTES * 0.85) / file.size));
    for (let i = 0; i < 2; i++) {
      if (typeof PrivacyGateway !== 'undefined') PrivacyGateway.assertMediaAllowed(await readConfig());
      const result = await target.client.callTool(target.toolName, { path: file.path, output_path: outPath, scale: Number(scale.toFixed(4)) });
      if (!result || result.ok === false || result.success === false) return;
      const st = await fsp.stat(outPath).catch(() => null);
      if (!st) return;
      if (st.size <= IMAGE_SEND_MAX_BYTES) { file.sendPath = outPath; file.sendSize = st.size; return; }
      scale *= 0.7;
    }
  } catch (error) { file.compressError = error.code === 'privacy.media_not_supported' ? error.code : 'image.compress_failed'; }
}
async function handleAudioTranscribe(req, res) {
  const config = await readConfig();
  if (typeof PrivacyGateway !== 'undefined') PrivacyGateway.assertMediaAllowed(config);
  const resolved = resolveAsrProvider(config);
  if (resolved.failure) {
    const f = resolved.failure;
    return send(res, apiFailure(f.code, f.params, f.message, f.status));
  }
  const { provider, asrModel } = resolved;
  const contentType = String(req.headers['content-type'] || '').split(';')[0].trim().toLowerCase();
  if (!contentType.startsWith('audio/')) {
    return send(res, apiFailure('asr.content_type', { contentType }, 'Content-Type 必须是 audio/*', 400));
  }
  const q = new URL(req.url, 'http://x').searchParams;
  // filename 只许纯 basename(与 /api/upload/content 同域),缺省按 content-type 给个正经扩展名。
  const rawName = String(q.get('filename') || '').trim();
  const filename = (rawName && rawName.length <= 255 && rawName === path.basename(rawName) && rawName !== '.' && rawName !== '..')
    ? rawName : ('audio' + ({ 'audio/webm': '.webm', 'audio/wav': '.wav', 'audio/wave': '.wav', 'audio/mpeg': '.mp3', 'audio/mp4': '.m4a', 'audio/ogg': '.ogg', 'audio/flac': '.flac' }[contentType] || '.bin'));
  const language = String(q.get('language') || '').trim().slice(0, 40);
  // 调用方给了 prompt 就用它的;没给(麦克风按停顿切段那条路今天都不给)就用语音词库里的个人词(59 号文)。
  const hint = String(q.get('prompt') || '').slice(0, 4000) || await voiceLexiconAsrPromptFor(provider, '');
  let audio;
  try {
    audio = await readAudioBody(req);
  } catch (err) {
    if (err && err.statusCode === 413) {
      return send(res, apiFailure('asr.too_large', { maxBytes: ASR_MAX_BODY_BYTES }, '音频超过 25 MB 上限', 413));
    }
    throw err;
  }
  if (!audio.length) return send(res, apiFailure('asr.empty', {}, '空音频体', 400));
  const result = await transcribeAudioViaProvider(provider, asrModel, { audio, contentType, filename, language, prompt: hint });
  if (result.failure) {
    const f = result.failure;
    return send(res, apiFailure(f.code, f.params, f.message, f.status));
  }
  return send(res, json({
    ok: true, text: result.text,
    ...(result.outLanguage ? { language: result.outLanguage } : {}),
    durationMs: result.durationMs, providerId: result.providerId, model: result.model, estimated: result.estimated,
  }));
}

// ── 113b: 会话内容搜索 ────────────────────────────────────────────────────────────────────────
// 摸底口径:侧栏搜索此前是纯前端子串过滤,只看 title/summary/cwd 三个字段(session-experience.js),
// 会话正文一个字都不查;`sessions/index.json` 也只是元数据缓存。用户「我上周让它改过那个文件」这类
// 回忆式查找完全做不到,而这恰恰是本地工作台最该会的事 —— 历史全在本机。
//
// 为什么这里要落盘索引,而记忆召回那边不落:记忆的检索单元就是注册表已经读进来的头部字段,重算是
// 微秒级;会话的检索单元要从可能几 MB 的 NDJSON 正文里抽,不缓存就是每次搜索把整个历史读一遍。
//
// 索引单元(v2)= 标题 + 摘要 + 【每一条】用户消息(各取开头一段)+ 助手回复(从新到旧各取开头一段),每会话 ≤ 8K 字符。
// v1 只收首条 user 与末尾 6 条,长对话中间问过的事永远搜不到(「搜不全」);还把后台任务回执、压缩标记这类
// 系统行也收了进来(「搜到垃圾」)。失效键 = updatedAt + messageCount(两者都在 listSessions 的元数据里,判断失效零额外 IO)。
// 正文读取:≤ 2MB 整个读,更大的只读头尾各 1MB —— 一条几十 MB 的会话不会因为被搜索而把内存顶起来。
// 索引文件名沿用 _search-index-v1.json(换了名旧文件就成了孤儿),版本号升到 2:旧索引读进来就是版本不符 → 全量重建。
const SESSION_SEARCH_INDEX_FILE = '_search-index-v1.json';
const SESSION_SEARCH_INDEX_VERSION = 2;
const SESSION_SEARCH_UNIT_CAP = 8192;      // 每会话进索引的字符上限
const SESSION_SEARCH_USER_CHARS = 400;     // 每条用户消息取多少
const SESSION_SEARCH_ASSISTANT_CHARS = 240;// 每条助手回复取多少
const SESSION_SEARCH_HEAD_BYTES = 1024 * 1024;
const SESSION_SEARCH_TAIL_BYTES = 1024 * 1024;
const SESSION_SEARCH_SNIPPET_RADIUS = 60;
const SESSION_SEARCH_MAX_LIMIT = 50;
const SESSION_SEARCH_MIN_QUERY = 2;

function sessionSearchIndexPath() { return path.join(paths.sessions, SESSION_SEARCH_INDEX_FILE); }

// 只读文件的头尾两段,中间跳过;两段都按【整行】交出去:
//   · 文件 ≤ 头 + 尾:两段本来就盖满全文,整个读(头注「≤ 2MB 整个读」)。修前这种文件也切成两段,头段尾巴的半行 JSON 解析失败、
//     尾段又无条件丢掉第一行 —— 恰好跨在 1MB 接缝上的那条消息两边都不要,搜它说过的话搜不到(而且与头注说的「整个读」不符);
//   · 更大:头段停在半行里就继续往后读到行尾,尾段起点落在行中间就往前读到行首 —— 跨边界的那条消息补成完整一行。
//     补读各有上限(NDJSON_EDGE_EXTEND_MAX):超过上限的单行(几 MB 的工具输出)才放弃,把那半行丢掉,不让它进解析。
const NDJSON_EDGE_EXTEND_CHUNK = 64 * 1024;
const NDJSON_EDGE_EXTEND_MAX = 2 * 1024 * 1024;
async function readNdjsonEdges(file, headBytes, tailBytes) {
  let fh = null;
  try {
    const st = await fsp.stat(file);
    if (!st.isFile() || st.size === 0) return { head: '', tail: '' };
    fh = await fsp.open(file, 'r');
    const size = st.size;
    const readAt = async (pos, len) => {
      const buf = Buffer.allocUnsafe(len);
      const { bytesRead } = await fh.read(buf, 0, len, pos);
      return bytesRead === len ? buf : buf.subarray(0, bytesRead);
    };
    if (size <= headBytes + tailBytes) return { head: (await readAt(0, size)).toString('utf8'), tail: '' };
    // 头段:读满 headBytes,停在半行里就往后补到行尾。
    let headBuf = await readAt(0, headBytes);
    if (headBuf.length && headBuf[headBuf.length - 1] !== 0x0a) {
      const extra = [];
      let pos = headBytes, found = false;
      while (pos < size && pos - headBytes < NDJSON_EDGE_EXTEND_MAX) {
        const chunk = await readAt(pos, Math.min(NDJSON_EDGE_EXTEND_CHUNK, size - pos));
        if (!chunk.length) break;
        const nl = chunk.indexOf(0x0a);
        if (nl >= 0) { extra.push(chunk.subarray(0, nl + 1)); found = true; break; }
        extra.push(chunk); pos += chunk.length;
      }
      if (found) headBuf = Buffer.concat([headBuf, ...extra]);
      else { const cut = headBuf.lastIndexOf(0x0a); headBuf = cut >= 0 ? headBuf.subarray(0, cut + 1) : Buffer.alloc(0); }   // 超限的巨型单行:丢掉这半行
    }
    // 尾段:起点前一个字节不是换行 = 起点在行中间,往前补到行首。
    const tailStart = size - tailBytes;
    let tailBuf = await readAt(tailStart, tailBytes);
    const before = await readAt(tailStart - 1, 1);
    if (before.length && before[0] !== 0x0a) {
      const front = [];
      let pos = tailStart, found = false;
      while (pos > 0 && tailStart - pos < NDJSON_EDGE_EXTEND_MAX) {
        const from = Math.max(0, pos - NDJSON_EDGE_EXTEND_CHUNK);
        const chunk = await readAt(from, pos - from);
        const nl = chunk.lastIndexOf(0x0a);
        if (nl >= 0) { front.unshift(chunk.subarray(nl + 1)); found = true; break; }
        front.unshift(chunk); pos = from;
        if (pos === 0) { found = true; break; }   // 一直退到文件开头:第一行本来就从 0 开始
      }
      if (found) tailBuf = Buffer.concat([...front, tailBuf]);
      else { const cut = tailBuf.indexOf(0x0a); tailBuf = cut >= 0 ? tailBuf.subarray(cut + 1) : Buffer.alloc(0); }   // 超限:丢掉起点那半行
    }
    return { head: headBuf.toString('utf8'), tail: tailBuf.toString('utf8') };
  } catch {
    return { head: '', tail: '' };
  } finally {
    if (fh) await fh.close().catch(() => {});
  }
}

function parseNdjsonRows(text) {
  const lines = String(text || '').split('\n');
  const rows = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    try { rows.push(JSON.parse(trimmed)); } catch { /* 半条/坏行跳过,与会话读取侧同口径 */ }
  }
  return rows;
}

function sessionMessageText(row) {
  if (!row || typeof row !== 'object') return '';
  const content = typeof row.content === 'string' ? row.content : '';
  if (content) return content;
  // segments 型 assistant 消息:只取文本段与工具名,不展开工具结果(那是噪声,而且可能很大)。
  const segments = Array.isArray(row.segments) ? row.segments : [];
  const parts = [];
  for (const segment of segments) {
    if (!segment) continue;
    if (typeof segment.text === 'string' && segment.text) parts.push(segment.text);
    else if (segment.type === 'tool' && segment.name) parts.push(String(segment.name));
  }
  return parts.join(' ');
}

// 不进索引的行:系统行(压缩标记、修复说明、后台任务回执)、带 backgroundJobId 的回执、以及以「完成通知 /
// system-reminder」开头的注入文本 —— 它们不是用户说过或看过的话,进了索引只会让搜索命中一堆不相干的会话。
function sessionSearchRowIsNoise(row) {
  if (!row || typeof row !== 'object') return true;
  if (row.role !== 'user' && row.role !== 'assistant') return true;
  if (row.backgroundJobId || row.source === 'compact' || row.hidden === true) return true;
  if (row.meta && row.meta.origin === 'agent_wake') return true;   // 后台代理唤醒通知:系统文字,不是这条会话「干过什么」的信号
  const text = typeof row.content === 'string' ? row.content.trimStart() : '';
  return /^(?:\[(?:代理完成通知|后台任务完成通知|后台任务|工具结果)|<system-reminder>)/.test(text);
}
async function buildSessionSearchUnit(meta) {
  const body = sessionBodyPaths(meta.id);
  const { head, tail } = await readNdjsonEdges(body.messages, SESSION_SEARCH_HEAD_BYTES, SESSION_SEARCH_TAIL_BYTES);
  const rows = [...parseNdjsonRows(head), ...parseNdjsonRows(tail)].filter(row => !sessionSearchRowIsNoise(row));   // 两段都是整行(见 readNdjsonEdges)
  // 116-5b:线程的名字与那句概括也进检索单元。它们是模型对「这条线程到底要干什么」的概括,
  // 常常用了用户原话里没打出来的词(原话「帮我分析一下AMD」/ 概括「拉 AMD 最新行情与新闻」)——
  // 顺带提召回,而不只是显示。缺席时这两段是空串,被下面的 filter(Boolean) 丢掉。
  const briefUnit = sessionBriefOf(meta);
  const parts = [meta.title || '', (briefUnit && briefUnit.title) || '', (briefUnit && briefUnit.gist) || '', meta.summary || '', meta.cwd || ''];
  let used = parts.reduce((n, part) => n + String(part).length + 1, 0);
  const seen = new Set();
  const push = (value, cap) => {
    const trimmed = String(value || '').replace(/\s+/g, ' ').trim().slice(0, cap);
    // 同一句话(重发、重试)只收一次,既不白白抬高 tf,摘录也不会像复制错了。
    if (!trimmed || seen.has(trimmed) || used >= SESSION_SEARCH_UNIT_CAP) return;
    seen.add(trimmed);
    parts.push(trimmed);
    used += trimmed.length + 1;
  };
  // 用户说过的每一句都是最强的「这条会话干过什么」信号,先收;剩下的额度给助手回复,从新到旧。
  for (const row of rows) if (row.role === 'user') push(sessionMessageText(row), SESSION_SEARCH_USER_CHARS);
  for (let i = rows.length - 1; i >= 0; i--) if (rows[i].role === 'assistant') push(sessionMessageText(rows[i]), SESSION_SEARCH_ASSISTANT_CHARS);
  return parts.filter(Boolean).join('\n').replace(/\s+/g, ' ').slice(0, SESSION_SEARCH_UNIT_CAP);
}

// 进程内缓存:侧栏搜索是边打字边搜(200ms 去抖),修前每敲一个字就把整份索引(会话多时十几 MB)读盘再解析一遍。
// 按文件的 mtime + size 认新旧;本进程自己写索引时直接更新缓存。
let sessionSearchIndexCache = null;
async function readSessionSearchIndex() {
  try {
    const file = sessionSearchIndexPath();
    const st = await fsp.stat(file);
    const stamp = `${st.mtimeMs}|${st.size}`;
    if (sessionSearchIndexCache && sessionSearchIndexCache.stamp === stamp) return sessionSearchIndexCache.data;
    const raw = JSON.parse(await fsp.readFile(file, 'utf8'));
    if (!raw || raw.version !== SESSION_SEARCH_INDEX_VERSION || !raw.entries || typeof raw.entries !== 'object') return null;
    sessionSearchIndexCache = { stamp, data: raw };
    return raw;
  } catch {
    return null; // 缺失/损坏 = 全量重建。索引是纯派生物,没有需要抢救的权威数据。
  }
}

// 增量刷新:只为「新会话」或「updatedAt/messageCount 变了的会话」重抽单元;删掉的会话顺带清出去。
// 单飞:侧栏是边打字边搜,冷索引(首次/大批会话变化后)那一遍要把每个会话的正文头尾读一次、再整份写盘。修前每个并发请求
// 各自读到同一份旧索引、各自把全部单元重抽一遍、各自整份写回(N 个请求 = N 倍读盘 + N 次互相覆盖的写)。
// 现在按一条链串行(runKeyedChain):后到的请求等前一个建完,再拿它刚写好的索引做增量 —— 条目全都新鲜,不重抽、不重写。
// 不是「后到的直接共用先到的结果」:各请求带的 metas 可能不同(中途新建的会话),共用会漏掉它们。
const sessionSearchRefreshChains = new Map();
function refreshSessionSearchIndex(metas) {
  return runKeyedChain(sessionSearchRefreshChains, 'index', () => refreshSessionSearchIndexNow(metas));
}
async function refreshSessionSearchIndexNow(metas) {
  const existing = (await readSessionSearchIndex()) || { version: SESSION_SEARCH_INDEX_VERSION, entries: {} };
  const entries = {};
  let changed = false;
  for (const meta of metas) {
    const prior = existing.entries[meta.id];
    const stamp = `${meta.updatedAt || ''}|${Number(meta.messageCount) || 0}`;
    if (prior && prior.stamp === stamp && typeof prior.unit === 'string') { entries[meta.id] = prior; continue; }
    entries[meta.id] = { stamp, unit: await buildSessionSearchUnit(meta) };
    changed = true;
  }
  if (!changed && Object.keys(existing.entries).length === Object.keys(entries).length) return entries;
  const payload = { version: SESSION_SEARCH_INDEX_VERSION, builtAt: nowIso(), entries };
  // 写失败不影响本次搜索结果(内存里的 entries 已经算好了),下次再试。
  // 性能批 C1:紧凑 JSON(3000 条会话时带缩进写出来有 34 MB,每次会话有变都整份重写一遍)
  const wrote = await atomicWriteJson(sessionSearchIndexPath(), JSON.stringify(payload)).then(() => true, () => false);
  if (wrote) {
    try { const st = await fsp.stat(sessionSearchIndexPath()); sessionSearchIndexCache = { stamp: `${st.mtimeMs}|${st.size}`, data: payload }; } catch { sessionSearchIndexCache = null; }
  }
  return entries;
}

// 摘录:取【命中查询词最多】的那一段(修前取第一个命中处 —— 常常是某个常见字碰巧出现的地方,看不出为什么命中)。
// 出服务端前过 redact() —— 与 /api/audit 同一条脱敏路径,会话正文里粘过的 key/token 不会因为「搜了一下」就漏到响应里。
function sessionSearchSnippet(unit, terms) {
  const source = String(unit || '');
  const lower = source.toLowerCase();
  const span = SESSION_SEARCH_SNIPPET_RADIUS * 3;
  const candidates = [];
  for (const term of terms) {
    let from = 0;
    for (let n = 0; n < 20; n++) {
      const found = lower.indexOf(term, from);
      if (found < 0) break;
      candidates.push(found);
      from = found + term.length;
    }
  }
  let at = -1, best = -1;
  for (const pos of candidates) {
    const start = Math.max(0, pos - SESSION_SEARCH_SNIPPET_RADIUS);
    const window = lower.slice(start, start + span);
    const distinct = terms.filter(term => window.includes(term)).length;
    if (distinct > best || (distinct === best && pos < at)) { best = distinct; at = pos; }
  }
  const start = at < 0 ? 0 : Math.max(0, at - SESSION_SEARCH_SNIPPET_RADIUS);
  const end = Math.min(source.length, start + span);
  const slice = source.slice(start, end);
  return redact((start > 0 ? '…' : '') + slice + (end < source.length ? '…' : ''));
}

// 排序(修前:词法命中与字符 n-gram 向量两路做 RRF 融合,只要沾一个字就进结果 —— 「搜到垃圾」的主因):
//   ① 词法命中为主。一个会话要算命中,得覆盖至少一半的查询词,或者原样包含整句查询;
//      分数 = 各词权重之和,命中在标题 / 概括里翻倍,整句原样出现、查询词全中另有加分;
//   ② 向量(同义、拼写漂移)只补【强】命中:有词法结果时,只收分数不低于最高分六成且 ≥ 0.2 的;
//      一条词法命中都没有时(打错字)才放宽到最高分一半且 ≥ 0.15(实测打错字的真命中在 0.3–0.5,只沾一个词的在 0.08 上下)。
// 性能批 C1:会话搜索每敲一个字就查一次。语料(分词、df、向量)与每篇的「小写 + 空白折叠」都按条目缓存 ——
// 条目在会话没变时是同一个对象(refreshSessionSearchIndex 原样复用),结果与逐次现算逐位相同。
let sessionSearchCorpusCache = null;
const sessionSearchHayMemo = new WeakMap();   // 条目对象 -> { unit, hay }
function sessionSearchHayOf(entry) {
  const hit = sessionSearchHayMemo.get(entry);
  if (hit && hit.unit === entry.unit) return hit.hay;
  // 查询词(retrievalTerms 产出的)不含空白,所以在折叠过空白的文本里 includes 与在原文里结果相同;
  // 整句 phrase 本来就是在折叠后的文本里比。一份就够两用。
  const hay = String(entry.unit).toLowerCase().replace(/\s+/g, ' ');
  sessionSearchHayMemo.set(entry, { unit: entry.unit, hay });
  return hay;
}
function sessionSearchScope(indexEnabled = true) {
  return { fullText: false, mode: indexEnabled ? 'bounded_index' : 'metadata_only',
    maxCharsPerSession: SESSION_SEARCH_UNIT_CAP, userCharsPerMessage: SESSION_SEARCH_USER_CHARS,
    assistantCharsPerMessage: SESSION_SEARCH_ASSISTANT_CHARS, headBytes: SESSION_SEARCH_HEAD_BYTES, tailBytes: SESSION_SEARCH_TAIL_BYTES,
    note: '只搜索标题、摘要及有限正文索引,长会话可能遗漏;未命中不能证明从未做过。可换关键词或读取选定线程核对。' };
}
async function searchSessionsByContent(query, limit) {
  const q = String(query || '').trim();
  if (q.length < SESSION_SEARCH_MIN_QUERY) return { ok: true, query: q, results: [], indexed: 0, scope: sessionSearchScope(), reason: 'query_too_short' };
  const metas = await listSessions();
  const entries = await refreshSessionSearchIndex(metas);
  const byId = new Map(metas.map(meta => [meta.id, meta]));

  const documents = metas
    .filter(meta => entries[meta.id])
    .map(meta => ({ id: meta.id, text: entries[meta.id].unit }));
  if (!documents.length) return { ok: true, query: q, results: [], indexed: 0, scope: sessionSearchScope() };

  const terms = [...new Set(retrievalTerms(q).filter(term => !term.startsWith('#')))];
  const phrase = q.normalize('NFKC').toLowerCase().replace(/\s+/g, ' ');
  const needed = Math.max(1, Math.ceil(terms.length / 2));
  const scores = new Map();
  // 性能批 C1:首次(或会话大批变化后)要给几千篇现算小写 + 折叠,先分片预热、每 100 篇让一次事件循环
  for (let i = 0; i < documents.length; i++) {
    sessionSearchHayOf(entries[documents[i].id]);
    if (i % 100 === 99) await new Promise(resolve => setImmediate(resolve));
  }
  for (const doc of documents) {
    const hay = sessionSearchHayOf(entries[doc.id]);
    const meta = byId.get(doc.id) || {};
    const brief = sessionBriefOf(meta);
    const titleHay = [meta.title, brief && brief.title, brief && brief.gist].filter(Boolean).join(' ').toLowerCase();
    let score = 0, matched = 0;
    for (const term of terms) {
      if (!hay.includes(term)) continue;
      matched += 1;
      const weight = Math.min(12, Math.max(2, term.length));
      score += titleHay.includes(term) ? weight * 2 : weight;
    }
    const exact = phrase.length >= 2 && hay.includes(phrase);
    if (!exact && matched < needed) continue;
    if (exact) score += 30;
    if (terms.length && matched === terms.length) score += 10;
    scores.set(doc.id, score);
  }
  const lexical = [...scores.entries()].map(([id, score]) => ({ id, score }));

  if (!sessionSearchCorpusCache) sessionSearchCorpusCache = createRetrievalCorpusCache();
  const corpus = await sessionSearchCorpusCache.build(documents);
  const vector = rankRetrievalCorpus(corpus, q);
  const top = vector.length ? vector[0].score : 0;
  const floor = lexical.length ? Math.max(0.2, top * 0.6) : Math.max(0.15, top * 0.5);
  const extra = vector.filter(row => !scores.has(row.id) && row.score >= floor);

  const updatedOf = id => String((byId.get(id) || {}).updatedAt || '');
  lexical.sort((a, b) => b.score - a.score || updatedOf(b.id).localeCompare(updatedOf(a.id)) || String(a.id).localeCompare(String(b.id)));
  const ranked = [
    ...lexical.map(row => ({ id: row.id, score: row.score / 100, meta: byId.get(row.id) })),
    ...extra.map(row => ({ id: row.id, score: row.score / 100, meta: byId.get(row.id) })),
  ].filter(row => row.meta);

  const cap = Math.min(SESSION_SEARCH_MAX_LIMIT, Math.max(1, Number(limit) || 20));
  return {
    ok: true,
    query: q,
    indexed: documents.length,
    scope: sessionSearchScope(),
    results: ranked.slice(0, cap).map(row => ({
      id: row.id,
      title: row.meta.title || '',
      // 116-5b(§11.8.5):线程的名字与一句概括。**缺席时这两个键不出现** —— 存量会话的
      // /api/sessions/search 载荷逐字节不变。title 仍是原话(它是权威,也是 hover 全文与回退)。
      // 加在这里而不是让调用方自己去 /api/sessions 里 join:这条响应从此自足,
      // 只拿到搜索结果的消费者(经典壳搜索、将来的任何面)不必再取一次会话列表。
      ...(sessionBriefOf(row.meta) ? { briefTitle: sessionBriefOf(row.meta).title, briefGist: sessionBriefOf(row.meta).gist } : {}),
      cwd: row.meta.cwd || '',
      updatedAt: row.meta.updatedAt || '',
      pinned: Boolean(row.meta.pinned),
      messageCount: Number(row.meta.messageCount) || 0,
      score: Number(row.score.toFixed(6)),
      snippet: sessionSearchSnippet(entries[row.id].unit, terms),
    })),
  };
}

// GET /api/sessions/:id 条件 GET 的【盘上戳】。不装载会话就能取:头文件整份读出来哈希(头只有几 KB~几十 KB;
// 不能只信 updatedAt/mtime —— 同一毫秒/同一个文件系统时钟刻度内两次落头会撞)+ 两个正文的 size/mtime/ino(追加改 size,
// 慢路径整份重写是 rename 换 inode)+ 后台任务账本的 size/mtime/ino(loadSession 会把它合并进 messages)。
// 头是提交点(saveSession 正文先落、头后落,且每次都推 updatedAt),所以「头哈希 + 正文戳」不变 = 盘上没有新提交。
// 任何一步读不到(legacy 单文件会话没有正文文件、瞬时锁、会话不存在)一律返回 null → 调用方不发 ETag、走原来的无条件全量,
// 与修前逐字节一致。
async function sessionEnvelopeStamp(id) {
  if (safeSessionId(id) === null) return null;
  try {
    const bp = sessionBodyPaths(id);
    const [head, msg, prov, jobs] = await Promise.all([
      fsp.readFile(sessionPath(id)),
      fsp.stat(bp.messages),
      fsp.stat(bp.provider),
      // 路径与 11-native-tools.js 的 backgroundJobFile 同一处约定(sessions/background-jobs/<id>.json)。这里不直接引用它:13d 引 11
      // 会新增一条循环边(module-dependency-graph 的债务上限锁着);e2e session-get-etag 的 F 段写一份账本、断言标签会变,钉住这份约定不漂移。
      fsp.stat(path.join(paths.sessions, 'background-jobs', id + '.json')).catch(() => null),
    ]);
    const fileStamp = st => `${st.size}:${st.mtimeMs}:${st.ino}`;
    return crypto.createHash('sha1').update(head).digest('hex') + '|' + fileStamp(msg) + '|' + fileStamp(prov) + '|' + (jobs ? fileStamp(jobs) : '-');
  } catch { return null; }
}
// 标签 = 盘上戳 + 装载会改变响应的全部【内存】输入:活态四件(见 sessionEnvelopeLiveParts)、会话级权限档/桌面工具覆盖表
// (loadSession 会把它们盖到返回的会话对象上)、垂死回合收尾窗口(turnSettlers:窗口内 loadSession 不做残留 pending 叙事段的
// 惰性清理,出窗后同一份盘面装载出的会话就不同了)、以及 ?since 参数(管家会话的尾巴切片,响应体不同)。
// deltaKey:增量取的两个查询参数(见路由体 fromIndex/prefixStamp)—— 它们改变响应体(尾巴 vs 全量),所以进标签;
// 不带这两个参数时哈希输入与修前逐项相同(不追加这一项),无参 GET 的标签逐字节不变。
function sessionEnvelopeEtag(id, stamp, liveParts, sinceRaw, deltaKey) {
  const overrides = [
    sessionPermissionModeOverrides.has(id) ? [sessionPermissionModeOverrides.get(id)] : null,
    sessionDesktopToolsOverrides.has(id) ? [sessionDesktopToolsOverrides.get(id)] : null,
  ];
  const parts = [stamp, overrides, turnSettlers.has(id), liveParts, sinceRaw == null ? null : String(sinceRaw)];
  if (deltaKey) parts.push(['delta', deltaKey]);
  return pretenderEtag('session', pretenderHash(parts));
}
// 会话信封上【只来自内存】的那几样(活回合标志 / liveTail / liveTurn / 递话通道):GET /api/sessions/:id 的 200 体与
// 条件 GET 的 ETag 共用这一份取样 —— 判据只写一处,响应里放了什么,ETag 就带什么(sessionEnvelopeEtag 直接哈希它)。
// 纯同步只读:不碰盘、不改 reg。取样逻辑与注释原样搬自路由体(只是从内联挪成函数,一个字没动)。
function sessionEnvelopeLiveParts(id) {
  // A child can exit before its final assistant message is persisted. Keep pollers live until
  // the driver releases its existing owner, or a user-only snapshot can stop polling forever.
  let live = activeChildren.has(id) || turnSettlers.has(id);
  if (!live) {
    for (const runtime of activeAgentRuns.values()) {
      if (runtime && runtime.run && runtime.run.sessionId === id) { live = true; break; }
    }
  }
  // 117l D4(§11.9;用户第四轮走查第 3 条):活回合的尾巴。只在【真有一个活回合】时出现
  // (回合一结束这个键就不在了 —— 抽屉据此把「它正在说」换回「它刚说」),不落盘、不进任何投影。
  // 放在【信封】上而不往 session 里塞:与下面 displayTitle 同一条纪律(路由不改写会话头本身)。
  // 117m-A5(用户第六轮走查①「点开线程的看全文,还是啥也看不到」):同一个信封上再多带四个键 ——
  // full(本回合从头累加的正文,04 里硬顶 12000 字、超顶砍头)、truncated、tools(最近 ≤20 条工具名
  // 与起止,**不含参数与结果**)、startedAt/iterations。经典壳据此在会话末尾画一张临时气泡,
  // 让「在别处起的回合」也看得到它现在在说什么。仍然是【条件展开】:回合一结束这个键就不在了。
  // 白名单式逐字段搬运,不 spread reg 上那份对象 —— 累加器上还有 batchMark/lastKind 这类内部游标,
  // tools 里还有工具调用 id,都不该出现在信封上。
  const liveReg = activeChildren.get(id);
  const liveTail = liveReg && liveReg.liveTail && typeof liveReg.liveTail === 'object'
    ? {
      text: String(liveReg.liveTail.text || ''), tool: String(liveReg.liveTail.tool || ''), updatedAt: String(liveReg.liveTail.updatedAt || ''),
      full: String(liveReg.liveTail.full || ''),
      truncated: Boolean(liveReg.liveTail.truncated),
      startedAt: String(liveReg.liveTail.startedAt || ''),
      iterations: Math.max(0, Number(liveReg.liveTail.iterations) || 0),
      tools: (Array.isArray(liveReg.liveTail.tools) ? liveReg.liveTail.tools : []).slice(-20).map(row => ({
        name: String((row && row.name) || '').slice(0, 80),
        status: String((row && row.status) || ''),
        startedAt: String((row && row.startedAt) || ''),
        endedAt: String((row && row.endedAt) || ''),
      })),
    }
    : null;
  // 117o-A7(用户第七轮走查,两张截图对照:「为啥这个查看全文,不能像 2.0 那样显示呢」):
  // 同一个信封上【再加一个新键】liveTurn —— 在途回合的有序叙事账本(02c 的 createTurnSegmentBuilder,
  // 回合落盘之后经典壳重建叙事靠的就是它)。A5 的 liveTail 只是一段拼好的纯文本,渲染层再怎么写
  // 也画不出思考块 / 过程记录 / 工具卡,差距的根子是数据形状。前端拿到它以后组装成一条与落盘助手
  // 消息同形的对象,交给【渲染落盘助手消息的同一个入口】去画,不写第二套简版渲染器。
  // 三条纪律:① 上面 liveTail 那几个键一个字不动(抽屉的「它正在说」在读它,117l/117m 的断言看着它),
  // 新键是【加】不是改;② 有界与截断方向都在 02c 的 liveSnapshot() 里(段数/单段/总文本三重硬顶,
  // 超顶从头部丢弃并置 truncated:true);③ **工具结果一律不下发** —— 只送 name 与那一行参数摘要,
  // 结果可能是整份文件、可能含密钥;回合一结束真消息落盘,经典壳照常拿到全部(e2e 的 E 段钉着这条)。
  const liveNarrative = liveReg && liveReg.liveSegments && typeof liveReg.liveSegments.liveSnapshot === 'function'
    ? liveReg.liveSegments.liveSnapshot()
    : null;
  const liveTurn = liveNarrative
    ? {
      segments: Array.isArray(liveNarrative.segments) ? liveNarrative.segments : [],
      toolCalls: Array.isArray(liveNarrative.toolCalls) ? liveNarrative.toolCalls : [],
      truncated: Boolean(liveNarrative.truncated),
      startedAt: liveTail ? liveTail.startedAt : '',
      iterations: liveTail ? liveTail.iterations : 0,
    }
    : null;
  // 117s-G(27 号文 §11.13.1 ②;真浏览器复现的丢回合 bug):这条线程此刻【该走哪条递话通道】。
  // 判据不是新造的 —— 就是 13h 那条递话阶梯 stewardRelayChannelFor,顺序 answer > permission >
  // queued > steer > turn,
  // 全仓递话唯一那处判定,经 06i 的延迟绑定命名空间取(13d 直接引用 13h 会造一条前向边)。
  // 为什么信封上要有它:经典壳的发送门只认 activeTurns —— 本页自己起的那条流。管家在服务端起的
  // 回合不在里面,于是用户在「2.0 视窗」里打一句话走的是「新回合」那条路,09:1347 的
  // `activeChildren.has -> stopSession('superseded')` 把跑着的回合就地杀掉,界面零提示。
  // 只投影 {channel, wait} 两个键:questionId/pendingId 是待决面的内部锚点,不该进会话信封。
  // 空闲(channel === 'turn')时整个键都不下发 —— 存量消费者拿到的信封逐字节不变。
  const relayDecision = typeof StewardHooks.relayChannel === 'function' ? StewardHooks.relayChannel(id) : null;
  const relay = relayDecision && relayDecision.channel && relayDecision.channel !== 'turn'
    ? { channel: String(relayDecision.channel), ...(relayDecision.wait ? { wait: relayDecision.wait } : {}) }
    : null;
  return { live, liveTail, liveTurn, relay, execution: sessionExecutionSnapshot(id), executionObservation: sessionExecutionObservation(id) };
}

// 安全走查 S10:导入会话 JSON(POST /api/sessions 带 messages)时,文件里写的 cwd 不能原样当工作区 —— 一份被分享来的会话文件
// 写个 cwd:'/' 就把本会话的文件工具写根放大到整盘。前端 importSession 已不再上送文件里的 cwd;这里是服务端的第二道:
// 导入形态(body.messages 非空)若显式带了 cwd,必须落在【已配置的工作区】(默认工作区 + workspaces[] 各条)之一内部或就是它,
// 否则 400(不回显路径)。比对走真实路径(符号链接 / junction 逃不出去)。普通「新建会话」(不带 messages)不受影响:
// 它的 cwd 来自用户在界面里选的文件夹(最近用过的、拖进来的),并不要求事先登记成工作区。
async function importedSessionCwdAllowed(cwd, config) {
  const raw = typeof cwd === 'string' ? cwd.trim() : '';
  if (!raw) return true;
  const target = await resolveContainmentPath(raw);
  if (!target || target.unresolvable) return false;
  const rootsRaw = [config && config.defaultWorkspace ? config.defaultWorkspace : os.homedir()];
  for (const w of (config && Array.isArray(config.workspaces) ? config.workspaces : [])) {
    if (w && typeof w === 'object' && typeof w.path === 'string' && w.path.trim()) rootsRaw.push(w.path.trim());
  }
  for (const rootRaw of rootsRaw) {
    if (typeof rootRaw !== 'string' || !rootRaw.trim()) continue;
    const root = await resolveContainmentPath(rootRaw);
    if (root && !root.unresolvable && pathWithinRoot(target.path, root.path)) return true;
  }
  return false;
}

async function handleSessionApiRoutes(req, res, pathname) {
  if (req.method === 'GET' && pathname === '/api/sessions') {
    return send(res, json({ ok: true, sessions: await listSessions() }));
  }
  // 113b: 会话内容搜索。GET /api/sessions/search?q=&limit=
  // 必须排在下面那条 pathname.startsWith('/api/sessions/') 的通配分支【之前】，
  // 否则 'search' 会被当成会话 id 拿去查。
  if (req.method === 'GET' && pathname === '/api/sessions/search') {
    if (!tokenOk(req)) return send(res, apiFailure('auth.token_invalid', {}, 'missing or invalid workbench token', 403));
    const config = await readConfig();
    if (!sessionSearchIndexEnabled(config)) {
      // 走 apiFailure 而不是裸字符串 error：后者会被 normalizeApiErrorPayload 归结成
      // api.request_failed，真正的 code 降级成 message，调用方就分不出“关了”和“坏了”。
      // 118 波在 help.doc_missing 上栓过同一个坑。状态码给 200：它不是错误，只是能力关着。
      return send(res, apiFailure('session_search.disabled', {}, 'session search index is disabled', 200));
    }
    const params = new URL(req.url, 'http://x').searchParams;
    return send(res, json(await searchSessionsByContent(params.get('q') || '', params.get('limit'))));
  }
  if (req.method === 'POST' && pathname === '/api/sessions') {
    const body = await readJsonBody(req);
    if (body && Array.isArray(body.messages) && body.messages.length && typeof body.cwd === 'string' && body.cwd.trim()
      && !(await importedSessionCwdAllowed(body.cwd, await readConfig()))) {
      return send(res, apiFailure('session.import_cwd_not_allowed', {}, 'imported session cwd must be a configured workspace (or a subfolder of one)', 400));
    }
    // 121-K3(§4.1「来源三值」):这条路由就是【用户自己按下「新会话」】那一下,来源恒为 'user'。
    // 显式钉死而不是把 body 整份透传:createSession 现在认 origin 参数,透传等于让任意调用方
    // 把自己的普通会话刷成「管家开的」—— 那正是 02 把 origin 挡在 PATCH 白名单外要防的同一件事,
    // 只挡 PATCH 不挡建会话是把门修在窗户旁边。管家族那两条路径自己传 'steward'(13k)。
    return send(res, json({ ok: true, session: await createSession({ ...(body && typeof body === 'object' ? body : {}), origin: 'user' }) }));
  }
  // Bulk history cleanup is intentionally narrower than the single-session DELETE endpoint: it only
  // clears unpinned sessions and can preserve the currently open session supplied by the UI.
  if (req.method === 'POST' && pathname === '/api/sessions/bulk-delete') {
    const body = await readJsonBody(req);
    return send(res, json(await bulkDeleteUnpinnedSessions({
      preserveSessionId: body && body.preserveSessionId,
      purgeAssociated: Boolean(body && body.purgeAssociated),
    })));
  }
  // 135c(用户 2026-09-23「会话内的后台任务进度」;拍板:只在对应线程里显示、跑完即消失、能停但先确认、
  // 别的线程只在左栏打一个小标记)。四条路由,都排在下面 '/api/sessions/' 通配分支之前(否则
  // 'background' 会被当成会话 id)。修前后台命令【没有任何 HTTP 读口】—— 只有模型自己的 shell_* 工具看得见。
  //   GET  /api/sessions/background-counts      各线程在跑的后台件数(左栏标记用;只有计数,不带内容)
  //   GET  /api/sessions/:id/background         这条线程在跑的后台任务:后台命令 + 后台子代理 + 班组
  //   GET  /api/sessions/:id/background/output  某条后台命令的最近输出(过 redact)
  //   POST /api/sessions/:id/background/stop    停一件:命令走 shellKill(认主),子代理/班组走既有 stop 动作
  if (req.method === 'GET' && pathname === '/api/sessions/background-counts') {
    if (!tokenOk(req)) return send(res, apiFailure('auth.token_invalid', {}, 'missing or invalid workbench token', 403));
    const shells = EventStreamHooks.backgroundShells;
    const counts = shells ? shells.counts() : {};
    for (const row of sessionBackgroundRunRows(null)) counts[row.sessionId] = (counts[row.sessionId] || 0) + 1;
    return send(res, json({ ok: true, counts }));
  }
  {
    const bg = /^\/api\/sessions\/([^/]+)\/background(\/output|\/stop)?$/.exec(pathname);
    if (bg) {
      if (!tokenOk(req)) return send(res, apiFailure('auth.token_invalid', {}, 'missing or invalid workbench token', 403));
      const sid = safeSessionId(safeDecodeURIComponent(bg[1]));   // 坏编码(%zz)→ null → 400,不再 URIError 500
      if (!sid) return send(res, apiSessionIdInvalid());
      if (req.method === 'GET' && !bg[2]) {
        const shells = EventStreamHooks.backgroundShells;
        const items = (shells ? shells.rows(sid) : []).concat(sessionBackgroundRunRows(sid));
        items.sort((a, b) => String(a.startedAt).localeCompare(String(b.startedAt)));
        return send(res, json({ ok: true, sessionId: sid, items }));
      }
      if (req.method === 'GET' && bg[2] === '/output') {
        const shellId = new URL(req.url, 'http://x').searchParams.get('shellId') || '';
        const shells = EventStreamHooks.backgroundShells;
        const out = shells ? shells.outputTail(sid, shellId, 8000) : null;
        if (!out) return send(res, json({ ok: false, error: 'background command not found' }, 404));
        return send(res, json({ ok: true, ...out }));
      }
      if (req.method === 'POST' && bg[2] === '/stop') {
        const body = await readJsonBody(req);
        const taskId = String((body && body.id) || '');
        if (taskId.startsWith('shell:')) {
          const shells = EventStreamHooks.backgroundShells;
          const result = shells ? await shells.stop(sid, taskId.slice(6)) : { ok: false };
          logEvent({ kind: 'background_task_stop', sessionId: sid, taskId, ok: result.ok === true, by: 'user' });
          return send(res, json(result.ok ? { ...result, state: 'stopped' } : { ...result, ok: false, error: result.error || 'background command not found' }, result.ok ? 200 : result.cleanupIncomplete ? 409 : 404));
        }
        if (taskId.startsWith('run:')) {
          const result = await agentRunActionCommand({ sessionId: sid, runId: taskId.slice(4), action: 'stop' });
          logEvent({ kind: 'background_task_stop', sessionId: sid, taskId, ok: result.status === 200, by: 'user' });
          return send(res, json(result.body, result.status));
        }
        return send(res, json({ ok: false, error: 'unknown background task id' }, 400));
      }
      return send(res, json({ ok: false, error: 'method not allowed' }, 405));
    }
  }
  // 单条会话的 GET / PATCH / DELETE 只认 /api/sessions/<一段>。修前是 startsWith + path.basename(pathname):
  // /api/sessions/随便/什么/<id> 与 /api/sessions/<id>/ 都被当成 <id> —— 同一条会话有无数个别名(DELETE 也吃),
  // 以后再加 /api/sessions/:id/xxx 子路由时稍不留神就被这里先吞掉。其余形状落到路由末尾的 api.route_not_found。
  const single = pathname.match(/^\/api\/sessions\/([^/]+)$/);
  if (single) {
    // 与后台任务那几条同一个解码口径:坏编码(%zz)→ '' → 下面各分支按不合形的 id 处理(404 / 400)。
    const id = safeDecodeURIComponent(single[1]) || '';
    if (req.method === 'GET') {
      if (!safeSessionId(id)) return send(res, apiSessionNotFound());   // 不合形/保留名(01 safeSessionId)不可能是一条会话
      // Mapping expiry/import/revocation may change a user-facing copy without a
      // canonical session write. Such sessions must not reuse canonical HTTP/delta
      // cache proofs. Fresh OFF sessions retain the original fast paths.
      const displayPrivate = Boolean(await PrivacyGateway.displayCacheKey(id));
      const displayReply = async (envelope, headers = {}) => send(res, json(await PrivacyGateway.displayEnvelope(id, envelope), 200, headers));
      // 条件 GET(perf):这条路由每 3 s(直播回合)/ 5–30 s(管家抽屉)被轮询一次,而 loadSession 要读整份头 + 两个
      // 正文并逐行 sha1(18 MB 会话 250–350 ms;逐行 sha1 后来去掉了,见 02 sessionBodyState)。ETag 在【装载之前】用「头文件内容哈希 + 两个正文的大小 + 后台任务账本 +
      // 内存覆盖表 + 内存活态」算出,与 If-None-Match 相等就直接 304,连会话都不装载。取样顺序有讲究:盘上的戳在装载【之前】取,
      // 装载期间若有写者落盘,下一次比对必然不等 → 只会多回一次 200,绝不会拿旧标签配新内容(只可能多刷新,不会漏刷新)。
      // 内存活态在 200 体里现算(与体里放的东西同一份取样);304 判定用装载前的取样:活态没变才相等。
      // providerHistory 仍在 200 体里:大量 e2e 与外部脚本从这条路由读它(前端虽不读,也不删 —— 断言只加不改)。
      const sinceRaw = id === STEWARD_SESSION_ID ? new URL(req.url, 'http://x').searchParams.get('since') : null;
      // perf(前端长会话):?fromIndex=N&prefixStamp=S —— 经典壳在自己起的回合收尾时只要 messages[N..]。S 是 02 sessionMessagesStamp
      // 给出的前缀戳(回合起点那条 session 事件上带着);服务端对【此刻要下发的】前 N 条重算一遍,相等才回尾巴,否则(历史被改写过、
      // N 超长、参数是垃圾)回与不带参数时逐字节相同的全量体。与 since 互斥(since 优先,管家会话的尾巴切片语义不动)。
      const deltaQuery = sinceRaw == null ? new URL(req.url, 'http://x').searchParams : null;
      const deltaFromRaw = deltaQuery ? deltaQuery.get('fromIndex') : null;
      const deltaStampRaw = deltaQuery ? deltaQuery.get('prefixStamp') : null;
      const deltaKey = !displayPrivate && (deltaFromRaw != null || deltaStampRaw != null) ? [deltaFromRaw, deltaStampRaw] : null;
      // perf(前端长会话):?view=live —— 经典壳看「别处起的回合」时每条 thread.live 推送(约 1 次/秒)来一发,只读信封上的在跑部分
      // (liveTail / liveTurn / relay / resumable.live)。修前每发都整份装载并下发全部历史(2000 条消息约 7.7 MB)。
      // 真有活回合时只读会话头、回轻量信封(view:'live',session 只带几个标量,不是完整会话);没有活回合就落回下面的全量路径
      // —— 回合刚收尾的那一拍前端正要把整份会话换上来,拿到的就是它。不带 view 的调用逐字节不变。
      if (sinceRaw == null && new URL(req.url, 'http://x').searchParams.get('view') === 'live') {
        const liveParts = sessionEnvelopeLiveParts(id);
        const head = liveParts.live ? await readSessionHeadResilient(id) : null;
        if (head && typeof head === 'object') {
          const { liveTail, liveTurn, relay, execution, executionObservation } = liveParts;
          const turnSeq = Math.max(0, Number(head.turnSeq) || 0);
          const count = (n, list) => (Number.isInteger(n) ? n : (Array.isArray(list) ? list.length : 0));
          const historyLength = count(head.providerHistoryCount, head.providerHistory);
          return displayReply({
            ok: true, view: 'live', execution, executionObservation,
            session: { id, updatedAt: String(head.updatedAt || ''), turnSeq, messageCount: count(head.messageCount, head.messages), providerHistoryCount: historyLength },
            resumable: { dangling: false, kind: null, turnSeq, historyLength, live: true },
            ...(liveTail ? { liveTail } : {}), ...(liveTurn ? { liveTurn } : {}), ...(relay ? { relay } : {}),
          }, { 'cache-control': 'no-store' });
        }
      }
      // 审查轮:活态在盘上戳【之前】取。反过来(先戳后活态)时,两次取样之间「落盘 + 活态翻转」可能拼出一个等于客户端手上旧标签的
      // 组合(旧盘 + 新活态),回一次不该回的 304;先取活态,竞态最多多回一次 200。
      const preLive = sessionEnvelopeLiveParts(id);
      const envelopeStamp = await sessionEnvelopeStamp(id);
      if (envelopeStamp && !displayPrivate) {
        const preEtag = sessionEnvelopeEtag(id, envelopeStamp, preLive, sinceRaw, deltaKey);
        if (pretenderNotModified(req, preEtag)) return send(res, { status: 304, headers: { etag: preEtag, 'cache-control': 'no-store' }, body: '' });
      }
      const notFound = () => send(res, id === STEWARD_SESSION_ID ? json({ ok: true, execution: sessionExecutionSnapshot(id), executionObservation: sessionExecutionObservation(id), session: { id: STEWARD_SESSION_ID, messages: [] }, resumable: null, displayTitle: '', created: false }) : apiSessionNotFound()); // 管家会话懒创建:首个管家回合落盘前回空历史(created:false),不再每次加载页面都在控制台留一条 404;别的会话照旧 404
      // perf(增量取):带 fromIndex/prefixStamp 的请求先用「不读 provider 正文」的装载视图(02 SESSION_LOAD_OMIT_PROVIDER:
      // 前提拿不准它自己就是一次完整装载)。前缀戳对不上 = 要回全量,全量体里有 providerHistory,于是换一份完整装载再往下走。
      let session = await loadSession(id, 0, 0, deltaKey ? SESSION_LOAD_OMIT_PROVIDER : null);
      if (!session) return notFound();
      let delta = null;
      if (deltaKey) {
        const omitted = sessionOmittedProviderHistory(session);
        delta = sessionMessagesDelta(session.messages, deltaFromRaw, deltaStampRaw, omitted ? omitted.body : null);
        if (!delta && omitted) {
          session = await loadSession(id);
          if (!session) return notFound();
        }
      }
      // v0.8-S0 A6: surface whether the last turn dangles (arrested mid-flight) so the UI can offer resume.
      // 运行中豁免:活回合/活 agent run 在跑时,providerHistory 尾部恰好就是 detectDanglingTurn
      // 判悬挂的形状(user 尾/tool 尾/未答 tool_calls)——切到还在正常跑的会话不能弹「未正常结束」
      // 横幅,故 live 会话直接返回不悬挂。
      const liveParts = sessionEnvelopeLiveParts(id);
      const { live, liveTail, liveTurn, relay, execution, executionObservation } = liveParts;
      // 200 体的标签:盘上戳是装载前取的(见上),内存活态是这一刻取的;没有戳(读不到头/正文)就不发 ETag,照旧无条件全量。
      const envelopeHeaders = displayPrivate ? { 'cache-control': 'no-store' }
        : envelopeStamp ? { etag: sessionEnvelopeEtag(id, envelopeStamp, liveParts, sinceRaw, deltaKey), 'cache-control': 'no-store' } : {};
      // 117l-A1-fix2(§11.9;B1 实现抽屉时发现,主会话核对源码):抽屉 steward-drawer.js 的
      // isLive() 第一判据是 `resumable && resumable.live === true`,而这个活回合分支修前没有
      // `live` 键,那条判据从没走通过,一直静默回落到「事项行五态 === 'running'」——挂在
      // request_user_input 上等答案的回合五态是 needs_you,于是被判成不在跑,抽屉的轮询节拍
      // (活 5s／闲 15s)与 activitySnapshot 都跟着错。只加这一个键;detectDanglingTurn 那一支
      // (真正判悬挂的形状)一个字不动。
      const resumable = live
        ? { dangling: false, kind: null, turnSeq: Math.max(0, Number(session.turnSeq) || 0), historyLength: sessionProviderHistoryLength(session), live: true }
        : detectDanglingTurn(session);
      // 116-4（27 号文 §11.7 第 3 项「唤醒链诚实」）：GET /api/sessions/steward?since=<ISO> 只回
      // 该时刻【之后】的消息。117b 的轮询发现 state.lastReply.at 变了（trigger:'inbox'）之后要把新
      // 回合追加进对话流，整份拉一遍管家会话在长会话上是几百 KB 的重复载荷。
      // 纪律：① 只对管家会话生效 —— 别的会话有自己的分页语义，不在本波范围；② 不带 since 的旧调用
      // 逐字节不变（没有这个参数就走原路，一行都不改）；③ 只切 messages 的尾巴，其余字段原样带出，
      // 前端拿到的仍是同一个形状；④ 不改会话对象本身（浅拷贝），loadSession 的返回值不许被路由改写。
      const sinceMs = sinceRaw ? Date.parse(String(sinceRaw)) : NaN;
      if (Number.isFinite(sinceMs)) {
        const all = Array.isArray(session.messages) ? session.messages : [];
        const tail = all.filter(m => {
          const at = Date.parse(String((m && m.createdAt) || ''));
          return Number.isFinite(at) && at > sinceMs;
        });
        return displayReply({ ok: true, execution, executionObservation, session: { ...session, messages: tail }, resumable, since: String(sinceRaw), messageCount: all.length, ...(liveTail ? { liveTail } : {}), ...(liveTurn ? { liveTurn } : {}) }, envelopeHeaders);
      }
      // 增量取:前缀戳对得上才回尾巴。信封与全量同形(同一组键、同一份 resumable/displayTitle/活态),只有三处不同 ——
      // session.messages 只是 messages[N..];session 上不带 providerHistory(前端从不读它,全量里照旧有);信封上多
      // messagesFrom(= N,客户端据此拼接)/ messageCount(整份条数,客户端拼完自检)/ messagesStamp(整份的新戳,可接着再增量)。
      // 对不上就什么都不做,落到下面的全量 —— 标签里带着参数,所以同一状态下全量与增量的标签不同,304 各认各的。
      // (delta 在装载之后就算好了,见上。)
      if (deltaKey) {
        if (delta) {
          const { providerHistory: _providerHistory, ...sessionHead } = session;
          return displayReply({
            ok: true, execution, executionObservation, session: { ...sessionHead, messages: delta.tail }, resumable, displayTitle: sessionDisplayTitle(session),
            messagesFrom: delta.from, messageCount: delta.count, messagesStamp: delta.stamp,
            ...(liveTail ? { liveTail } : {}), ...(liveTurn ? { liveTurn } : {}), ...(relay ? { relay } : {}),
          }, envelopeHeaders);
        }
      }
      // 116-5b(§11.8.5):这条线程该显示什么名字,由 02 的 sessionDisplayTitle 一处判定。
      // 放在【信封】上而不是往 session 里塞:session 就是会话头本身,路由不许改写它的形状
      // (上面 since 分支那条「不改会话对象本身」是同一条纪律);抽屉/「现在这一件」的标题读这个键。
      return displayReply({ ok: true, execution, executionObservation, session, resumable, displayTitle: sessionDisplayTitle(session), ...(liveTail ? { liveTail } : {}), ...(liveTurn ? { liveTurn } : {}), ...(relay ? { relay } : {}) }, envelopeHeaders);
    }
    if (req.method === 'PATCH' || (req.method === 'POST' && req.headers['x-http-method'] === 'PATCH')) {
      const body = await readJsonBody(req);
      // 116-3 A2:管家会话不是线程 —— 它没有权限档、没有标题重命名语义,元数据一律不许经这条通用
      // 路由改(GET 保留:117c 的历史渲染要读它)。与 10 的回合入口那道门同一条纪律:管家会话的写面
      // 只有管家运行器自己。
      if (id === STEWARD_SESSION_ID) {
        return send(res, apiFailure('steward.forbidden', {}, 'the steward session cannot be patched through /api/sessions', 403));
      }
      if (!safeSessionId(id)) return send(res, apiSessionNotFound());
      // 116-2a(27 号文 §3.3/§8.6「每条线程一个权限 chip、点开即换、立即生效」):线程级权限就地快切。
      // 与 engineRoute 同端点、同风格(它是会话级字段的既有先例)。两道门:
      //   ① 白名单 —— 非 PERMISSION_MODES 的值 400,绝不悄悄回落(用户按了一个档,系统却按另一个档跑,
      //      是第 78 波注释里点名的那类事故);null/'' 是【合法】的,意思是「清除会话级设置,回落全局」。
      //   ② 二次确认 —— 切到全自动必须显式 confirm:true,否则 409。这是 §8.6 那条弹窗要求的服务端一半:
      //      服务端不能只信 UI 弹过窗,任何调用方(脚本/117 壳/未来的管家 UI)都得过这道门。
      //      收紧与清除不需要确认。
      if (body && Object.prototype.hasOwnProperty.call(body, 'permissionMode')) {
        const requested = body.permissionMode == null ? '' : String(body.permissionMode);
        if (requested !== '' && !PERMISSION_MODES.includes(requested)) {
          return send(res, apiFailure('session.invalid_permission_mode', { permissionMode: requested, allowed: PERMISSION_MODES },
            `permissionMode must be one of ${PERMISSION_MODES.join('/')}, or null/"" to follow the global default`, 400));
        }
        if (PERMISSION_MODES_REQUIRING_CONFIRM.includes(requested) && body.confirm !== true) {
          return send(res, apiFailure('permission.confirm_required', { permissionMode: requested },
            'switching a thread to full-auto requires an explicit confirm:true (it can change files and run commands while you are away)', 409));
        }
      }
      // 117z-E2b 提交②(27 号文 §11.21.7 债 ②):给线程开桌面工具是与「切全自动」同一道门的另一种口径 ——
      // 修前只有 permissionMode 要 confirm:true,`desktopTools:true` 直接过。严格只看 === true:false / null /
      // '' / 不带键都是收紧或清除,与 permissionMode 那条一样不需要确认。错误码沿用同一个,前端一处分支。
      if (body && body.desktopTools === true && body.confirm !== true) {
        return send(res, apiFailure('permission.confirm_required', { desktopTools: true },
          'giving a thread desktop tools requires an explicit confirm:true (it can see your screen and press keys while you are away)', 409));
      }
      const session = await updateSessionMeta(id, body);
      if (!session) return send(res, apiSessionNotFound());
      const patchedConfig = await readConfig();
      // 审计:权限档是安全面,每一次改动都要能事后对账(谁、哪条线程、从哪档到哪档、生效档是什么)。
      if (body && Object.prototype.hasOwnProperty.call(body, 'permissionMode')) {
        logEvent({
          kind: 'session', source: 'permission_mode', sessionId: id,
          permissionMode: sessionMeta(session).permissionMode,
          effectivePermissionMode: resolvePermissionMode({ session, config: patchedConfig }),
          confirmed: body.confirm === true,
        });
      }
      // 117z-E2b 提交②:桌面工具的会话级覆盖同样是安全面,照 permission_mode 那条的形状记一行
      //(哪条线程、写成了什么、是不是带 confirm 来的)。desktopTools 读的是落盘后的三态(true/false/null)。
      if (body && Object.prototype.hasOwnProperty.call(body, 'desktopTools')) {
        logEvent({
          kind: 'session', source: 'desktop_tools', sessionId: id,
          desktopTools: sessionDesktopToolsOf(session),
          confirmed: body.confirm === true,
        });
      }
      // 既有形状只加不改:`session` 原样保留(既有断言与前端都读它),额外带一份 sessionMeta —— 它是
      // 权限 chip 要的两个字段(会话级 permissionMode / 派生 effectivePermissionMode)的唯一读形。
      return send(res, json({ ok: true, session, sessionMeta: sessionMeta(session, patchedConfig) }));
    }
    if (req.method === 'DELETE' || (req.method === 'POST' && req.headers['x-http-method'] === 'DELETE')) {
      // 列表只发布 safeSessionId 合法的 id(02 重建索引的判据),不合法的 id 不可能是一条会话:先回 400,
      // 不再对它跑 stopSession / revokeAllGrants / 一串 unlink,再回一个假的 ok:true。
      if (!safeSessionId(id)) return send(res, apiSessionIdInvalid());
      return send(res, json(await deleteSession(id)));
    }
  }
  return false;
}

// ============================================================================
// 第70波(EC-E Mission Ready 首切片):/api/missions 聚合只读投影。
// 纪律:①纯读模型 —— 不复制第二套执行状态机,快照全部从既有权威源(mission 账本 / run 快照 /
// checkpoint journal / usage 月度账本 / 内存 pending 注册表)现算;②旧会话适配只读派生(sessionKind),
// 绝不回写磁盘;③列表只读会话头文件(<id>.json 含 mission,不触 messages/provider 正文),详情才全量加载。
// ============================================================================

// 卡片/快照共用的状态派生:complete(全部里程碑 done) > active(until-done 驱动中) > paused(supervised =
// 预算耗尽/停滞/用户接管后的待命态) > idle(off 且未完成)。mission 缺失时不应出现在任务列表('none')。
function missionCardStatus(m) {
  if (!m) return 'none';
  const ms = Array.isArray(m.milestones) ? m.milestones : [];
  if (ms.length > 0 && ms.every(x => x && x.status === 'done')) return 'complete';
  if (m.autoMode === 'until-done') return 'active';
  if (m.autoMode === 'supervised') return 'paused';
  return 'idle';
}

// 未决事项统一读形(第71b:四源统一 —— permission/question/plan/pool 全部从 session.interventions NDJSON 现算)。
// 前三者此前是纯内存 Map(04-permission-runtime:191/194/199),重启即归零;71 波旁路持久化为 Intervention(02
// append-only NDJSON),重启终态化(markInterruptedInterventions)后 pending 标 cancelled_restart -> 计数归零。
// 71b 池提案统一进来:paused run 的提案恢复后仍可审批,boot 对账补登记 + markInterruptedInterventions 按 run
// 状态分流保留 pending(见 02/08);run 快照扫描仅作并集兜底(append 落盘延迟 + 对账前存量),按 id 去重不双计。
async function missionPendingCounts(sessionId, runs, interventions) {
  const ivs = Array.isArray(interventions) ? interventions : await readInterventions(sessionId).catch(() => []);
  let permissions = 0, questions = 0, plans = 0, pool = 0;
  const poolPendingIds = new Set();
  for (const iv of ivs) {
    if (!iv || iv.status !== 'pending') continue;
    if (iv.type === 'permission') permissions++;
    else if (iv.type === 'question') questions++;
    else if (iv.type === 'plan') plans++;
    else if (iv.type === 'pool') { pool++; poolPendingIds.add(String(iv.id)); }
  }
  for (const r of (runs || [])) for (const item of ((r && r.taskPool) || [])) {
    if (item && item.status === 'proposed' && !poolPendingIds.has(String(item.id))) { pool++; poolPendingIds.add(String(item.id)); }
  }
  return { permissions, questions, plans, pool };
}

function clipMissionRunText(value, max = 360) {
  return String(value || '').replace(/\s+/g, ' ').trim().slice(0, max);
}

function lastMissionRunProgress(node) {
  const rows = Array.isArray(node && node.progressLog) ? node.progressLog : [];
  for (let index = rows.length - 1; index >= 0; index--) if (rows[index]) return rows[index];
  return null;
}

// 第82波班组图只消费这份精简节点投影。节点结果、角色快照、工具证据等大字段仍留在 Agent Run
// 权威文件；Mission 详情只带画图和递话资格所需事实，避免复制运行状态机或把 24KB result 带进任务单。
function missionRunGraph(src, live) {
  const nodes = Array.isArray(src && src.nodes) ? src.nodes : [];
  // 第98波(P5-A):真实调度波次 -- 按并发上限+wait 模拟派发,下发给前端班组图分列(替代纯拓扑层)。
  const waveSeq = computeWaveSeq(nodes, {
    concurrency: Number(src && src.concurrency) || 1,
    isWaitNode: n => !!(n && n.wait),
  });
  return {
    nodes: nodes.map(node => {
      // Read backwards instead of cloning/filtering a potentially long progress history on every Preview poll.
      const progress = lastMissionRunProgress(node);
      const eligibility = live
        ? nodeDeliveryEligibility(src, String(node && node.id || ''), { allowClaude: true })
        : { ok: false, reason: 'not_live' };
      return {
        id: String(node && node.id || ''),
        status: String(node && node.status || ''),
        roleId: String(node && (node.roleId || node.role) || ''),
        roleLabel: clipMissionRunText(node && node.roleLabel, 80),
        task: clipMissionRunText(node && node.task, 520),
        dependsOn: Array.isArray(node && node.dependsOn) ? node.dependsOn.map(value => String(value || '')).filter(Boolean).slice(0, 16) : [],
        engine: String(node && node.engine || ''), model: clipMissionRunText(node && node.model, 100),
        progress: clipMissionRunText(progress && progress.text, 220),
        startedAt: String(node && node.startedAt || ''), completedAt: String(node && node.completedAt || ''),
        fromPool: node && node.fromPool === true, proposedBy: String(node && node.proposedBy || ''),
        deterministic: Boolean(node && node.gate && ['vote', 'dedupe', 'coverage', 'propagate'].includes(node.gate.mode)),
        steerable: eligibility.ok === true, steerReason: String(eligibility.reason || ''),
        ...(waveSeq.has(String(node && node.id || '')) ? { wave: waveSeq.get(String(node && node.id || '')) } : {}),
      };
    }),
    proposals: (Array.isArray(src && src.taskPool) ? src.taskPool : [])
      .filter(item => item && item.status === 'proposed')
      .map(item => ({
        id: String(item.id || ''), status: 'proposed', proposedBy: String(item.proposedBy || ''),
        task: clipMissionRunText(item.task, 520), reason: clipMissionRunText(item.reason, 220),
        roleId: String(item.roleId || ''),
        dependsOn: Array.isArray(item.dependsOn) ? item.dependsOn.map(value => String(value || '')).filter(Boolean).slice(0, 16) : [],
      })),
  };
}

// run 摘要投影(对齐 /api/agent-runs?view=digest 的标量集 + 用量字段;live run 以内存为准)。
// includeGraph 仅供单 Mission 详情使用；300 Mission 列表和 75c 索引继续保持标量热路。
function missionRunDigest(r, includeLive = true, includeGraph = false) {
  const live = includeLive ? activeAgentRuns.get(r.id) : null;
  const mem = live && live.run ? live.run : null;
  const src = mem || r;
  const digest = {
    id: src.id, status: src.status, eventSeq: Number(src.eventSeq) || 0,
    createdAt: src.createdAt || '', updatedAt: src.updatedAt || '', completedAt: src.completedAt || '',
    nodeCount: Array.isArray(src.nodes) ? src.nodes.length : 0,
    poolPending: ((src.taskPool) || []).filter(p => p && p.status === 'proposed').length,
    live: !!live, paused: !!(live && live.paused), resumeTier: src.resumeTier || '',
    health: agentRunHealth(src, !!live),
    totalTokens: Number(src.totalTokens) || 0, costUsd: Number(src.costUsd) || 0,
  };
  if (includeGraph) Object.assign(digest, missionRunGraph(src, live));
  return digest;
}

// 列表卡片:从会话头文件投影(头含 mission,见 saveSession 头/正文拆分)。
async function buildMissionCard(head, runs, opts = {}) {
  // 116-4 第 0 步（复现出来的根因）：kind 是 'mission' 但头上【没有】mission 容器的会话是
  // 真实形状 —— steward_thread_new 建线程时显式写 kind='mission'，mission 容器要等
  // /api/mission start 才有。修前这里 m.goal 直接读 null，而 buildPretenderSessionSlice 没有
  // try，rebuildPretenderIndexFull 的 Promise.all 整份 reject：GET /api/missions、/api/missions/<id>、
  // GET /api/interventions 全部 500，收件箱每轮 tick 抛 "Cannot read properties of null (reading 'goal')"
  // 三个源一起停摆 —— 这正是「线程跑完管家没被唤醒」的第一层根因。
  // missionCardStatus(null) 早就返回 'none'（故它仍收 m 而不是 mm，否则 {} 会变成 'idle'）——
  // 本函数其余部分本来就是按「可能没有 mission」写的，只有下面那一段漏了守卫。
  const m = head.mission;
  const mm = (m && typeof m === 'object') ? m : {};
  const ms = Array.isArray(mm.milestones) ? mm.milestones : [];
  return {
    // 117r-D1:kind 从写死的 'mission' 改成【如实】取 sessionKind(head)。修前唯一的调用面是
    // 13e「kind === 'mission' 才造卡片」,所以这个字面量恒等于真值;现在管家关心的速查线程也有卡片了,
    // 再写死就是撒谎。mission 会话(含 steward_thread_new 那种 kind='mission' 但没有 mission 容器的)
    // 走 sessionKind 仍然返回 'mission',既有行为逐字不变。
    // 117r-D5:这个字段的【消费者换了一批】。修前它是五态第一条分支的守卫入参(kind === 'quick_ask'
    // 就短路),所以谎报会让速查线程顶着「交办中/已收工」;修后五态不再读 kind(守卫改看
    // factsUnknown),它转而是「这条线程是什么」的唯一出处 —— 看板行上那枚速查徽标
    // (public/js/steward-board.js 读 row.kind)就靠它。谎报的后果从「状态说错」变成「身份说错」,
    // 如实取 sessionKind 这件事因此比修前更要紧,不是更松。
    sessionId: head.id, missionId: sessionMissionId(head), title: head.title || '', cwd: head.cwd || '', kind: sessionKind(head),
    // 121-K3(34 号文 §4.2):`kind` 与「这是不是一条速查线程」**从这一刀起不再是同一件事**。
    // 修前 13e 只给 mission 与【管家关心的】线程造卡片,于是「有卡片 + kind==='quick_ask'」恰好等价于
    // 「管家用 steward_quick_ask 开的速查线程」—— 117r-D5 那段注释就是建立在这个巧合上的。
    // K3 把索引口径放宽成 threadVisible 之后,用户自己在 2.0 里聊的普通会话也有卡片了,而 sessionKind
    // 对它们同样返回 'quick_ask'(第 70 波的「纯问答默认档」,那是【档位】不是【身份】)—— 巧合破了。
    // 所以身份单独给一格,判据与 13j 的 stewardQuickThread 逐字同源(头上有没有 stewardQuick 容器):
    // 速查线程是管家为了回答一个问题临时开的,普通会话不是,两者在同一个 kind 里区分不开。
    quick: !!(head.stewardQuick && typeof head.stewardQuick === 'object'),
    // 116-5b(§11.8.5):这条线程该显示什么名字,由 02 的 sessionDisplayTitle 一处判定(人起的 >
    // 生成的 > 原话),前端只读结果不再算一遍 —— 与本行已有的 stateLabel / missionTitle / wait.label
    // 同一条纪律(读模型里本来就有一批服务端算好的显示串)。title 保持原话不动。
    // brief 单独带出是为了那句 gist(名字之外还要一句人话概括,抽屉与搜索结果要用);缺席时不出现。
    displayTitle: sessionDisplayTitle(head),
    // 117l D4(§11.9):最后一句助手原话的头部(= head.summary,09 收尾处写的前 160 字,不经模型改写)。
    // 看板行的「它在问你」要判「末句是不是问号」,而 13e 的活叠加层只拿得到卡片 —— 没这一个字段就只能
    // 每行再读一次会话头。只是会话头已有字段的投影,不新增任何持久化来源。
    // **注意截断**:summary 只有 160 字,长回复的末句问号会被截掉 —— 漏报是安全的(不会把不是问句
    // 的说成问句),完整判定在 steward_thread_status(那里会话正文已装载)。
    lastSay: String(head.summary || ''),
    ...(sessionBriefOf(head) ? { brief: sessionBriefOf(head) } : {}),
    createdAt: head.createdAt || '', updatedAt: head.updatedAt || '',
    status: missionCardStatus(m),
    // 117p-S2(30 号文 §8.3):五态判据需要的两个卡片字段 —— 都只是会话头已有字段的投影,不新增
    // 持久化来源(与 lastSay / displayTitle 同一条纪律)。缺了它们,两份五态抄写件只能把 turnSeq
    // 硬编码成 0,于是「跑过回合但头上没有 mission 账本」的管家线程永远落不进 done/stopped。
    turnSeq: Math.max(0, Number(head.turnSeq) || 0),
    lastTurn: head.stewardLastTurn && typeof head.stewardLastTurn === 'object'
      ? { seq: Math.max(0, Number(head.stewardLastTurn.seq) || 0), ok: head.stewardLastTurn.ok !== false, aborted: head.stewardLastTurn.aborted === true }
      : null,
    activeTurn: opts.persistent ? false : activeChildren.has(head.id), // 75c:live overlay 不写进可重建持久索引
    ...(opts.persistent ? {} : { execution: sessionExecutionSnapshot(head.id) }),
    ...(opts.persistent ? {} : { queued: stewardThreadTurnQueued(head.id) }), // hunt3:排队中的回合,同上只活在叠加层
    mission: {
      goal: mm.goal || '', createdAt: mm.createdAt || '', updatedAt: mm.updatedAt || '',
      autoMode: mm.autoMode || 'off',
      milestonesTotal: ms.length,
      done: ms.filter(x => x && x.status === 'done').length,
      blocked: ms.filter(x => x && x.status === 'blocked').length,
      pending: ms.filter(x => !x || x.status === 'pending').length,
      budget: mm.budget || { maxAutoTurns: 0, maxTokens: 0 },
      spent: mm.spent || { autoTurns: 0, tokens: 0 },
      budgetExhausted: Boolean(mm.budgetExhaustedAt), budgetExhaustedAt: String(mm.budgetExhaustedAt || ''),   // 后者给管家收件箱当去重键:任务重启后再次用尽是新的一件事
      // 第72波:结果章存根(列表卡片只带状态+时间,明细走详情快照 result)
      result: (mm.result && typeof mm.result === 'object') ? { status: mm.result.status || '', finishedAt: mm.result.finishedAt || '' } : null,
    },
    pending: await missionPendingCounts(head.id, runs, opts.interventions),
    runCount: (runs || []).length,
    lastRun: runs && runs.length ? missionRunDigest(runs[runs.length - 1], !opts.persistent) : null,
    // Latest persisted run plus every live run: a healthy newer run cannot hide an older live fault.
    healthRuns: missionHealthRuns(head.id, runs, !opts.persistent),
  };
}

function missionHealthRuns(sessionId, runs, includeLive = true) {
  const latest = (Array.isArray(runs) ? runs : []).filter(run => run && run.id)
    .slice().sort((a, b) => String(b.createdAt || '').localeCompare(String(a.createdAt || '')) || String(b.id).localeCompare(String(a.id)))[0];
  const byId = new Map();
  if (latest) byId.set(latest.id, missionRunDigest(latest, includeLive));
  if (includeLive) for (const runtime of activeAgentRuns.values()) {
    const run = runtime && runtime.run;
    if (run && run.sessionId === sessionId) byId.set(run.id, missionRunDigest(run, true));
  }
  return [...byId.values()];
}

// ── 第 116 波 116g(27 号文 §3.1 / §8.10):事项级聚合读模型 ─────────────────────
// 一处装配,两处消费(GET /api/missions 的只加字段、13g 的 steward_missions 工具)。纪律与 70 波
// /api/missions 同源:**纯读模型** —— 线程五态取投影 card(与看板逐字节同源),事项级状态只经 06i 的
// `aggregateMissionState` 纯函数,绝不在这里另写一份判据;没有事项文件的 missionId 按需派生
// (`derived:true`,标题取会话标题),不落盘、不回写、不迁移。

// 02 事项容器的稳定信封 error -> HTTP 状态。事项/线程找不到是 404,容量满是 409(可重试的资源
// 约束,不是请求写错了),其余一律 400。表在这里而不在域侧:域函数不认识 HTTP。
function missionContainerHttpStatus(error) {
  if (error === 'not_found' || error === 'session_not_found') return 404;
  if (error === 'capacity_exceeded') return 409;
  return 400;
}
// 失败信封统一走 P2 的 apiFailure(code/params/message)—— 直接把 { ok:false, error:'字符串' } 送进
// json() 会被 normalizeApiErrorPayload 归一成 code:'api.request_failed',错误码就丢了。
const MISSION_FAILURE_PARAM_KEYS = ['limit', 'count', 'missionId', 'sessionId'];
function missionContainerFailure(result) {
  const params = {};
  for (const key of MISSION_FAILURE_PARAM_KEYS) if (result && result[key] !== undefined) params[key] = result[key];
  return apiFailure('mission.' + String((result && result.error) || 'failed'), params,
    String((result && result.message) || ''), missionContainerHttpStatus(result && result.error));
}

function emptyMissionCostBucket() {
  return { turns: 0, inTok: 0, outTok: 0, cachedInTok: 0, costsByCurrency: {} };
}
function addMissionCostBucket(bucket, usage) {
  if (!usage || typeof usage !== 'object') return bucket;
  bucket.turns += Number(usage.turns) || 0;
  bucket.inTok += Number(usage.inTok) || 0;
  bucket.outTok += Number(usage.outTok) || 0;
  bucket.cachedInTok += Number(usage.cachedInTok) || 0;
  for (const [currency, amount] of Object.entries(usage.costsByCurrency || {})) {
    if (!Number.isFinite(Number(amount))) continue;
    bucket.costsByCurrency[currency] = Math.round(((bucket.costsByCurrency[currency] || 0) + Number(amount)) * 1e6) / 1e6;
  }
  return bucket;
}

// 测试用确定性计数(不靠墙钟):workspaceComputed = 真正跑了一次「工作区归属判定」的次数(同 cwd 一次装配内只算一次)。
const missionAggregateStats = { workspaceComputed: 0 };
async function buildMissionAggregateRows(options = {}) {
  const includeArchived = options.includeArchived === true;
  // W7(用户 2026-09-24「管家需要把工作区和任务联系起来」):事项与线程的读模型把【工作区】带出去 ——
  // 只加字段。事项的工作区 = 事项容器记着的那个(13k 在事项第一次有了工作区时记下),没有就取组里
  // 最近动过的那条线程的目录。ruyiOwned 的判据单点在 06i 的 stewardRuyiOwnedPath(数据根里的、或如意
  // 为任务开的而用户没收编的),要配置里那张表 —— 调用方有现成的就传 options.config,省一次读盘。
  const wsConfig = (options.config && typeof options.config === 'object') ? options.config : await readConfig().catch(() => null);
  // 性能:2000 条线程只有寥寥几个不同的 cwd,而 stewardRuyiOwnedPath(逐字符归一 + 数据根前缀比较)与
  // dataRootAliases()(取数据根、比对别名)此前在【每条线程 + 每个事项组】各算一遍,一次 GET /api/missions
  // 约 4000 次,占去 37% CPU。本次装配内 wsConfig / paths.data / 别名都是定值,所以别名提到函数头只取一次,
  // 并按 cwd 记下 { name, ruyiOwned }(纯函数,同 cwd 同答案);每次仍返回【新对象】,调用方改它不会串行。
  const dataRootPath = paths.data;
  const dataRootAliasList = dataRootAliases();
  const workspaceMemo = new Map();   // 修剪后的 cwd -> { name, ruyiOwned }
  const workspaceOf = cwd => {
    const p = String(cwd || '').trim();
    if (!p) return null;
    let known = workspaceMemo.get(p);
    if (!known) {
      known = { name: path.basename(p.replace(/[\\/]+$/, '')) || p, ruyiOwned: stewardRuyiOwnedPath(p, wsConfig, dataRootPath, dataRootAliasList) };
      workspaceMemo.set(p, known);
      missionAggregateStats.workspaceComputed += 1;
    }
    return { path: p, name: known.name, ruyiOwned: known.ruyiOwned };
  };
  const overlayAt = nowIso();   // 一次装配只取一次「叠加时刻」:每行各取一次是 2000 次 Date + toISOString,而它们本就是同一个请求
  const index = await getPretenderProjectionIndex().catch(() => null);
  const slices = new Map(((index && index.sessions) || []).map(row => [row.sessionId, row]));
  const metas = await listSessions().catch(() => []);          // 管家会话已在 listSessions 里滤掉
  const containers = await listMissionContainers().catch(() => []);
  const containerById = new Map(containers.map(row => [row.missionId, row]));
  const byMissionId = new Map();

  const ensure = (missionId, container) => {
    let group = byMissionId.get(missionId);
    if (!group) byMissionId.set(missionId, group = { missionId, container: null, threads: [], cost: emptyMissionCostBucket() });
    if (container && !group.container) group.container = container;
    return group;
  };
  for (const container of containers) {
    if (container.archivedAt && !includeArchived) continue;
    ensure(container.missionId, container);
  }
  for (const meta of metas) {
    const missionId = meta.missionId || meta.id;
    const container = containerById.get(missionId) || null;
    if (container && container.archivedAt && !includeArchived) continue;
    const group = ensure(missionId, container);
    const slice = slices.get(meta.id) || null;
    const card = slice ? overlayMissionCard(slice, overlayAt) : null;
    // 五态的三条取值路径,与 13g steward_thread_status 逐字一致(同一条线程在看板与管家里必须同色):
    //   ① 有投影卡片 -> fromCard(与 /api/missions 的卡片同源);
    //   ② 没卡片但是 mission 会话(投影还没赶上这条新会话)-> 按会话头现算,入参与 thread_status 相同
    //      —— 少喂 turnSeq 会把一条跑过回合的线程说成「交办中」,和 thread_status 的「已停工」打架;
    //   ③ 其余会话(= 用户自己在经典 2.0 里聊的普通会话)-> 【刻意不读会话头】以省 I/O,
    //      所以这一支手上一条事实都没有,明说 factsUnknown:true 让判据短路成「事实未知」。
    //      117r-D5 之前这里靠的是 kind === 'quick_ask' 那条守卫,出参完全一样(仍是 quick_ask、
    //      聚合仍落 stopped),变的只是【为什么】短路 —— 从「它是速查」变成「我不知道它在干什么」。
    //      对应地:①支里的速查线程(D1 之后它有卡片、有事实)不再被这条守卫劫走,走完整五态。
    let derived;
    // 124 还债①（40 号文 §8.5 ①）：这条线程有没有【自己的验收账本】（`session.mission`）。
    // 判据与 13g `thread_status` / 13h 总览同一条：卡片侧 `card.status === 'none'` ⇔ 头上没有
    // mission 容器（§6-ter 的 `ledgerless` 写的就是这两句的两种写法），不许拿
    // `milestonesTotal === 0` 之类的近似顶替。
    // 第三支（普通会话）刻意不读会话头以省 I/O —— 而 mission 账本只可能挂在 mission 会话上，
    // 所以那一支恒为 false：这不是猜，是定义。
    let threadLedger = false;
    if (card) { derived = stewardThreadStateFromCard(card); threadLedger = String(card.status || '') !== 'none'; }
    else if (meta.kind === 'mission') {
      const head = await readMissionSessionHead(meta.id);
      threadLedger = !!(head && head.mission);
      // 会话头这一支与 13k thread_status / 13o 总览 / 13r 事件流同一个适配器(06i stewardThreadStateFromHead)。
      derived = stewardThreadStateFromHead(head, {
        kind: 'mission',
        pending: await missionPendingCounts(meta.id, [], null).catch(() => null),
        activeTurn: activeChildren.has(meta.id),
        runCount: 0,
      });
    } else derived = deriveStewardThreadState({ kind: 'quick_ask', factsUnknown: true });
    // 124 还债①：组级两个事实在这一处累计（前端不再自己推）——
    //   · anyLedger：组里任一条线程带账本；
    //   · anyMission：这一组里有真正的【事项线程】（未归类事项没有容器，只能靠它认出来）。
    group.anyLedger = group.anyLedger === true || threadLedger;
    group.anyMission = group.anyMission === true || meta.kind === 'mission';
    group.threads.push({
      sessionId: meta.id,
      title: stewardSanitizeText(meta.title || ''),
      // 116-5b:同 buildMissionCard —— title 仍是原话,显示名另给一个键(steward_missions 的线程清单、
      // 抽屉页签、看板行都读它)。meta 是索引条目形态(brief/titleSource),sessionDisplayTitle 两形态都认。
      displayTitle: stewardSanitizeText(sessionDisplayTitle(meta)),
      ...(sessionBriefOf(meta) ? { brief: sessionBriefOf(meta) } : {}),
      kind: meta.kind || 'quick_ask',
      state: derived.state,
      stateLabel: derived.label,
      permissionMode: meta.permissionMode || null,
      lastAssistantText: stewardSanitizeText(meta.summary || '').slice(0, 120),
      updatedAt: String(meta.updatedAt || ''),
      cwd: String(meta.cwd || ''),   // W7:这条线程开在哪个目录(事项的 workspace 从这里派生)
      workspace: workspaceOf(meta.cwd),
      // 116h(§8.10「排队可解释」):等待原因由 06i 的 waitReasonFor 单点判定,与 steward_thread_status /
      // 总览行 / steward_missions 同一函数同一形状。pending 用上面五态判据已经算好的那一份(少喂一次
      // 就会出现 116g 那种「看板与 thread_status 各说各话」);仲裁器一侧同步只读,开关关时恒为 null。
      wait: waitReasonFor(
        { pending: (derived.sources && derived.sources.pendingTotal) || 0 },
        typeof StewardHooks.arbiterWait === 'function' ? StewardHooks.arbiterWait(meta.id) : null,
      ),
    });
    addMissionCostBucket(group.cost, slice && slice.usage);
  }

  const rows = [];
  const rowBySessionId = new Map();
  for (const group of byMissionId.values()) {
    const container = group.container;
    const acceptanceItems = container ? container.acceptance : [];
    // 117s-A D1(§11.13 ③):组内线程改成「状态秩优先、其次 updatedAt 降序」。秩由 06i 的
    // stewardThreadStateRank 单点给(needs_you > running > dispatching > done/stopped),
    // 状态本身仍是上面那三条取值路径算出来的那一个 —— 这里【不】重新判定任何状态。
    // 末位补 sessionId 是为了确定性:两条线程秩与 updatedAt 都相同时,行序不该随 listSessions
    // 的目录枚举顺序漂移(夹具与 ETag 都指望同样的输入给同样的行序)。
    group.threads.sort((a, b) => stewardThreadStateRank(a.state) - stewardThreadStateRank(b.state)
      || String(b.updatedAt).localeCompare(String(a.updatedAt))
      || String(a.sessionId).localeCompare(String(b.sessionId)));
    const row = {
      missionId: group.missionId,
      // 未归类事项没有事项文件,标题只能从它唯一那条线程的会话标题派生(§3.1「不改写历史」)。
      // 116-5b:派生用的是那条线程的【显示名】而不是原话 —— 这个字段本来就是一个派生出来的显示串
      // (真事项走 container.title),不是权威数据;线程的原话仍在 threads[].title 里原样躺着。
      title: container ? container.title : ((group.threads[0] && (group.threads[0].displayTitle || group.threads[0].title)) || group.missionId),
      goal: container ? container.goal : '',
      derived: !container,
      archivedAt: (container && container.archivedAt) || '',
      cwd: container ? container.cwd : '',
      // W7:事项的工作区(见本函数头注)。cwd 仍是容器那一格的原值,语义一个字不改。
      workspace: workspaceOf((container && container.cwd)
        || ((group.threads.slice().sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt)))[0] || {}).cwd)),
      aggregateState: aggregateMissionState(group.threads.map(thread => thread.state)),
      threadCount: group.threads.length,
      threads: group.threads,
      acceptance: {
        done: acceptanceItems.filter(item => item.done).length,
        total: acceptanceItems.length,
        items: acceptanceItems,
        // ── 124 还债①（40 号文 §8.5 ①）：让【看板】也答得出「未记录验收」───────────────
        // 修前这一块只有 done/total/items 三个数，都来自事项容器。容器里的 done 按定义只可能是
        // 用户勾的，所以那条 a/b 单一来源、不会说谎 —— 但它**答不出「这一件压根没人记过验收」**：
        // `total === 0` 既可能是「记过、是空的」，也可能是「从来没记过」，看板只能两者都当没话说。
        // 详情路由（/api/missions/:id）走的是 02 的 buildMissionAcceptanceProjection，那边有
        // `ledger`；列表这一侧没有，于是抽屉说得出「未记录验收」而看板说不出。这两个键就是把
        // 同一套事实补到列表行上 —— **判据仍然只有前端 thread-facts.acceptanceRecorded 一处**，
        // 这里只负责把它需要的事实如实投影出来。
        //   · ledger  —— 组里【任一条】线程带自己的验收账本（`session.mission`）。组级口径：
        //     事项是按组显示的，组里只要有一条记过，这一件就不算「没人记过」。
        //   · tracked —— 这一组是不是【一件活】：有事项容器，或组里有 mission 线程（未归类事项
        //     没有容器文件，只能靠后者认出来）。
        //     为什么要它：左栏自 121-K3 放宽索引口径后大半是用户手工开的普通会话，它们的聚合态
        //     恒落 stopped、也从来没有验收记录 —— 不带这个门，「收工却没记过」会把整栏刷成等重
        //     灰字（§2.3「只在有话可说时出现」，正是 P1 当初刻意不碰看板的那条理由）。
        //     普通聊天会话本来就没有验收这回事，对它说「未记录验收」是噪声，不是诚实。
        ledger: group.anyLedger === true,
        tracked: Boolean(container) || group.anyMission === true,
      },
      budget: container ? container.budget : {},
      cost: group.cost,
      createdAt: container ? container.createdAt : ((group.threads[group.threads.length - 1] && group.threads[group.threads.length - 1].updatedAt) || ''),
      updatedAt: container ? container.updatedAt : ((group.threads[0] && group.threads[0].updatedAt) || ''),
    };
    rows.push(row);
    for (const thread of group.threads) rowBySessionId.set(thread.sessionId, row);
  }
  // 117s-A D1(§11.13 ③):组同规则 —— 状态秩优先、其次 updatedAt 降序。组的秩取【它自己的聚合态】
  // 的秩,而聚合态只经 06i 的 aggregateMissionState(上面已经算过一次,直接读 row.aggregateState);
  // 「组的秩 = 组内最高秩」这句话由 aggregateMissionState 的规则本身保证,不在这里另算一遍最大值
  // (any needs_you -> needs_you;非全 done 时 any running -> running;再 any dispatching;否则
  //  done/stopped 同落末档 —— 逐档与 stewardThreadStateRank 的秩一一对应)。
  rows.sort((a, b) => stewardThreadStateRank(a.aggregateState) - stewardThreadStateRank(b.aggregateState)
    || String(b.updatedAt).localeCompare(String(a.updatedAt))
    || String(a.missionId).localeCompare(String(b.missionId)));
  // 事项文件不在 75c 物化索引的 sourceStamp 覆盖面内(它们不是会话文件),所以 ETag 必须自己带上
  // 它们的指纹 —— 否则 PATCH 完验收项、再带 If-None-Match 来读会拿到 304 + 陈旧的 acceptance。
  // 117h 第 0 步:行上新增的 missionTitle / goal / acceptanceItems 都由容器字段直出,所以指纹要把
  // 它们一并纳入 —— 光靠 updatedAt 依赖「每次改都会动 updatedAt」这条隐含约定,写进指纹才是自证的。
  // 117s-A D1:行序自此由【状态秩】决定,而状态可以在 updatedAt 与容器字段都不动的情况下变
  //   (最典型的一条:活回合结束 -> activeTurn 由真变假 -> running 落 done,会话头那一刻并没有再写一次)。
  // 指纹不带秩的话,带 If-None-Match 来的下一拍会拿到 304 + 一份【旧顺序】的行 —— 与上面那条
  // acceptance 的教训同一个模具,所以把秩写进指纹,而不是依赖「状态变了 updatedAt 一定也变」。
  const stamp = pretenderHash([
    containers.map(row => [row.missionId, row.updatedAt, row.archivedAt || '', row.title || '', row.goal || '']),
    rows.map(row => [
      row.missionId, stewardThreadStateRank(row.aggregateState),
      row.threads.map(thread => [thread.sessionId, stewardThreadStateRank(thread.state)]),
      // W7:工作区也进指纹 —— ruyiOwned 随配置里那张表变,而会话头与容器都没动。
      row.workspace ? [row.workspace.path, row.workspace.ruyiOwned] : null,
    ]),
  ]);
  return { rows, rowBySessionId, stamp };
}

// /api/missions 的行是【线程行】(每个 mission 会话一张卡,70 波起如此,前端静态锁按它冻结)。
// 116g 只在每行【追加】它所属事项的聚合事实,既有字段与顺序一个不动。
function overlayMissionAggregateFields(card, row) {
  if (!card) return card;
  // row 缺失 = 这张卡片的会话在 listSessions 的元数据里没有对应行(索引与投影之间的瞬时偏斜)。
  // 退化成「只有它自己一条线程的未归类事项」,聚合态仍然只经 aggregateMissionState —— 绝不在这里
  // 按 card.status 另编一套判据(那就是第二个状态机)。
  // 116h(§8.10「排队可解释」):看板每一行都要能说出「它在等什么」。这一行就是那条线程自己的行,
  // 所以取聚合行里【它自己】那条线程的 wait(与 steward_missions / steward_thread_status 同源同形);
  // row 缺失的退化分支里现算一次,仍然只经 06i 的 waitReasonFor(不另编第二套判据)。
  const threadWait = row ? ((row.threads || []).find(thread => thread.sessionId === card.sessionId) || {}).wait || null : null;
  if (!row) {
    const derived = stewardThreadStateFromCard(card);
    return Object.assign(card, {
      aggregateState: aggregateMissionState([derived.state]),
      threadCount: 1,
      // 124 还债①：退化支（没有聚合行）也得如实说 —— 没有容器就没有容器验收项，
      // 账本与「是不是一件活」仍然只读卡片上那两条既有事实，不另编。
      acceptance: { done: 0, total: 0, ledger: String(card.status || '') !== 'none', tracked: String(card.kind || '') === 'mission' },
      budget: {}, cost: emptyMissionCostBucket(), derived: true,
      // 117h 第 0 步:没有聚合行 = 没有容器,事项标题就是这条线程自己的标题,目标与验收项如实为空。
      missionTitle: String(card.displayTitle || card.title || ''), goal: '', acceptanceItems: [],
      missionWorkspace: null,   // W7:没有聚合行就没有事项级工作区;这条线程自己的目录仍在 card.cwd
      wait: waitReasonFor(
        { pending: (derived.sources && derived.sources.pendingTotal) || 0 },
        typeof StewardHooks.arbiterWait === 'function' ? StewardHooks.arbiterWait(card.sessionId) : null,
      ),
    });
  }
  return Object.assign(card, {
    aggregateState: row.aggregateState,
    threadCount: row.threadCount,
    // 124 还债①：ledger / tracked 跟着 done/total 一起上行 —— 看板按组取【领头那一行】的
    // acceptance（groupRows 里 `acceptance: row.acceptance`），而这两个是组级事实，同组每一行都一样。
    acceptance: { done: row.acceptance.done, total: row.acceptance.total, ledger: row.acceptance.ledger === true, tracked: row.acceptance.tracked === true },
    budget: row.budget,
    cost: row.cost,
    derived: row.derived,
    // ── 117h 第 0 步(27 号文 §5 117h 行 / 117d 拍板①):看板要按【事项】分组显示,而事项容器的
    // 标题 / 目标 / 验收项此前只有 steward_missions 工具面拿得到 —— 117d 抽屉只能按确定性顺序
    // 回落到线程标题。这里【只加三个字段】,不加新路由、不动既有字段与顺序:
    //   · missionTitle:有容器就是容器标题;没有容器(derived 行,`未归类事项`)就是本行自己的标题;
    //   · goal        :容器目标,无容器为空串(不猜、不拿线程摘要冒充);
    //   · acceptanceItems:容器验收项整表(既有 acceptance 只有 done/total 两个数,画不出条目)。
    // 116-5b:derived 行的事项标题 = 这条线程自己的【显示名】(见 buildMissionAggregateRows 同款注释)。
    missionTitle: row.derived ? String(card.displayTitle || card.title || '') : String(row.title || ''),
    goal: String(row.goal || ''),
    acceptanceItems: Array.isArray(row.acceptance.items) ? row.acceptance.items : [],
    wait: threadWait,
    // W7:这条线程所属事项的工作区({path,name,ruyiOwned} 或 null)。只加字段;给 W4 的管家界面读。
    missionWorkspace: row.workspace || null,
  });
}

async function handleMissionsApiRoutes(req, res, pathname) {
  // 75c:列表走可删物化索引。冷读验证/重建权威源，热读只叠加 live overlay；cursor 携带 revision，
  // 跨页期间事实变化返回 409 snapshot_changed，绝不静默漏项/重复。
  if (req.method === 'GET' && pathname === '/api/missions') {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const index = await getPretenderProjectionIndex();
    // 116g:只加字段 —— 行仍然是【线程行】(每个 mission 会话一张卡),既有字段与顺序逐字节不变,
    // 追加的是这条线程所属【事项】的聚合事实(aggregateState/threadCount/acceptance/cost/budget/derived)。
    const aggregate = await buildMissionAggregateRows();
    const overlayAt = nowIso();   // 与聚合装配同理:整张列表共用一个叠加时刻,不再逐行取一次
    const missions = index.sessions.filter(row => row.card && String(row.sessionId || '') !== STEWARD_SESSION_ID)   // 走查 U3:管家自己的会话不是任务,不进左栏
      .map(row => overlayMissionAggregateFields(overlayMissionCard(row, overlayAt), aggregate.rowBySessionId.get(row.sessionId)));
    // 117s-A D1(§11.13 ③):看板正文读的就是这一份行序(steward-board.js 的 groupRows() 按
    // missionId 首次出现的先后定组序、组内按行序)—— 设计页只点了 buildMissionAggregateRows 里的
    // 那两处排序,但那一份是给 steward_missions 工具面消费的;**看板真正吃的是这一行**,所以三处
    // 一起改,否则「在跑的排最前」在工具面成立、在用户眼前的看板上不成立。
    // 排序键四段,一段都不能省:
    //   ① 组的秩(aggregateState;overlayMissionAggregateFields 两个分支都已挂上它);
    //   ② 组的 updatedAt 降序 —— 取【同组各行 updatedAt 的最大值】,与修前「组序由它最新的那条线程
    //      决定」逐字同义(修前没有显式组序,组序就是第一条落在组里的行的位置);
    //   ③ 组内线程的秩(从叠加过 live 层的卡片现算,与看板自己 MissionState.fromCard(row) 同源);
    //   ④ 线程 updatedAt 降序,末位 sessionId 兜确定性。
    // 一二段在前保证【组仍然是连续的】—— 少了它,一条 needs_you 的线程会把它所在的组劈成两半。
    const groupRank = new Map();     // missionId -> 组秩(取组内最小秩,即最高优先级)
    const groupUpdated = new Map();  // missionId -> 组内最大 updatedAt
    const threadRank = new Map();    // sessionId -> 线程秩
    for (const row of missions) {
      const mid = String(row.missionId || row.sessionId || '');
      const rank = stewardThreadStateRank(stewardThreadStateFromCard(row).state);
      threadRank.set(String(row.sessionId || ''), rank);
      const own = stewardThreadStateRank(row.aggregateState);
      groupRank.set(mid, Math.min(groupRank.has(mid) ? groupRank.get(mid) : own, own));
      const at = String(row.updatedAt || '');
      if (!groupUpdated.has(mid) || at > groupUpdated.get(mid)) groupUpdated.set(mid, at);
    }
    const gid = row => String(row.missionId || row.sessionId || '');
    missions.sort((a, b) => (groupRank.get(gid(a)) - groupRank.get(gid(b)))
      || String(groupUpdated.get(gid(b))).localeCompare(String(groupUpdated.get(gid(a))))
      || String(gid(a)).localeCompare(String(gid(b)))
      || (threadRank.get(String(a.sessionId)) - threadRank.get(String(b.sessionId)))
      || String(b.updatedAt).localeCompare(String(a.updatedAt))
      || String(a.sessionId).localeCompare(String(b.sessionId)));
    // ?sessionIds=a,b,c:只要这几条的卡片(侧栏搜索命中了、但不在它已经取到的那一页里的会话 —— 左栏只取最新
    // 200 条,修前更早的会话搜得到也显示不出来)。只认合形的 id,最多 60 条;不分页、不参与 304。
    const wanted = String(new URL(req.url, 'http://x').searchParams.get('sessionIds') || '').split(',').map(id => safeSessionId(id.trim())).filter(Boolean).slice(0, 60);
    if (wanted.length) {
      const set = new Set(wanted);
      return send(res, json({ ok: true, missions: missions.filter(row => set.has(String(row.sessionId || ''))), projectionRevision: index.missionsRevision }));
    }
    const paged = paginatePretenderProjection(req, 'missions', index.missionsRevision, missions);
    if (paged.response) return send(res, paged.response);
    // 用量修订号挂在【最后】一段:前面三段(修订号 - 在场覆盖 - 行指纹)的段位有测试按位读(steward-thread-order ⑪)。
    const etag = pretenderEtag('missions', index.missionsRevision + '-' + pretenderLiveOverlayRevision() + '-' + aggregate.stamp + '-' + (index.missionsUsageRevision || ''), paged.page);
    if (pretenderNotModified(req, etag)) return send(res, { status: 304, headers: { etag }, body: '' });
    return send(res, json({
      ok: true,
      missions: paged.items,
      page: paged.page,
      nextCursor: paged.page.nextCursor,
      projectionRevision: index.missionsRevision,
      index: pretenderIndexMeta(index),
    }, 200, { etag }));
  }
  // ── 第 116 波 116g(27 号文 §3.1):事项容器的写面。五条路由,全部 token 门(01b 的
  // `POST /api/missions` 与 `PATCH /api/missions/` 两条新登记 + 既有 `POST /api/missions/` 前缀条)。
  // 幂等一律靠子操作本身幂等(attach/detach/去重/归档),不靠"是否做过"的标记位 —— 标记位会在
  // 崩溃窗口里说谎,幂等的子操作不会。
  if (req.method === 'POST' && pathname === '/api/missions') {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const body = await readJsonBody(req);
    const result = await createMissionContainer(body || {});
    return send(res, result.ok ? json(result, 201) : missionContainerFailure(result));
  }
  // 事项级字段(title/goal/acceptance/budget)的【唯一】写入口。会话头里的 head.mission 不受影响。
  if ((req.method === 'PATCH' || (req.method === 'POST' && req.headers['x-http-method'] === 'PATCH')) && pathname.match(/^\/api\/missions\/([^/]+)$/)) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const missionId = safeSessionId(pathname.split('/')[3]);
    if (!missionId) return send(res, missionContainerFailure({ error: 'invalid_request', message: 'invalid missionId' }));
    const body = await readJsonBody(req);
    const result = await patchMissionContainer(missionId, body || {});
    return send(res, result.ok ? json(result) : missionContainerFailure(result));
  }
  // 线程加入 / 移出。attach 把会话头 missionId 改为目标事项(经 updateSessionMeta,享受 116-2a 的
  // 活回合竞态防护)并写反向索引;detach 恢复 missionId === sessionId(未归类)。
  if (req.method === 'POST' && pathname.match(/^\/api\/missions\/([^/]+)\/threads$/)) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const missionId = safeSessionId(pathname.split('/')[3]);
    if (!missionId) return send(res, missionContainerFailure({ error: 'invalid_request', message: 'invalid missionId' }));
    const body = await readJsonBody(req);
    const action = String((body && body.action) || '');
    if (action !== 'attach' && action !== 'detach') {
      return send(res, missionContainerFailure({ error: 'invalid_request', message: "action must be 'attach' or 'detach'" }));
    }
    const result = action === 'attach'
      ? await missionAttachThread(missionId, body && body.sessionId)
      : await missionDetachThread(missionId, body && body.sessionId);
    return send(res, result.ok ? json(result) : missionContainerFailure(result));
  }
  // 合并:from 的全部线程搬到目标、验收项按文本去重并入、from 标 archivedAt。再合一次零变化。
  if (req.method === 'POST' && pathname.match(/^\/api\/missions\/([^/]+)\/merge$/)) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const missionId = safeSessionId(pathname.split('/')[3]);
    if (!missionId) return send(res, missionContainerFailure({ error: 'invalid_request', message: 'invalid missionId' }));
    const body = await readJsonBody(req);
    const result = await missionMergeInto(missionId, body && body.from);
    return send(res, result.ok ? json(result) : missionContainerFailure(result));
  }
  // 拆分:把指定线程拆到一个新事项。幂等键 = 同一组 sessionIds 已完整落在同名未归档事项里。
  if (req.method === 'POST' && pathname.match(/^\/api\/missions\/([^/]+)\/split$/)) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const missionId = safeSessionId(pathname.split('/')[3]);
    if (!missionId) return send(res, missionContainerFailure({ error: 'invalid_request', message: 'invalid missionId' }));
    const body = await readJsonBody(req);
    const result = await missionSplitThreads(missionId, body && body.sessionIds, body && body.title);
    return send(res, result.ok ? json(result) : missionContainerFailure(result));
  }
  // 第79波:确定性回来摘要数据面。只返回严格位于 (after,currentRevision] 的原始变更记录；
  // migration prefix、损坏行、内部/尾部缺号都以 degraded+gap 明示，客户端不得推进 lastSeen。
  if (req.method === 'GET' && /^\/api\/missions\/[^/]+\/changes$/.test(pathname)) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const sessionId = safeSessionId(pathname.split('/')[3]);
    if (!sessionId) return send(res, apiSessionIdInvalid());
    const query = new URL(req.url, 'http://x').searchParams;
    const after = Number(query.get('after'));
    if (!Number.isSafeInteger(after) || after < 0) return send(res, json({ ok: false, error: 'after must be a non-negative integer' }, 400));
    const session = await loadSession(sessionId);
    if (!session) return send(res, apiSessionNotFound());
    // 117m-A3(用户第六轮走查④「交办台点开,显示报错」):线程 kind:'mission' 而 mission:null 是【合法状态】
    // —— 管家刚开的线程还没有任何变更账本。修前这里 404 'mission not found',而交办台详情是一个
    // Promise.all(详情 + 两次 changes),一挂就把整块面板换成错误卡(用户截图里那张)。把「还没有变更」
    // 说成「找不到事项」是判据错位:找不到的是账本,不是事项,而空账本本来就该回一份空清单。
    // 只放宽这一种情形(会话在、账本空);会话不存在仍旧 404。
    if (!session.mission) {
      return send(res, json({
        ok: true, missionId: sessionMissionId(session), sessionId,
        fromRevision: after, currentRevision: 0, baseRevision: 0,
        changes: [], degraded: false, gap: null,
        integrity: { corruptLines: 0, lastRevision: 0 },
      }));
    }
    const currentRevision = Math.max(0, Number(session.mission.changeSeq) || 0);
    const folded = await readMissionChangesWithMeta(sessionId, currentRevision);
    let gap = folded.gap;
    if (!gap && after < folded.baseRevision) gap = { expected: after + 1, actual: folded.baseRevision + 1, prefix: true };
    if (!gap && after > currentRevision) gap = { expected: currentRevision, actual: after, ahead: true };
    const degraded = folded.degraded || Boolean(gap);
    return send(res, json({
      ok: true,
      missionId: sessionMissionId(session),
      sessionId,
      fromRevision: after,
      currentRevision,
      baseRevision: folded.baseRevision,
      changes: folded.records.filter(record => Number(record.seq) > after && Number(record.seq) <= currentRevision),
      degraded,
      gap: gap || null,
      integrity: { corruptLines: folded.corruptLines, lastRevision: folded.lastRevision },
    }));
  }
  // 第84波:Mission 控制面。动作作用域由 missionControlCommand 单一核心冻结；本路由只做
  // missionId/sessionId 解析与 HTTP 适配，经典 /api/mission stop 也复用同一核心。
  if (req.method === 'POST' && /^\/api\/missions\/[^/]+\/control$/.test(pathname)) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const sessionId = safeSessionId(pathname.split('/')[3]);
    if (!sessionId) return send(res, apiSessionIdInvalid());
    const body = await readJsonBody(req);
    const result = await missionControlCommand(sessionId, body && body.action, body && body.prompt);
    return send(res, json(result.body, result.status));
  }
  // 详情:单会话稳定任务快照(EC-E:mission + Agent Run + 产物 + 变更 + 检查点 + 用量 + 游标)。
  // 只认 /api/missions/<一段>(与 13d 单条会话路由同一个口径):修前是 startsWith + path.basename,
  // /api/missions/随便/什么/<id> 与 /api/missions/<id>/ 都被当成 <id>,以后加 GET 子路由会被这里先吞掉。
  const missionDetail = req.method === 'GET' ? pathname.match(/^\/api\/missions\/([^/]+)$/) : null;
  if (missionDetail) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const sessionId = safeSessionId(safeDecodeURIComponent(missionDetail[1]) || '');
    if (!sessionId) return send(res, apiSessionIdInvalid());
    const index = await getPretenderProjectionIndex();
    const indexed = index.sessions.find(row => row.sessionId === sessionId) || null;
    // 124-P1:详情自此带着【事项容器】那一套验收项(「人工复核」那一档),容器是另一份文件,
    // 它变了不会动会话投影的 revision —— 指纹不带上它,勾完验收项的下一拍就是 304 + 陈旧验收。
    // 容器是小 JSON,304 这条路上多读它一次,换的是不说谎(指纹判据单点住在 02)。
    // 未归类线程(missionId === sessionId)天然没有事项文件 —— 事项 id 一律 `mission_<hex>`(02 的
    // safeMissionId 头注),与 `sess_` 分家,所以那一档连读都不用读(抽屉是轮询的,省的是每一拍一次
    // ENOENT)。归类过的才去读那份小 JSON。
    const containerId = (indexed && indexed.missionId && indexed.missionId !== sessionId) ? indexed.missionId : '';
    const container = containerId ? await readMissionContainer(containerId).catch(() => null) : null;
    const etag = indexed ? pretenderEtag('mission', indexed.revision + '-' + pretenderLiveOverlayRevision(sessionId) + '-' + missionContainerAcceptanceStamp(container)) : '';
    if (etag && pretenderNotModified(req, etag)) return send(res, { status: 304, headers: { etag }, body: '' });
    const session = await loadSession(sessionId);
    if (!session) return send(res, apiSessionNotFound());
    const runs = await listAgentRuns(sessionId).catch(() => []);

    // 验收投影(124-P1):里程碑计数与 items 形状一个字不动,另带「这条是谁判的」四态、机器检查的
    // 实情(没跑过 / 最近一次没通过 —— J08)、事项容器那一套(人工复核)与「有没有账本」。判据单点
    // 住在 02 的 buildMissionAcceptanceProjection,本路由只负责把两份数据喂进去。
    // indexed 缺失(会话还没进投影索引)时上面那次容器读不到,这里按会话头里的 missionId 补一次。
    const headMissionId = sessionMissionId(session);
    const acceptanceContainer = container
      || (headMissionId && headMissionId !== sessionId ? await readMissionContainer(headMissionId).catch(() => null) : null);
    const acceptance = buildMissionAcceptanceProjection(session.mission, acceptanceContainer);

    // 变更/产物聚合:跨回合 turnSummary 折叠(02 foldTurnSummaries 单一实现,与 buildMissionResult 共用) ——
    // filesChanged 按 path 后写胜(最新 op/revertible 为当前态),artifacts 按 path 先去重(首次产出记回合)。
    // revertible=false 即不可逆显式标注(journal skipped 或天生不在账内)。
    // 第72波顺手修:旧内联折叠 `commands += (ts.commands || []).length` 把数字当数组,commands>0 即 NaN
    // (JSON 序列化为 null)——统一走 fold 后该 bug 消失;irreversible 正向账随行,旧回合(无该字段)的
    // commands 诚实单列 legacyCommands,不混进新账假装有据。
    const fold = foldTurnSummaries(session);
    const filesChangedList = fold.filesChanged, artifactsList = fold.artifacts, commands = fold.commands;

    // 检查点引用(真实回滚能力的入口:POST /api/checkpoints/rollback {sessionId, turnSeq, entrySeq?})。
    const cpEntries = await journalReadIndex(sessionId).catch(() => []);
    const cpTurnSeqs = [...new Set(cpEntries.map(e => e && e.turnSeq).filter(Number.isFinite))].sort((a, b) => a - b);
    const checkpoints = {
      entries: cpEntries.length,
      turnSeqs: cpTurnSeqs,
      totalBytes: cpEntries.reduce((s, e) => s + (Number(e && e.bytes) || 0), 0),
      rollbackAvailable: cpEntries.length > 0,
    };
    // 第84波台账时间轴:直接投影 checkpoint journal，不从摘要猜「可回退」。被跳过的大文件与不在
    // journal 中的变更诚实列入不可回退区；最多下发最近 200 条，长任务的详情响应保持有界。
    const checkpointKeys = new Set(cpEntries.map(entry => `${Number(entry && entry.turnSeq)}:${Number(entry && entry.entrySeq)}:${String(entry && entry.path || '')}`));
    // skipped:true 已在 checkpoint row 自身标成不可回退；这里只补「摘要里有、journal 里没有」的变更，
    // 避免同一大文件既算 skipped row 又算 nonRevertibleFile 而把不可退计数翻倍。
    const nonRevertibleFiles = filesChangedList.filter(file => file
      && !checkpointKeys.has(`${Number(file.turnSeq)}:${Number(file.entrySeq)}:${String(file.path || '')}`));
    const ledgerEntries = cpEntries.slice(-200).map(entry => ({
      turnSeq: Number(entry && entry.turnSeq) || 0,
      entrySeq: Number(entry && entry.entrySeq) || 0,
      path: String(entry && entry.path || ''),
      op: String(entry && entry.op || ''),
      tool: String(entry && entry.tool || ''),
      bytes: Math.max(0, Number(entry && entry.bytes) || 0),
      ts: String(entry && entry.ts || ''),
      revertible: !(entry && entry.skipped),
      reason: entry && entry.skipped ? 'content_too_large' : '',
    }));
    const reversibleEntries = ledgerEntries.filter(entry => entry.revertible).length;
    const recoveryBlockers = ledgerEntries.filter(entry => !entry.revertible).length + nonRevertibleFiles.length
      + fold.irreversible.total + fold.irreversible.legacyCommands;
    const controls = missionControlView(session, { checkpointEntries: cpEntries, runs });
    const ledger = {
      entries: ledgerEntries,
      truncated: cpEntries.length > ledgerEntries.length,
      totalEntries: cpEntries.length,
      nonRevertibleFiles: nonRevertibleFiles.slice(-80),
      irreversible: { items: fold.irreversible.items.slice(-80), legacyCommands: fold.irreversible.legacyCommands, ...(fold.irreversible.incomplete ? { incomplete: true } : {}) },
      rollbackTargetTurnSeq: controls.rollbackTargetTurnSeq,
      recoverability: reversibleEntries === 0 ? 'none' : (recoveryBlockers > 0 ? 'partial' : 'full'),
      reversibleEntries,
      nonRevertibleEntries: recoveryBlockers,
    };

    // 用量切片:append-only 月度账本按 sessionId 过滤(权威存储,session 对象上无聚合字段)。
    const usage = indexed && indexed.usage ? indexed.usage : emptyMissionUsage();

    // 游标:增量消费的位置令牌 —— 会话 turnSeq(单调不回绕)+ 各 run 事件流 eventSeq(严格单调,afterSeq 补播)。
    const cursor = {
      turnSeq: Number(session.turnSeq) || 0,
      runs: Object.fromEntries(runs.map(r => [r.id, Number(r && r.eventSeq) || 0])),
      projectionRevision: indexed ? indexed.revision : '',
      snapshotAt: nowIso(),
    };
    const pendingCounts = await missionPendingCounts(sessionId, runs, indexed && indexed.interventions);

    return send(res, json({
      ok: true,
      snapshot: {
        sessionId, missionId: sessionMissionId(session), kind: sessionKind(session), title: session.title || '', summary: session.summary || '',
        cwd: session.cwd || '', createdAt: session.createdAt || '', updatedAt: session.updatedAt || '',
        status: missionCardStatus(session.mission),
        activeTurn: activeChildren.has(sessionId), // 第56波:活回合标志(五态派生的「进行中」权威信号之一,与 run.live 同型内存叠加)
        queued: stewardThreadTurnQueued(sessionId), // hunt3:回合在仲裁器里排队(前端 fromSnapshot 读它,同 activeTurn 一档)
        mission: session.mission || null,
        acceptance,
        // 班组图只需最近 6 轮；更旧历史仍保留标量 digest，可在经典工作台查看完整节点。
        runs: runs.map((run, index) => missionRunDigest(run, true, index < 6)),
        changes: { filesChanged: filesChangedList, artifacts: artifactsList, commands },
        // 第72波:不可逆操作正向账(活任务也随快照下发;终态任务以 mission.result 盖章版为准)
        irreversible: { total: fold.irreversible.total, byKind: fold.irreversible.byKind, items: fold.irreversible.items.slice(-30), legacyCommands: fold.irreversible.legacyCommands, ...(fold.irreversible.incomplete ? { incomplete: true } : {}) },
        // 第72波:任务结果快照(终态盖章;active/paused 为 null,看 acceptance/changes/irreversible 实时投影)
        result: (session.mission && session.mission.result) || null,
        // 历史轮次验收报告(next_turn/retry/rollback/再武装前归档的旧 result,有界 last 10)
        resultHistory: Array.isArray(session.mission && session.mission.resultHistory) ? session.mission.resultHistory : [],
        checkpoints,
        controls,
        ledger,
        usage,
        pending: pendingCounts,
        cursor,
        projectionRevision: indexed ? indexed.revision : '',
        freshness: {
          persistentRevision: indexed ? indexed.revision : '',
          indexedAt: indexed ? indexed.indexedAt : '',
          liveOverlay: activeChildren.has(sessionId) || runs.some(r => activeAgentRuns.has(r.id)),
          overlayAt: nowIso(),
        },
      },
      index: pretenderIndexMeta(index),
    }, 200, etag ? { etag } : {}));
  }
  return false;
}

// ============================================================================
// 第75b波(Pretender P1):Intervention 单一 command core。
// 新契约与经典四端点都只做参数/响应适配;权威 CAS、可送达检查、实际动作、审计与幂等响应持久化均在这里。
// ============================================================================
function canonicalDecisionValue(value, depth = 0) {
  if (depth > 24 || value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(v => canonicalDecisionValue(v, depth + 1));
  const out = {};
  for (const key of Object.keys(value).sort()) out[key] = canonicalDecisionValue(value[key], depth + 1);
  return out;
}

function interventionDecisionFingerprint(missionId, interventionId, payload) {
  return crypto.createHash('sha256')
    .update(JSON.stringify(canonicalDecisionValue({ missionId, interventionId, payload })), 'utf8')
    .digest('hex');
}

function interventionCommandFailure(reason, status, params = {}, message = '') {
  return {
    status,
    body: {
      ok: false,
      reason,
      error: {
        code: `intervention.${reason}`,
        params: params && typeof params === 'object' && !Array.isArray(params) ? params : {},
        ...(message ? { message } : {}),
      },
    },
  };
}

function normalizeContractQuestionDecision(payload, questions) {
  const rows = payload && payload.answer && Array.isArray(payload.answer.answers)
    ? payload.answer.answers
    : null;
  const known = Array.isArray(questions) ? questions : [];
  if (!rows || rows.length !== known.length || rows.length < 1 || rows.length > 3) {
    return { ok: false, message: 'answer.answers must contain exactly one answer for each question' };
  }
  const byId = new Map(known.map(q => [String(q && q.id || ''), q]));
  const seen = new Set();
  for (const row of rows) {
    if (!row || typeof row !== 'object') return { ok: false, message: 'each answer must be an object' };
    if (Object.keys(row).some(key => !['questionId', 'selectedOptionIds', 'otherText'].includes(key))) {
      return { ok: false, message: 'answer contains fields outside the typed question contract' };
    }
    const questionId = String(row.questionId || '');
    const question = byId.get(questionId);
    if (!question || seen.has(questionId)) return { ok: false, message: 'questionId is unknown or duplicated' };
    seen.add(questionId);
    if (!Array.isArray(row.selectedOptionIds)) return { ok: false, message: 'selectedOptionIds must be an array' };
    if (row.selectedOptionIds.some(id => typeof id !== 'string')) return { ok: false, message: 'selectedOptionIds must contain strings' };
    if (row.otherText !== undefined && typeof row.otherText !== 'string') return { ok: false, message: 'otherText must be a string' };
    const selected = row.selectedOptionIds.map(x => String(x || '')).filter(Boolean);
    if (selected.length !== new Set(selected).size || selected.length > 12) return { ok: false, message: 'selectedOptionIds contains duplicates or too many values' };
    const optionIds = new Set((Array.isArray(question.options) ? question.options : []).map(o => String(o && o.id || '')));
    if (selected.some(id => !optionIds.has(id))) return { ok: false, message: 'selectedOptionIds contains an option outside this question' };
    const otherText = String(row.otherText || '').trim();
    const mode = String(question.answerMode || (question.multiSelect ? 'multiple' : 'single'));
    if (mode === 'single' && selected.length > 1) return { ok: false, message: 'single-choice question accepts at most one option' };
    if (mode === 'text' && selected.length) return { ok: false, message: 'text question does not accept selectedOptionIds' };
    if (otherText && mode !== 'text' && question.allowOther !== true) return { ok: false, message: 'otherText is not allowed for this question' };
    if (!selected.length && !otherText) return { ok: false, message: 'each question requires an answer' };
  }
  return { ok: true, answer: normalizeQuestionAnswer({ answers: rows }, known) };
}

function mapInterventionTransitionFailure(result) {
  const reason = String(result && result.reason || 'decision_failed');
  if (reason === 'not_found') return interventionCommandFailure(reason, 404, {}, 'mission or intervention not found');
  if (reason === 'expired') return interventionCommandFailure(reason, 410, { status: result.status || '' }, 'intervention has expired');
  if (reason === 'version_conflict') {
    return interventionCommandFailure(reason, 409, {
      expectedVersion: result.expectedVersion,
      actualVersion: result.actualVersion,
    }, 'intervention version does not match');
  }
  if (reason === 'idempotency_conflict') {
    return interventionCommandFailure(reason, 409, {}, 'idempotencyKey was already used for a different request');
  }
  if (reason === 'already_terminal') {
    return interventionCommandFailure(reason, 409, {
      status: result.status || '',
      interventionVersion: Number(result.interventionVersion) || 0,
    }, 'intervention is already terminal');
  }
  if (reason === 'not_pending') {
    return interventionCommandFailure(reason, 409, { status: result.status || '' }, 'intervention is already being applied');
  }
  if (reason === 'persist_failed') return interventionCommandFailure(reason, 503, {}, 'could not record the decision on disk; nothing was applied, try again');
  if (reason === 'terminal_persist_failed') return interventionCommandFailure(reason, 503, {
    status: result.status || 'applying', interventionVersion: Number(result.interventionVersion) || 0, outcomeUnknown: true,
  }, 'the action ran, but its final state could not be recorded; inspect the execution result before taking further action');
  return interventionCommandFailure(reason, 409, {
    ...(result && result.runId ? { runId: result.runId } : {}),
  }, String(result && result.message || 'intervention cannot be delivered'));
}

async function decideIntervention(command = {}) {
  const rawMissionId = String(command.missionId || '');
  const missionId = safeSessionId(rawMissionId);
  const interventionId = String(command.interventionId || '');
  const source = String(command.source || 'contract').slice(0, 64);
  const contractRequest = command.contractRequest !== false;
  const payload = command.payload && typeof command.payload === 'object' && !Array.isArray(command.payload)
    ? command.payload
    : {};
  if (!missionId || missionId !== rawMissionId || !/^[A-Za-z0-9_-]{1,160}$/.test(interventionId)) {
    return interventionCommandFailure('invalid_request', 400, {}, 'invalid missionId or interventionId');
  }
  // 117j 收尾：这一发读【必须】走带瞬时重试的那一个。它是用户动作的判定入口 —— 读空一次就等于
  // 把「允许／回答」当场判成 404「会话不存在」，而真相只是回合正好在写头（见 02 的头注）。
  const head = await readSessionHeadResilient(missionId);
  // 117e 第 0 步(116g 引入的真 bug):这道门在 116g 之前是恒等式 —— 会话没挂进显式事项容器时
  // sessionMissionId(head) 就回落成 head.id,而 head 正是按 `sessionPath(missionId)` 读出来的。
  // 116g 的 missionAttachThread 把 session.missionId 改写成【容器 id】之后,同一条会话再按自己的
  // id 来答待决就恒判 not_found —— /api/chat/answer、/api/permission/decision、/api/plan/decision
  // 三条兼容适配器与 steward_decide 传的都是 sessionId,于是「凡是进了多线程事项的线程,问题/权限/
  // 计划都答不进去」(经典壳同样受影响)。
  // 修法:把「missionId 等于该会话自身 id」显式认作合法别名(容器 id 仍照旧受理,只是那个 id 上
  // 没有会话文件,读不出 head 就仍然 404)。**不放宽**「跨会话答别人的待决」:待决本体在下面按
  // `readInterventions(missionId)` 从这条会话自己的旁路账里取,并再核一次 `current.sessionId ===
  // missionId`;拿会话 A 的 id 去答会话 B 的待决,那两道判定照旧拦下。
  const headSelfId = String((head && head.id) || '');
  if (!head || (sessionMissionId(head) !== missionId && headSelfId !== missionId)) {
    return interventionCommandFailure('not_found', 404, {}, 'mission or intervention not found');
  }

  if (contractRequest) {
    if (!Number.isInteger(command.expectedVersion) || command.expectedVersion < 0) {
      return interventionCommandFailure('invalid_request', 400, { field: 'expectedVersion' }, 'expectedVersion must be a non-negative integer');
    }
    const key = String(command.idempotencyKey || '');
    if (!key || key.length > 128) {
      return interventionCommandFailure('invalid_request', 400, { field: 'idempotencyKey' }, 'idempotencyKey must contain 1-128 characters');
    }
  }

  const current = (await readInterventions(missionId).catch(() => []))
    .find(iv => iv && String(iv.id) === interventionId);
  if (!current || String(current.sessionId || missionId) !== missionId) {
    return interventionCommandFailure('not_found', 404, {}, 'mission or intervention not found');
  }

  const type = String(current.type || '');
  const action = String(payload.action || '');
  if (contractRequest) {
    const commonFields = new Set(['expectedVersion', 'idempotencyKey', 'action']);
    const typeFields = type === 'permission' ? ['updatedInput', 'scope']
      : type === 'question' ? ['answer']
        : type === 'plan' ? ['feedback']
          : [];
    const allowed = new Set([...commonFields, ...typeFields]);
    const unknown = Object.keys(payload).filter(key => !allowed.has(key));
    if (unknown.length) return interventionCommandFailure('payload_invalid', 400, { fields: unknown }, 'request contains fields outside the type/action contract');
  }
  let toStatus = '';
  let normalizedAnswer = null;
  if (type === 'permission') {
    if (action !== 'allow' && action !== 'deny') return interventionCommandFailure('action_invalid', 400, { type }, 'permission action must be allow or deny');
    if (action === 'allow' && payload.updatedInput !== undefined && (!payload.updatedInput || typeof payload.updatedInput !== 'object' || Array.isArray(payload.updatedInput))) {
      return interventionCommandFailure('payload_invalid', 400, { field: 'updatedInput' }, 'updatedInput must be an object');
    }
    if (payload.scope !== undefined && payload.scope !== 'session') {
      return interventionCommandFailure('payload_invalid', 400, { field: 'scope' }, 'scope must be session when provided');
    }
    toStatus = action === 'allow' ? 'allowed' : 'denied';
  } else if (type === 'question') {
    if (action !== 'answer') return interventionCommandFailure('action_invalid', 400, { type }, 'question action must be answer');
    if (contractRequest) {
      const normalized = normalizeContractQuestionDecision(payload, current.questions);
      if (!normalized.ok) return interventionCommandFailure('payload_invalid', 400, { type }, normalized.message);
      normalizedAnswer = normalized.answer;
    } else {
      normalizedAnswer = payload.normalizedAnswer;
      if (!normalizedAnswer || typeof normalizedAnswer !== 'object') return interventionCommandFailure('payload_invalid', 400, { type }, 'question answer is required');
    }
    toStatus = normalizedAnswer.ok === false ? 'cancelled' : 'answered';
  } else if (type === 'plan') {
    if (action !== 'approve' && action !== 'reject') return interventionCommandFailure('action_invalid', 400, { type }, 'plan action must be approve or reject');
    if (contractRequest && payload.feedback !== undefined && typeof payload.feedback !== 'string') {
      return interventionCommandFailure('payload_invalid', 400, { field: 'feedback' }, 'feedback must be a string');
    }
    toStatus = action === 'approve' ? 'approved' : 'rejected';
  } else if (type === 'pool') {
    if (action !== 'approve' && action !== 'reject') return interventionCommandFailure('action_invalid', 400, { type }, 'pool action must be approve or reject');
    toStatus = action === 'approve' ? 'approved' : 'rejected';
  } else if (type === 'replan') {
    if (action !== 'approve' && action !== 'reject') return interventionCommandFailure('action_invalid', 400, { type }, 'replan action must be approve or reject');
    toStatus = action === 'approve' ? 'approved' : 'rejected';
  } else {
    return interventionCommandFailure('type_unsupported', 409, { type }, 'intervention type is not supported by this release');
  }

  const idempotencyKey = String(command.idempotencyKey || makeId('legacy')).slice(0, 128);
  const decisionPayload = type === 'question'
    ? { action, answer: normalizedAnswer }
    : type === 'permission'
      ? { action, ...(action === 'allow' && payload.updatedInput !== undefined ? { updatedInput: payload.updatedInput } : {}), ...(action === 'allow' && payload.scope === 'session' ? { scope: 'session' } : {}) }
      : type === 'plan'
        ? { action, ...(payload.feedback !== undefined ? { feedback: String(payload.feedback) } : {}) }
        : { action };
  const decisionFingerprint = interventionDecisionFingerprint(missionId, interventionId, decisionPayload);
  let runtimeEntry = null;
  let poolContext = null;
  let replanContext = null;

  const preflight = async authoritative => {
    if (!authoritative || String(authoritative.type || '') !== type) return { ok: false, reason: 'not_found' };
    if (type === 'permission') {
      runtimeEntry = pendingPermissions.get(interventionId);
      if (!runtimeEntry || runtimeEntry.sessionId !== missionId) return { ok: false, reason: 'delivery_unavailable', message: 'permission consumer is not live' };
      return { ok: true };
    }
    if (type === 'question') {
      runtimeEntry = pendingQuestions.get(interventionId);
      if (!runtimeEntry || runtimeEntry.sessionId !== missionId) return { ok: false, reason: 'delivery_unavailable', message: 'question consumer is not live' };
      return { ok: true };
    }
    if (type === 'plan') {
      runtimeEntry = pendingPlans.get(interventionId);
      if (!runtimeEntry || runtimeEntry.sessionId !== missionId) return { ok: false, reason: 'delivery_unavailable', message: 'plan consumer is not live' };
      return { ok: true };
    }
    if (type === 'replan') {
      const runId = String(authoritative.runId || '');
      if (command.requestRunId && String(command.requestRunId) !== runId) return { ok: false, reason: 'not_found' };
      // R5: patch 审批不要求 run live —— 节点终态后 run 通常已收尾离开 activeAgentRuns。
      // 优先用 live 内存态(最新),否则读 persisted run JSON(已收尾仍可审批)。
      const live = activeAgentRuns.get(runId);
      let runObj = null;
      if (live && live.run && !live.closing) {
        if (live.run.sessionId !== missionId) return { ok: false, reason: 'not_found' };
        runObj = live.run;
      } else {
        try { runObj = safeJsonParse(await fsp.readFile(agentRunFile(missionId, runId), 'utf8'), null); } catch {}
        if (!runObj || runObj.sessionId !== missionId) return { ok: false, reason: 'run_not_found', runId, message: 'run is not found' };
      }
      const patch = (Array.isArray(runObj.replanPatches) ? runObj.replanPatches : []).find(p => p && String(p.id) === interventionId);
      if (!patch || patch.status !== 'pending') return { ok: false, reason: 'replan_patch_unavailable', runId, message: 'replan patch is no longer pending' };
      replanContext = { runId, runObj, patch };
      return { ok: true };
    }

    const runId = String(authoritative.runId || '');
    if (command.requestRunId && String(command.requestRunId) !== runId) return { ok: false, reason: 'not_found' };
    const live = activeAgentRuns.get(runId);
    if (!live || !live.run || live.closing) {
      let persisted = null;
      try { persisted = safeJsonParse(await fsp.readFile(agentRunFile(missionId, runId), 'utf8'), null); } catch {}
      const reason = persisted && persisted.status === 'paused' ? 'run_paused' : 'run_not_live';
      return { ok: false, reason, runId, message: reason === 'run_paused' ? 'run is paused; resume it before deciding' : 'run is not live' };
    }
    if (live.run.sessionId !== missionId) return { ok: false, reason: 'not_found' };
    if (live.stopRequested || (live.ctrl && live.ctrl.signal && live.ctrl.signal.aborted)) {
      return { ok: false, reason: 'run_stopping', runId, message: 'run is stopping' };
    }
    const item = (Array.isArray(live.run.taskPool) ? live.run.taskPool : []).find(p => p && String(p.id) === interventionId);
    if (!item || item.status !== 'proposed') return { ok: false, reason: 'pool_item_unavailable', runId, message: 'pool item is no longer proposed' };
    let config = null, cwd = '', roleLibrary = new Map();
    if (action === 'approve') {
      try {
        config = await readConfig();
        const session = await loadSession(missionId);
        cwd = normalizeCwd(session && session.cwd, config.defaultWorkspace);
        roleLibrary = new Map((await getAgentRoleLibrary(cwd, config)).map(role => [role.id, role]));
      } catch { /* preserve the existing empty-role-library fallback */ }
      const dryRun = { ...live.run, nodes: Array.isArray(live.run.nodes) ? [...live.run.nodes] : [] };
      const dry = materializePoolItem(dryRun, { ...item }, { roleLibrary, cwd, config, dryRun: true });
      if (!dry.ok) return { ok: false, reason: dry.reason || 'pool_materialize_rejected', runId, message: dry.error || 'pool item cannot be materialized' };
    }
    poolContext = { runId, live, item, config, cwd, roleLibrary };
    return { ok: true };
  };

  const execute = () => {
    if (type === 'permission') {
      runtimeEntry.commandApplying = true;
      clearTimeout(runtimeEntry.timer);
      const decision = action === 'allow'
        ? { behavior: 'allow', updatedInput: payload.updatedInput, ...(payload.scope === 'session' ? { scope: 'session' } : {}) }
        : { behavior: 'deny', message: String(payload.message || 'denied by user') };
      runtimeEntry.resolve(decision, { skipInterventionSettle: true });
      return { ok: true, delivered: true };
    }
    if (type === 'question') {
      runtimeEntry.commandApplying = true;
      clearTimeout(runtimeEntry.timer);
      const delivered = runtimeEntry.deliver(normalizedAnswer, { skipInterventionSettle: true, preserveRegistry: true });
      return { ok: delivered !== false, delivered: delivered !== false, reason: delivered === false ? 'delivery_failed' : '' };
    }
    if (type === 'plan') {
      runtimeEntry.commandApplying = true;
      clearTimeout(runtimeEntry.timer);
      runtimeEntry.resolve({
        decision: action,
        note: payload.feedback != null ? String(payload.feedback).slice(0, 2000) : '',
      }, { skipInterventionSettle: true });
      return { ok: true, delivered: true };
    }
    if (type === 'replan') {
      return (async () => {
        const { runObj, patch } = replanContext;
        if (patch.status !== 'pending') return { ok: false, reason: 'run_state_changed' };
        if (action === 'reject') {
          patch.status = 'rejected'; patch.decidedAt = nowIso();
          bumpRunIntervention(runObj, 'replan_reject');
          appendAgentRunEvent(runObj, { type: 'run_replan', data: { action: 'rejected', patchId: interventionId, by: String(command.decidedBy || 'user') } });
          await saveAgentRun(runObj);
          return { ok: true, patchId: interventionId };
        }
        if (!Array.isArray(patch.changes) || patch.changes.length === 0) return { ok: false, reason: 'replan_changes_pending', message: '重规划提案尚未补充 changes，暂不能应用；请先由 review 角色填充变更项，或拒绝该提案' };
        const ap = applyReplanPatch(runObj, interventionId);
        if (!ap.ok) return { ok: false, reason: 'replan_apply_failed', message: ap.error || '' };
        patch.decidedAt = nowIso();
        bumpRunIntervention(runObj, 'replan_approve');
        appendAgentRunEvent(runObj, { type: 'run_replan', data: { action: 'applied', patchId: interventionId, by: String(command.decidedBy || 'user'), applied: ap.applied } });
        await saveAgentRun(runObj);
        return { ok: true, patchId: interventionId, applied: ap.applied };
      })();
    }
    return (async () => {
      const { runId, live, item, config, cwd, roleLibrary } = poolContext;
      if (activeAgentRuns.get(runId) !== live || live.closing || live.stopRequested || (live.ctrl && live.ctrl.signal && live.ctrl.signal.aborted) || item.status !== 'proposed') {
        return { ok: false, reason: 'run_state_changed' };
      }
      if (action === 'reject') {
        item.status = 'rejected'; item.decidedBy = String(command.decidedBy || 'user'); item.decidedAt = nowIso();
        bumpRunIntervention(live.run, 'pool_reject');
        appendAgentRunEvent(live.run, { type: 'run_pool', data: { action: 'rejected', poolId: interventionId, by: String(command.decidedBy || 'user') } });
        await saveAgentRun(live.run);
        return { ok: true, poolId: interventionId };
      }
      const mat = materializePoolItem(live.run, item, { roleLibrary, cwd, config });
      if (!mat.ok) return { ok: false, reason: mat.reason || 'pool_materialize_failed', message: mat.error || '' };
      item.status = 'materialized'; item.decidedBy = String(command.decidedBy || 'user'); item.decidedAt = nowIso(); item.resultNodeId = mat.node.id;
      bumpRunIntervention(live.run, 'pool_approve');
      appendAgentRunEvent(live.run, { type: 'run_pool', data: { action: 'materialized', poolId: interventionId, by: String(command.decidedBy || 'user'), nodeId: mat.node.id } });
      try { live.poolGraceArmed = true; } catch {}
      if (live.inPoolGrace && Array.isArray(live.resumeWaiters)) {
        const waiters = live.resumeWaiters.splice(0);
        for (const wake of waiters) wake();
      }
      await saveAgentRun(live.run);
      return { ok: true, poolId: interventionId, nodeId: mat.node.id };
    })();
  };

  let transition;
  try {
    transition = await transitionInterventionState(
      missionId,
      interventionId,
      contractRequest ? command.expectedVersion : undefined,
      toStatus,
      {
        source,
        decidedBy: String(command.decidedBy || 'user'),
        idempotencyKey,
        decisionFingerprint,
        preflight,
        action: execute,
        resolveStatus: result => result && result.ok === false ? 'indeterminate' : toStatus,
        extra: result => ({
          action,
          ...(type === 'question' ? { answer: normalizedAnswer } : {}),
          ...(type === 'plan' && payload.feedback != null ? { feedback: String(payload.feedback).slice(0, 2000) } : {}),
          ...(result && result.nodeId ? { nodeId: result.nodeId } : {}),
        }),
        buildResponse: (result, meta) => result && result.ok === false
          ? interventionCommandFailure(result.reason || 'delivery_failed', 409, { type }, result.message || 'decision could not be delivered').body
          : {
              ok: true,
              missionId,
              interventionId,
              type,
              action,
              status: meta.status,
              interventionVersion: meta.interventionVersion,
              ...(result && result.delivered !== undefined ? { delivered: result.delivered } : {}),
              ...(result && result.nodeId ? { nodeId: result.nodeId } : {}),
            },
        audit: command.audit === false ? undefined : (_result, terminal) => {
          const auditSource = source === 'legacy_question' ? 'question_answer'
            : source === 'legacy_permission' ? 'permission_decision'
              : source === 'legacy_plan' ? 'plan_decision'
                : source === 'legacy_pool' ? `pool_${action}`
                  // 116c(27 号文 §11.3):管家代答的决定在审计流里必须一眼可辨,不能混进通用标签 ——
                  // 「谁按的这个批准」是事后解释与撤销的第一现场。
                  : source === 'steward' ? 'steward_decision'
                    : 'intervention_decision';
          logEvent({ kind: 'intervention', source: auditSource, sessionId: missionId, interventionId, type, action, interventionVersion: terminal.interventionVersion });
        },
        afterTerminal: () => {
          if (!runtimeEntry) return;
          runtimeEntry.commandApplying = false;
          if (type === 'permission' && pendingPermissions.get(interventionId) === runtimeEntry) pendingPermissions.delete(interventionId);
          else if (type === 'question' && pendingQuestions.get(interventionId) === runtimeEntry) pendingQuestions.delete(interventionId);
          else if (type === 'plan' && pendingPlans.get(interventionId) === runtimeEntry) pendingPlans.delete(interventionId);
        },
      },
    );
  } catch (error) {
    const message = String(error && error.message || error);
    return interventionCommandFailure('execution_failed', 500, {}, message);
  }
  if (!transition || !transition.ok) return mapInterventionTransitionFailure(transition);
  const response = transition.response && typeof transition.response === 'object'
    ? transition.response
    : {
        ok: true,
        missionId,
        interventionId,
        type,
        action,
        status: transition.status,
        interventionVersion: transition.interventionVersion,
      };
  return { status: response.ok === false ? 409 : 200, body: response };
}

// 性能批 P3:GET /api/interventions 的待决引用表,按索引对象缓存(索引任何刷新都换新对象,缓存随之作废)。
// 次序与修前逐条相同:按 requestedAt 的 localeCompare 稳定排序(每个索引版本只排一次)。
const pendingInterventionRefsMemo = new WeakMap();
function pendingInterventionRefs(index, onlySession) {
  let byFilter = pendingInterventionRefsMemo.get(index);
  if (!byFilter) pendingInterventionRefsMemo.set(index, byFilter = new Map());
  const hit = byFilter.get(onlySession);
  if (hit) return hit;
  const refs = [];
  const counts = { permission: 0, question: 0, plan: 0, pool: 0, replan: 0, total: 0 };
  for (const slice of index.sessions) {
    if (onlySession && slice.sessionId !== onlySession) continue;
    for (const iv of slice.interventions || []) {
      if (!iv || iv.status !== 'pending') continue;
      refs.push({ slice, iv, requestedAt: String(iv.requestedAt || '') });
      counts.total++;
      if (iv.type === 'permission') counts.permission++;
      else if (iv.type === 'question') counts.question++;
      else if (iv.type === 'plan') counts.plan++;
      else if (iv.type === 'pool') counts.pool++;
      else if (iv.type === 'replan') counts.replan++;
    }
  }
  refs.sort((a, b) => a.requestedAt.localeCompare(b.requestedAt));
  const entry = { refs, counts };
  byFilter.set(onlySession, entry);
  return entry;
}
// 一条待决的对外形状(字段与次序与修前逐字相同);实时字段每次现算。
function pendingInterventionItem(slice, iv) {
  const sessionId = slice.sessionId;
  return {
    id: iv.id, type: iv.type || '', sessionId, missionId: slice.missionId || sessionId,
    requestedAt: iv.requestedAt || '', interventionVersion: Math.max(0, Number(iv.interventionVersion) || 0),
    toolName: iv.toolName || '', tier: iv.tier || '', revertible: iv.revertible === true,
    runId: iv.runId || '', proposedBy: iv.proposedBy || '', task: iv.task || '',
    input: iv.type === 'permission' && iv.input && typeof iv.input === 'object' && !Array.isArray(iv.input) ? iv.input : undefined,
    questionSummary: iv.type === 'question' ? String(iv.questionSummary || '') : '',
    questions: iv.type === 'question' && Array.isArray(iv.questions) ? iv.questions : [],
    context: iv.type === 'question' ? String(iv.context || '').slice(0, 6000) : '',
    planSummary: iv.type === 'plan' ? String(iv.planSummary || '') : '',
    replanSummary: iv.type === 'replan' ? String(iv.summary || '') : '',
    replanTriggerType: iv.type === 'replan' ? String(iv.triggerType || '') : '',
    replanNodeId: iv.type === 'replan' ? String(iv.nodeId || '') : '',
    deliverable: iv.type === 'permission' ? pendingPermissions.has(String(iv.id))
      : iv.type === 'question' ? pendingQuestions.has(String(iv.id))
        : iv.type === 'plan' ? pendingPlans.has(String(iv.id))
          : iv.type === 'pool' ? activeAgentRuns.has(String(iv.runId || ''))
            : activeChildren.has(sessionId),
    live: activeChildren.has(sessionId), // 决策可送达性提示:活回合在,决策才能立刻被消费
    // 135(工作台「等你处理」队列的倒计时):内存登记簿里的截止时刻(ms)。权限的超时即自动拒绝、
    // 存档暂停会把它延长,提问靠心跳续期 —— 都只有这张登记簿知道真值,前端不自己猜。取不到为 0。
    deadlineAt: Math.max(0, Number((iv.type === 'permission' ? pendingPermissions.get(String(iv.id))
      : iv.type === 'question' ? pendingQuestions.get(String(iv.id)) : null)?.deadlineAt) || 0),
  };
}

async function handleInterventionApiRoutes(req, res, pathname) {
  if (req.method === 'POST' && pathname === '/api/_test/pretender-maintenance') {
    if (process.env.RUYI_TEST_HOOKS !== '1') return send(res, json({ ok: false, error: 'not found' }, 404));
    const body = await readJsonBody(req);
    if (body.action === 'compact') {
      const sessionId = safeSessionId(body.sessionId);
      if (!sessionId) return send(res, apiSessionIdInvalid());
      return send(res, json(await compactInterventionJournal(sessionId, { force: true })));
    }
    if (body.action === 'rebuild') {
      pretenderIndexRuntime.fullDirty = true;
      return send(res, json({ ok: true, index: pretenderIndexMeta(await getPretenderProjectionIndex()) }));
    }
    return send(res, json({ ok: false, error: 'invalid maintenance action' }, 400));
  }
  const contractMatch = pathname.match(/^\/api\/missions\/([^/]+)\/interventions\/([^/]+)\/decision$/);
  if (req.method === 'POST' && contractMatch) {
    let missionId = '', interventionId = '';
    try {
      missionId = decodeURIComponent(contractMatch[1]);
      interventionId = decodeURIComponent(contractMatch[2]);
    } catch {
      return send(res, json(interventionCommandFailure('invalid_request', 400, {}, 'malformed route encoding').body, 400));
    }
    const body = await readJsonBody(req);
    const result = await decideIntervention({
      missionId,
      interventionId,
      expectedVersion: body.expectedVersion,
      idempotencyKey: body.idempotencyKey,
      payload: body,
      source: 'contract',
      contractRequest: true,
    });
    return send(res, json(result.body, result.status));
  }
  // 第56波(Pretender 立项门 / EC-E 363):全局「需要你」最小聚合入口 —— 跨会话 pending Intervention 收件箱。
  // 只读派生:扫 *.interventions.ndjson 折叠取 pending(注册/决策/超时/清理/重启终态化全在旁路账里);
  // pool 型由 71b 注册 + boot 对账覆盖,append 落盘延迟窗为最终一致(与 13d missionPendingCounts 同立场)。
  // 按 requestedAt 升序(FIFO 收件箱:最先等你的在最前)。
  if (req.method === 'GET' && pathname === '/api/interventions') {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const index = await getPretenderProjectionIndex();
    // hunt2-steward ⑨:可选 ?sessionId= 只看一条线程的待决(counts 同口径只数它)。抽屉修前拉全局前 100 条
    // 再在前端按会话筛 —— 全局待决超过 100 条时,排在后面的那条线程的待决永远落在页外,抽屉说它「没在等你」。
    // 不带这个参数的调用逐字节不变。ETag 带上筛选键:同一个修订号下两种视图的响应体不同。
    const onlySessionRaw = new URL(req.url, 'http://127.0.0.1').searchParams.get('sessionId');
    const onlySession = onlySessionRaw ? (safeSessionId(onlySessionRaw) || '~invalid') : '';
    const stewardView = new URL(req.url, 'http://127.0.0.1').searchParams.get('view') === 'steward';
    // 性能批 P3:待决列表按索引版本只收集、排序一次(引用 + 计数缓存在 index 对象上);分页与 ETag 在造条目之前 ——
    // 304 不再付整张表的代价,200 也只为这一页造条目。条目里的实时字段(可送达、活回合、倒计时)照旧每次现算。
    const { refs, counts } = pendingInterventionRefs(index, onlySession);
    const paged = paginatePretenderProjection(req, 'interventions', index.interventionsRevision, refs);
    if (paged.response) return send(res, paged.response);
    const etag = pretenderEtag('interventions', index.interventionsRevision + '-' + pretenderLiveOverlayRevision() + (onlySession ? '-s:' + onlySession : '') + (stewardView ? '-steward' : ''), paged.page);
    if (pretenderNotModified(req, etag)) return send(res, { status: 304, headers: { etag }, body: '' });
    paged.items = paged.items.map(ref => pendingInterventionItem(ref.slice, ref.iv));
    // 135(「等你处理」队列真机走查):弹窗要写清「来自哪条线程」,而前端左栏列表可能还没刷到刚开的线程。
    // 只读【本页】有待决的那几条会话的头(每个 ~1 KB,并行),取不到就留空,前端退回「未命名线程」。
    // 3.0 预览收口:此前在分页与 304 之前串行读【全部】待决会话的头,299 条会话时每请求 300–450 ms
    // (mission-index-scale 收件箱热 P95 闸 250 ms 红);标题从不进 ETag,挪到分页之后响应不变。
    const pageSids = [...new Set(paged.items.map(p => p.sessionId))];
    const heads = await Promise.all(pageSids.map(sid => readSessionHeadResilient(sid).catch(() => null)));
    const titleOf = new Map(pageSids.map((sid, i) => [sid, String((heads[i] && heads[i].title) || '').slice(0, 120)]));
    for (const p of paged.items) p.title = titleOf.get(p.sessionId) || '';
    if (stewardView) {
      const ids = [...new Set(paged.items.map(p => p.missionId).filter(id => !pageSids.includes(id)))];
      const containers = await Promise.all(ids.map(id => readMissionContainer(id).catch(() => null)));
      const titles = new Map(ids.map((id, i) => [id, String(containers[i]?.title || '')]));
      for (const p of paged.items) {
        p.missionTitle = titles.get(p.missionId) || p.title;
        const run = activeAgentRuns.get(p.runId)?.run;
        const detail = p.type === 'permission' ? p.input
          : p.type === 'plan' ? pendingPlans.get(String(p.id))?.markdown
            : p.type === 'pool' ? run?.taskPool?.find(item => item.id === p.id)
              : p.type === 'replan' ? run?.replanPatches?.find(item => item.id === p.id) : null;
        const text = typeof detail === 'string' ? detail : detail ? JSON.stringify(detail, null, 2) : '';
        p.detailsText = text.slice(0, 32000);
        p.detailsComplete = !!detail && text.length <= 32000;
      }
    }
    return send(res, json({
      ok: true,
      pending: paged.items,
      counts,
      page: paged.page,
      nextCursor: paged.page.nextCursor,
      projectionRevision: index.interventionsRevision,
      index: pretenderIndexMeta(index),
    }, 200, { etag }));
  }
  // 第71波:会话的持久化 Intervention 只读派生(注册/决策/超时/清理/重启终态化的旁路记录,02 NDJSON)。
  // 只认 /api/interventions/<一段>(同上:不再用 path.basename 给多段路径当别名)。
  const interventionsOf = req.method === 'GET' ? pathname.match(/^\/api\/interventions\/([^/]+)$/) : null;
  if (interventionsOf) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const sessionId = safeSessionId(safeDecodeURIComponent(interventionsOf[1]) || '');
    if (!sessionId) return send(res, apiSessionIdInvalid());
    const index = await getPretenderProjectionIndex();
    const slice = index.sessions.find(row => row.sessionId === sessionId) || null;
    const interventions = slice ? slice.interventions : [];
    const counts = { permission: 0, question: 0, plan: 0, pool: 0, replan: 0, pending: 0, resolved: 0 };
    for (const iv of interventions) {
      if (!iv) continue;
      if (iv.status === 'pending') {
        counts.pending++;
        if (iv.type === 'permission') counts.permission++;
        else if (iv.type === 'question') counts.question++;
        else if (iv.type === 'plan') counts.plan++;
        else if (iv.type === 'pool') counts.pool++;
        else if (iv.type === 'replan') counts.replan++;
      } else counts.resolved++;
    }
    const revision = slice ? slice.interventionRevision : pretenderHash([]);
    const paged = paginatePretenderProjection(req, 'session-interventions:' + sessionId, revision, interventions);
    if (paged.response) return send(res, paged.response);
    const etag = pretenderEtag('session-interventions', revision, paged.page);
    if (pretenderNotModified(req, etag)) return send(res, { status: 304, headers: { etag }, body: '' });
    return send(res, json({
      ok: true,
      sessionId,
      missionId: slice ? slice.missionId : sessionId,
      interventions: paged.items,
      counts,
      page: paged.page,
      nextCursor: paged.page.nextCursor,
      projectionRevision: revision,
      integrity: slice ? slice.integrity : { degraded: false, corruptLines: 0, journalRows: 0, journalBytes: 0 },
    }, 200, { etag }));
  }
  if (req.method === 'POST' && pathname === '/api/chat/answer') {
    // 75b compatibility adapter: normalize the classic answer[] shape, then hand the actual decision to
    // the same command core used by the Mission contract.
    const body = await readJsonBody(req);
    const sessionId = String(body.sessionId || '');
    const questionId = String(body.questionId || body.toolUseId || '');
    const entry = pendingQuestions.get(questionId);
    if (!entry || entry.sessionId !== sessionId) {
      return send(res, apiFailure('question.not_pending', {}, 'question is no longer pending', 409));
    }
    const result = await decideIntervention({
      missionId: sessionId,
      interventionId: questionId,
      payload: { action: 'answer', normalizedAnswer: normalizeQuestionAnswer(body, entry.questions) },
      source: 'legacy_question',
      contractRequest: false,
    });
    if (result.status !== 200) return send(res, apiFailure('question.delivery_failed', {}, 'answer could not be delivered; the question is still pending', 409));
    return send(res, json({ ok: true, delivered: true, questionId }));
  }
  if (req.method === 'POST' && pathname === '/api/question/heartbeat') {
    // Keep-alive from the open question modal: re-arms the pending question's timeout so a user typing a
    // long answer is never cut off at a fixed deadline. No heartbeat (modal closed / app gone) means the
    // original timeout fires as the backstop. Returns the fresh deadline for the UI countdown.
    const body = await readJsonBody(req);
    const sessionId = String(body.sessionId || '');
    const extension = extendUserQuestion(sessionId, String(body.questionId || ''));
    if (!extension) return send(res, apiFailure('question.not_pending', {}, 'question is no longer pending', 409));
    return send(res, json({ ok: true, deadlineAt: extension.deadlineAt, timeoutMs: extension.timeoutMs }));
  }
  if (req.method === 'POST' && pathname === '/api/question/request') {
    // Called by request_user_input in the per-session Claude MCP child. Hold the tool call until the UI
    // answers, then return a normal MCP tool result. Provider turns use the same registry in-process.
    const body = await readJsonBody(req);
    if (!tokenMatches(body.token)) return send(res, apiFailure('auth.token_invalid', {}, 'bad token', 403));
    const sessionId = safeSessionId(body.sessionId);
    if (!sessionId) return send(res, apiSessionIdInvalid());
    const reg = activeChildren.get(sessionId);
    if (!reg || !reg.onEvent) return send(res, apiFailure('question.no_active_turn', {}, 'no active UI stream to prompt', 409));
    const config = await readConfig();
    const answer = await requestUserQuestion(sessionId, makeId('question'), body.questions, reg.onEvent, config.questionTimeoutMs, reg.questionContext || '');
    return send(res, json(answer && answer.ok
      ? { ok: true, answers: answer.answers, content: answer.content }
      : { ok: false, error: (answer && (answer.error || answer.content)) || 'question cancelled' }));
  }
  if (req.method === 'POST' && pathname === '/api/permission/request') {
    // Called by the permission-bridge MCP tool (loopback). Holds until the UI decides or times out.
    const body = await readJsonBody(req);
    if (!tokenMatches(body.token)) return send(res, json({ ok: false, error: 'bad token' }, 403));
    const config = await readConfig();
    const sessionId = String(body.sessionId || '');
    const reg = activeChildren.get(sessionId);
    const requestId = makeId('perm');
    if (!reg || !reg.onEvent) {
      // No live UI stream to ask — fail closed.
      return send(res, json({ behavior: 'deny', message: 'no active UI to prompt', requestId }));
    }
    // 审计 A② 后续(CLI 直挂面):toolLoadingMode:'full' 时桥接服务器(ACC 等)直接写进 --mcp-config,由 CLI 自己调,
    // 不经工作台的三个分发点 —— 唯一还能插手的地方就是这里:CLI 为 mcp__<server>__<tool> 来问权限时,按与分发点
    // 同一个 bridgedReadPathGate 判读路径,越界 / 内部数据 / 相对路径直接拒(不弹窗、不走授权书、不走 auto 短路)。
    // 覆盖不到的:CLI 不来问的时候 —— bypass / auto 档(不带 --permission-prompt-tool)与 exec 档 DAG 节点(bypass 起)。
    // 如意自己的 MCP 工具(mcp__ruyi__*)在它自己的 toolCall 里已有文件闸,这里不重复判。
    {
      const cliToolName = String(body.toolName || '');
      if (cliToolName.startsWith('mcp__') && !cliToolName.startsWith(RUYI_MCP_CLI_TOOL_PREFIX)) {
        // 2026-10 能力总闸(纵深):CLI 直挂的内置桌面 MCP(mcp__ai-computer-control__<tool>)来问权限时,按与 09/08/12 同一个
        // toolDisabledByPolicy 判,被 allowCommandTools / allowDesktopTools(+ 这条线程的 desktopTools)关掉的直接拒,不弹窗。
        // 主防线在源头:01 把同一张表算成 ACC_HIDE_TOOLS 交给 ACC,它根本不注册这些工具;这里兜的是旧版 ACC(不认该变量)。
        // 同样覆盖不到 CLI 不来问的档(bypass / auto、exec 档 DAG 节点)—— 那几档只靠源头裁剪。
        const accPrefix = `mcp__${DESKTOP_MCP_SERVER_ID}__`;
        if (cliToolName.startsWith(accPrefix)) {
          const policyOff = toolDisabledByPolicy(cliToolName, config, sessionDesktopToolsOf(reg.session),
            { serverId: DESKTOP_MCP_SERVER_ID, toolName: cliToolName.slice(accPrefix.length) });
          if (policyOff) {
            logEvent({ kind: 'permission_bridge_policy_deny', sessionId, tool: cliToolName, reason: policyOff });
            return send(res, json({ behavior: 'deny', message: toolDisabledResult(cliToolName, policyOff).error, requestId }));
          }
        }
        const input = body.input && typeof body.input === 'object' && !Array.isArray(body.input) ? body.input : {};
        const readRefusal = await bridgedReadPathGate(cliToolName, input, { sessionId, session: reg.session, config });
        if (readRefusal) {
          logEvent({ kind: 'permission_bridge_path_deny', sessionId, tool: cliToolName, code: readRefusal.code || '' });
          return send(res, json({ behavior: 'deny', message: readRefusal.error || 'path not allowed', requestId }));
        }
      }
    }
    // v0.8-S4b: mirror the native path — carry tier + revertible so the popup renders the badge + the
    // revertibility line for CLI-bridge permission prompts too. The CLI reports its own tool names (Edit/
    // Write/Bash/…); toolIsRevertible only matches the workbench file_* set, so a native CLI Edit shows
    // 「无法自动撤销」(correct: CLI-native edits don't pass through toolCall → aren't journaled).
    // 第27波:CLI 桥授权书消耗点。命中直接 allow —— 连 permission_request 事件都不发(免弹窗静默放行)。工具名按 CLI
    // 弹窗实际显示的 Claude 名(Bash/Edit/Write)匹配,与签发卡片同名口径。范围外回落到下方正常弹窗。session 仅需 .id。
    const bridgeTier = Object.prototype.hasOwnProperty.call(CLI_TOOL_TIER, String(body.toolName || '')) ? CLI_TOOL_TIER[String(body.toolName)] : nativeToolTier(String(body.toolName || ''));   // CLI 报的是 Claude 名(Edit/Write/Bash),查 CLI 表;修前查原生表,一律落成 exec
    // 117m-A3(配 A1 的 D1):高风险判据要吃到工具名与入参,否则 CLI 桥这一侧的 auto 档还是老口径。
    // 审计 C:按【这一回合】的实效档判,不按全局档。runClaudeTurn 登记活回合时记下了 spawn CLI 用的解析档
    // (请求级 > 会话级 > 全局,10 runSessionTurn 解析);修前读 config.permissionMode —— 全局 auto 时,一条被
    // 收紧到 default/plan 的线程(或交办卡/定时任务的请求级收紧)经 CLI 桥发来的 edit/exec 请求被静默放行。
    // 登记表上没有这个值(Kimi 等其它引擎)就按会话头 + 全局解析,仍比「只看全局」更紧或相等。
    const bridgeMode = String((reg && reg.permissionMode) || resolvePermissionMode({ session: reg && reg.session, config }) || '');
    const bridgeGate = nativeToolGate(bridgeMode, bridgeTier, String(body.toolName || ''), body.input || {});
    // auto 档的低风险动作在原生引擎里已经不弹窗了,CLI 桥必须同口径 —— 否则同一个「全自动」在两个引擎
    // 下行为不一致。只对 auto 档短路(其余档位一行不变:read/bypass 的既有落点仍走下面那条路)。
    if (bridgeMode === 'auto' && bridgeGate === 'allow') {
      return send(res, json({ behavior: 'allow', updatedInput: body.input || {} }));
    }
    // 对抗轮 P3(天花板对称):与 native 主 gate 对齐 —— 仅当工作台自身权限模式对该档判定为 'ask' 时才允许授权书降级。
    // 工作台若处于 plan 模式(该档判 'block'),即便 CLI 发来请求也不放行(子集律:授权书永不把 block 提升为 allow),
    // 回落到下方正常弹窗由人定夺。default→'ask' 授权书生效;bypass→'allow' 本就免弹窗,无需授权书。
    if (bridgeGate === 'ask') {
      const grantHit = consumeGrant({ id: sessionId }, String(body.toolName || ''), body.input || {}, 'cli', null);
      // 第42b波(live 冒烟擒获):CLI ≥2.1 的 zod union 要求 allow 变体【必须】带 updatedInput record,
      // 裸 {behavior:'allow'} 会被 CLI 判 invalid_union 拒掉 → 回显原始输入。
      if (grantHit) return send(res, json({ behavior: 'allow', updatedInput: body.input || {} }));
    }
    reg.onEvent({ type: 'permission_request', requestId, toolName: body.toolName, input: body.input, tier: bridgeTier, revertible: toolIsRevertible(body.toolName) });
    registerIntervention(sessionId, 'permission', requestId, {
      toolName: String(body.toolName || ''), tier: bridgeTier, revertible: toolIsRevertible(body.toolName),
      input: body.input && typeof body.input === 'object' && !Array.isArray(body.input) ? body.input : {},
    });
    // 第27f波:CLI 桥超时→存档暂停(与 provider 路径对称)。仅【opt-in + 本会话处于无人值守 driverAuto 回合】才启用;
    // 否则维持"超时即拒杀"安全默认。两段定时:基础超时→检查点(logEvent+saveSession)+ permission_paused 事件 + 延长到 TTL;
    // TTL 内无决定则回落 deny(fail-closed)。entry.timer 重赋为 TTL 定时器,/api/permission/decision 与 clearPendingPermissions 照常清对。
    const cliPause = config.autonomyPauseOnTimeout && driverAutoSessions.has(sessionId);
    const decision = await new Promise(resolve => {
      // 128f-⑪:「等多久」问 04 的 permissionWaitMs(修前这一支只认 config,定时线程上的 CLI 引擎也是 120 s)。
      const baseMs = permissionWaitMs(sessionId, config, reg && reg.session);
      const entry = { resolve, sessionId, timer: null, deadlineAt: Date.now() + baseMs };
      if (cliPause) {
        entry.timer = setTimeout(() => {
          if (reg) reg.pausePending = true; // 第27f波:存档暂停期间豁免子进程 idle 看门狗(否则 TTL 内先杀子,窗口被截断)
          try { logEvent({ kind: 'permission_paused', sessionId, tool: String(body.toolName || ''), tier: bridgeTier, requestId, engine: 'claude' }); } catch { /* ignore */ }
          loadSession(sessionId).then(s => s && saveSession(s)).catch(() => {}); // 检查点:会话已在磁盘,重写一遍固化
          try { reg.onEvent({ type: 'permission_paused', requestId, toolName: body.toolName, tier: bridgeTier, ttlMs: config.autonomyPauseTtlMs }); } catch { /* stream gone */ }
          entry.deadlineAt = Date.now() + Math.max(60000, Number(config.autonomyPauseTtlMs) || 2700000);   // 128f-⑪:存档暂停把窗口延长了
          entry.timer = setTimeout(() => {
            const message = '权限已存档暂停但在时限内无人决定,已回落拒绝';
            runAutomaticInterventionDecision({
              missionId: sessionId, interventionId: requestId, source: 'timeout_permission', decidedBy: 'timeout',
              idempotencyKey: `timeout:${requestId}`, payload: { action: 'deny', message },
            }, () => {
              if (pendingPermissions.get(requestId) !== entry || entry.commandApplying) return;
              pendingPermissions.delete(requestId);
              resolve({ behavior: 'deny', message, pausedTimeout: true });
              settleIntervention(sessionId, requestId, 'denied', { decidedBy: 'timeout', note: 'paused ttl timeout' });
            });
          }, Math.max(60000, Number(config.autonomyPauseTtlMs) || 2700000));
        }, baseMs);
      } else {
        entry.timer = setTimeout(() => {
          const message = 'permission prompt timed out';
          runAutomaticInterventionDecision({
            missionId: sessionId, interventionId: requestId, source: 'timeout_permission', decidedBy: 'timeout',
            idempotencyKey: `timeout:${requestId}`, payload: { action: 'deny', message },
          }, () => {
            if (pendingPermissions.get(requestId) !== entry || entry.commandApplying) return;
            pendingPermissions.delete(requestId);
            resolve({ behavior: 'deny', message });
            settleIntervention(sessionId, requestId, 'denied', { decidedBy: 'timeout', note: message });
          });
        }, baseMs);
      }
      pendingPermissions.set(requestId, entry);
    });
    try { reg.onEvent({ type: 'permission_decision', requestId, behavior: decision && decision.behavior === 'allow' ? 'allow' : 'deny', message: decision && decision.message }); } catch { /* stream gone */ }
    if (reg) { reg.pausePending = false; reg.lastEventAt = Date.now(); } // 解除暂停豁免 + 重置看门狗时钟(暂停不算子进程空闲)
    if (res.writableEnded || res.destroyed) return; // request already gone (e.g. child died)
    // 第42b波(live 冒烟擒获):CLI ≥2.1 的 --permission-prompt-tool 响应是 zod union —— allow 变体必须
    // 带 updatedInput record;UI 纯「允许」(未改输入)时 decision.updatedInput 为 undefined,JSON 序列化
    // 掉键后被 CLI 拒(invalid_union: expected record, received undefined)→ 回合必败。回填原始输入。
    if (decision && decision.behavior === 'allow' && (typeof decision.updatedInput !== 'object' || decision.updatedInput === null || Array.isArray(decision.updatedInput))) {
      decision.updatedInput = body.input || {};
    }
    return send(res, json(decision));
  }
  if (req.method === 'POST' && pathname === '/api/permission/decision') {
    // 75b compatibility adapter. The entry lookup only recovers the mission partition; execution is core-owned.
    const body = await readJsonBody(req);
    const requestId = String(body.requestId || '');
    const entry = pendingPermissions.get(requestId);
    if (!entry) return send(res, json({ ok: false, error: 'unknown or expired request' }, 404));
    const behavior = body.behavior === 'allow' ? 'allow' : 'deny';
    const result = await decideIntervention({
      missionId: entry.sessionId,
      interventionId: requestId,
      payload: behavior === 'allow'
        ? { action: 'allow', updatedInput: body.updatedInput, ...(body.scope === 'session' ? { scope: 'session' } : {}) }
        : { action: 'deny', message: body.message || 'denied by user' },
      source: 'legacy_permission',
      contractRequest: false,
    });
    if (result.status === 503) return send(res, json({ ok: false, error: 'could not record the decision on disk; nothing was applied, try again' }, 503));
    if (result.status !== 200) return send(res, json({ ok: false, error: 'unknown or expired request' }, 404));
    return send(res, json({ ok: true }));
  }
  if (req.method === 'POST' && pathname === '/api/plan/decision') {
    // 75b compatibility adapter for the classic plan-mode pause.
    const body = await readJsonBody(req);
    const planId = String(body.planId || '');
    const sessionId = String(body.sessionId || '');
    const entry = pendingPlans.get(planId);
    if (!entry || entry.sessionId !== sessionId) return send(res, json({ ok: false, error: 'no pending plan' }));
    const decision = body.decision === 'approve' ? 'approve' : 'reject';
    const result = await decideIntervention({
      missionId: sessionId,
      interventionId: planId,
      payload: { action: decision, feedback: body.note != null ? String(body.note) : '' },
      source: 'legacy_plan',
      contractRequest: false,
    });
    if (result.status !== 200) return send(res, json({ ok: false, error: 'no pending plan' }));
    return send(res, json({ ok: true }));
  }
  // 75a-2: test-only CAS primitive probe (failure-injection matrix, SCHEMA §7 六窗口). Env-gated
  // (RUYI_TEST_HOOKS=1) + token; production returns 404. Not a user-facing route -- 75b 的统一契约端点
  // POST /api/missions/:missionId/interventions/:id/decision 才是对外入口。
  if (req.method === 'POST' && pathname === '/api/_test/intervention-cas') {
    if (process.env.RUYI_TEST_HOOKS !== '1') return send(res, json({ ok: false, error: 'not found' }, 404));
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const body = await readJsonBody(req);
    let result;
    try {
      // 116c: source 可由请求指定(默认仍是 'test',既有用例逐字节不变)——让 CAS 矩阵能直接验证
      // source:'steward' 的成功/版本冲突/越权三条路径在命令核心里走的是同一套判定与同一条落盘格式。
      result = await transitionInterventionState(body.sessionId, body.ivId, body.expectedVersion, body.toStatus || 'allowed', {
        crashAt: body.crashAt, decidedBy: body.decidedBy, source: String(body.source || 'test').slice(0, 64),
        action: body.actionMs ? () => new Promise(r => setTimeout(r, Number(body.actionMs) || 0)) : undefined,
      });
    } catch (e) {
      const m = String((e && e.message) || '');
      if (m.startsWith('__cas_crash:')) return send(res, json({ ok: false, reason: 'crash', at: m.slice('__cas_crash:'.length) }));
      throw e;
    }
    return send(res, json(result));
  }
  return false;
}

// ── 116c(27 号文 §11.3「116c ... steward_run_action ... 如果动作逻辑内联在路由里,先把它零行为抽成
// 可调用函数(同模块),路由改为调用它」)────────────────────────────────────────────────────────
// 五个班组动作(pause/resume/stop/retry_node/steer_node)的实现从 POST /api/agent-runs/:runId 路由体里
// 零行为搬出:每个分支原来的 `send(res, json(BODY, STATUS))` 逐个换成 `return { status, body }`,判定
// 顺序、措辞、计数(bumpRunIntervention)、事件(appendAgentRunEvent)与落盘时机一字未改。
// 不在本函数内处理的动作(apply_isolation / pool_approve / pool_reject / 未知动作)返回 null,由路由
// 沿用原有分支继续处理 —— 这样搬家对 HTTP 面是逐字节等价的。
// 归属校验(live.run.sessionId !== sessionId -> 404)在函数内【再做一次】:进程内调用方(管家)不经过
// 路由体那道闸,fail-closed 的重复判定比信任调用方便宜得多。
// 135c:线程内后台任务条里的「子代理 / 班组」两类。只看【活着的】run(activeAgentRuns,进程内真值):
// 跑完的 run 按拍板「跑完即消失」不出现,结果照旧走 background.completed 的 toast 与对话里的回执。
// sessionId 传 null = 全部线程(左栏计数用)。tail 取在跑节点最近一条 progressLog,过 redact 裁 160。
const BACKGROUND_RUN_DONE = new Set(['succeeded', 'failed', 'skipped', 'cancelled', 'stopped', 'partial']);
function sessionBackgroundRunRows(sessionId) {
  const sid = sessionId ? safeSessionId(sessionId) : '';
  const rows = [];
  for (const [runId, live] of activeAgentRuns) {
    const run = live && live.run;
    if (!run || !run.sessionId) continue;
    if (sid && run.sessionId !== sid) continue;
    const nodes = Array.isArray(run.nodes) ? run.nodes : [];
    let tail = '', tailAt = '';
    for (const node of nodes) {
      if (!node || node.status !== 'running' || !Array.isArray(node.progressLog) || !node.progressLog.length) continue;
      const last = node.progressLog[node.progressLog.length - 1];
      if (last && String(last.at || '') >= tailAt) { tailAt = String(last.at || ''); tail = String(last.text || ''); }
    }
    const first = nodes[0] || {};
    rows.push({
      id: 'run:' + runId,
      kind: (run.kind === 'spawn_agent' || nodes.length === 1) ? 'agent' : 'run', // 代理模式 v2:单节点 run 读作「代理」,多节点读作「班组」
      runId,
      sessionId: run.sessionId,
      name: String(run.title || first.task || first.id || runId).replace(/\s+/g, ' ').slice(0, 120),
      startedAt: run.createdAt || '',
      status: live.stopRequested ? 'stopping' : live.paused ? 'paused' : String(run.status || 'running'),
      progress: { done: nodes.filter(n => n && BACKGROUND_RUN_DONE.has(n.status)).length, total: nodes.length },
      tail: tail ? redact(tail.replace(/\s+/g, ' ')).slice(0, 160) : '',
    });
  }
  return rows;
}

async function agentRunActionCommand(input) {
  const o = (input && typeof input === 'object') ? input : {};
  const sessionId = safeSessionId(o.sessionId);
  const runId = safeSessionId(o.runId);
  const action = String(o.action || '');
  if (!sessionId || !runId) return { status: 400, body: { ok: false, error: 'sessionId/runId required' } };
  const live = activeAgentRuns.get(runId);
  if (live && live.run && live.run.sessionId && live.run.sessionId !== sessionId) return { status: 404, body: { ok: false, error: 'agent run not found' } };
  if (action === 'pause') {
    if (!live) return { status: 409, body: { ok: false, error: '工作流当前未运行' } };
    // 对抗轮 P3(#8): 计数按【状态迁移】幂等 —— 对已暂停 run 重复 POST(UI 按钮态滞后期双击/双面板)端点行为
    // 无害但计数器会被 UI 时延系统性抬高。只在真正 running→paused 时计一次干预(与本文件 pool_approve 先查
    // status!=='proposed' 的"无效重复不计干预"模式一致)。
    const wasPaused = live.paused === true;
    live.paused = true; live.run.pauseRequestedAt = nowIso();
    if (!wasPaused) bumpRunIntervention(live.run, 'pause'); // 29c(状态迁移才计)
    appendAgentRunEvent(live.run, { type: 'run_paused', data: { reason: 'user' } }); // 25.3
    await saveAgentRun(live.run);
    return { status: 200, body: { ok: true, state: 'pausing' } };
  }
  if (action === 'resume') {
    if (live) {
      // Reset the idle clock ATOMICALLY with clearing paused: the watchdog reads live.lastActivityAt, so by the
      // time it observes paused=false the clock is already fresh -> no false idle-abort right after a long pause.
      const wasPaused = live.paused === true; // 对抗轮 P3(#8): 仅 paused→running 计一次(对运行中 run resume 是 no-op,不计)
      live.paused = false; live.lastActivityAt = Date.now(); const waiters = live.resumeWaiters.splice(0); for (const wake of waiters) wake();
      if (wasPaused) bumpRunIntervention(live.run, 'resume'); // 29c
      appendAgentRunEvent(live.run, { type: 'run_resume_requested', data: { mode: 'warm' } }); // 25.3
      saveAgentRun(live.run).catch(() => {}); // 对抗轮修: 追写快照,让 eventSeq 尽快落盘(缩小崩溃重号窗口)
      return { status: 200, body: { ok: true, state: 'running' } };
    }
    return { status: 200, body: await launchPersistedAgentRun({ sessionId, runId, interventionKind: 'resume' }) };
  }
  if (action === 'stop') {
    if (!live) return { status: 409, body: { ok: false, error: '工作流当前未运行' } };
    const wasStopping = live.stopRequested === true; // 对抗轮 P3(#8): 重复 stop 不重复计
    live.stopRequested = true; live.paused = false; try { if (live.ctrl) live.ctrl.abort(); } catch {}
    const waiters = live.resumeWaiters.splice(0); for (const wake of waiters) wake();
    if (!wasStopping) bumpRunIntervention(live.run, 'stop'); // 29c
    appendAgentRunEvent(live.run, { type: 'run_stop_requested' }); // 25.3
    saveAgentRun(live.run).catch(() => {}); // 对抗轮修: 同 resume —— 追写快照缩小 eventSeq 崩溃重号窗口
    return { status: 200, body: { ok: true, state: 'stopping' } };
  }
  if (action === 'retry_node') {
    if (live) return { status: 409, body: { ok: false, error: '请先等待或停止当前运行' } };
    const nodeId = String(o.nodeId || '').trim();
    return { status: 200, body: await launchPersistedAgentRun({ sessionId, runId, retryNodeId: nodeId, retryCascade: o.cascade === true, interventionKind: 'retry_node' }) };
  }
  // Directional node steering. Provider nodes consume at their next iteration boundary; Claude nodes consume
  // through the live stream-json stdin channel. Queued nodes keep the message until their model starts.
  if (action === 'steer_node') {
    if (!live) return { status: 409, body: { ok: false, error: '工作流当前未运行，无法插话' } };
    // 停止收尾窗口：stop 已经请求（或 ctrl 已中止）之后，节点即将被标记 cancelled，不会再有下一次迭代边界来
    // 消费插话队列；此时接受插话只会让用户误以为它会生效，直接拒绝更诚实。
    if (live.stopRequested || (live.ctrl && live.ctrl.signal && live.ctrl.signal.aborted)) return { status: 409, body: { ok: false, error: '工作流正在停止，无法插话' } };
    const nodeId = String(o.nodeId || '').trim();
    if (!nodeId) return { status: 400, body: { ok: false, error: 'nodeId required' } };
    // 团队模式 v2 (B1): 投递资格判定与 send_to_agent 共用同一小函数(不复制两份),reason 各自映射为本处既有措辞。
    const elig = nodeDeliveryEligibility(live.run, nodeId, { allowClaude: true });
    if (elig.reason === 'not_found') return { status: 404, body: { ok: false, error: '节点不存在' } };
    if (elig.reason === 'deterministic_gate') return { status: 409, body: { ok: false, error: '确定性质量门节点不经过模型，无法插话' } };
    if (elig.reason === 'terminal') return { status: 409, body: { ok: false, error: '节点已结束，无法插话' } };
    if (!elig.ok) return { status: 409, body: { ok: false, error: { code: 'agent_run.mailbox_closed', params: { reason: elig.reason }, message: '节点正在收尾，无法插话' } } };
    const text = String(o.text || '').trim().slice(0, 2000);
    if (!text) return { status: 400, body: { ok: false, error: '插话内容不能为空' } };
    if (!live.steerQueues) live.steerQueues = new Map();
    let q = live.steerQueues.get(nodeId);
    if (!q) { q = []; live.steerQueues.set(nodeId, q); }
    if (q.length >= STEER_QUEUE_MAX) return { status: 409, body: { ok: false, error: '该节点插话队列已满' } };
    q.push(text);
    bumpRunIntervention(live.run, 'steer_node'); // 29c(队列在内存,计数随下一次快照落盘即可,不额外写盘)
    return { status: 200, body: { ok: true, queued: q.length, live: elig.node.status === 'running' } };
  }
  return null; // 本函数不认识的动作(apply_isolation / pool_* / 未知)——由路由沿用原分支
}

async function handleAgentRunApiRoutes(req, res, pathname) {
  if (req.method === 'GET' && pathname === '/api/agent-runs') {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const listUrl = new URL(req.url, 'http://x');
    const sessionId = safeSessionId(listUrl.searchParams.get('sessionId'));
    if (!sessionId) return send(res, json({ ok: false, error: 'sessionId required' }, 400));
    // digest 视图只要标量:走按 mtime+size 缓存的 listAgentRunDigests(08),未变的 run 文件零读盘;完整视图照旧读全量。
    const digestView = listUrl.searchParams.get('view') === 'digest';
    const readRuns = () => (digestView ? listAgentRunDigests(sessionId) : listAgentRuns(sessionId));
    const liveBefore = [...activeAgentRuns.keys()]; let runs = await readRuns(); if (liveBefore.some(id => !activeAgentRuns.has(id))) runs = await readRuns();   // 读盘期间有 run 收尾（终稿落盘后才撤活对象）：先前读到的是收尾前快照、却已不算 live（提案仍 proposed）→ 重读一次拿终稿
    // A live run's in-memory state is newer than its throttled crash-recovery snapshot. Return a detached
    // copy of that state for the full polling view, otherwise short nodes can finish before their intermediate
    // progressLog snapshot is ever observable and the UI falsely looks frozen.
    // digest(每 2s 轮询)只从这里读标量、不外发也不改对象:浅展开即与深拷贝读到的值逐字段相同,
    // 省掉每个 live run 整份节点/结果/progressLog 的 JSON 往返。完整视图照旧深拷贝(对象要外发)。
    for (let i = 0; i < runs.length; i += 1) {
      const live = activeAgentRuns.get(runs[i].id);
      if (!live || !live.run) continue;
      runs[i] = { ...(digestView ? live.run : JSON.parse(JSON.stringify(live.run))), live: true, paused: !!live.paused };
    }
    // 第29波(§29a): digest 轻量视图 —— 增量客户端每 tick 只拉这份 run 级标量做变更探测(eventSeq/status/
    // updatedAt),不再每 2s 重传全部节点(单节点 result≤24KB + roleSnapshot 8KB prompt,历史终态 run 每 tick
    // 白传)。live run 的 eventSeq/status/updatedAt 以【内存】为准(快照节流 1.5s,磁盘恒旧);快照仍是唯一
    // 权威状态源,digest 只是"该不该去拉"的信号。
    if (digestView) {
      // runs 此刻是磁盘摘要(live 且有内存对象的已被上面换成 live.run 的浅展开);逐行装配见 08 agentRunDigestRow。
      const digest = runs.map(r => agentRunDigestRow(r, activeAgentRuns.get(r.id)));
      return send(res, json({ ok: true, view: 'digest', runs: digest }));
    }
    return send(res, json({ ok: true, runs }));
  }
  // 第29波(§29a): 增量事件消费 —— 客户端记住 lastSeq,断线/重开后 afterSeq=lastSeq 重发即天然补播;
  // seq 严格单调(25.3)保证补播无重无漏。必须排在文件底部 GET /api/agent-runs/:id 通配前缀分支之前,
  // 否则被吞。跨会话防护与快照端点同源:事件文件按 sessionId 分目录,错 session 只会 404→空数组。
  if (req.method === 'GET' && pathname.startsWith('/api/agent-runs/') && pathname.endsWith('/events')) {
    if (!tokenOk(req)) return send(res, json({ ok: false, error: 'missing or invalid workbench token' }, 403));
    const evUrl = new URL(req.url, 'http://x');
    const sessionId = safeSessionId(evUrl.searchParams.get('sessionId'));
    const evParts = pathname.split('/').filter(Boolean); // ['api','agent-runs',runId,'events']
    const runId = evParts.length === 4 ? safeSessionId(evParts[2]) : null;
    if (!sessionId || !runId) return send(res, json({ ok: false, error: 'sessionId/runId required' }, 400));
    const afterSeq = Number(evUrl.searchParams.get('afterSeq')) || 0;
    const { events, hasMore } = await readAgentRunEvents(sessionId, runId, afterSeq, Number(evUrl.searchParams.get('limit')) || 0);
    return send(res, json({ ok: true, runId, afterSeq, events, hasMore }));
  }
  if (req.method === 'POST' && pathname.startsWith('/api/agent-runs/')) {
    const parts = pathname.split('/').filter(Boolean);
    const runId = safeSessionId(parts[2]);
    const body = await readJsonBody(req);
    const sessionId = safeSessionId(body.sessionId);
    const action = String(body.action || '');
    if (!sessionId || !runId) return send(res, json({ ok: false, error: 'sessionId/runId required' }, 400));
    const live = activeAgentRuns.get(runId);
    // runId 是全局命名空间（不像持久化文件那样按 sessionId 分目录），live runtime 挂在内存 Map 里也不天然按
    // sessionId 隔离——不加这层校验，一个知道/猜到 runId 的会话就能 pause/resume/stop/steer 另一个会话正在跑的
    // 工作流。对齐 apply_isolation 从文件读到 run 后做的 run.sessionId !== sessionId 校验语义，统一在这里拦截，
    // 对 pause/resume/stop/steer_node 全部生效；resume 的冷启动分支（live 为空）走 launchPersistedAgentRun，
    // 本来就按 sessionId 找持久化文件，不受影响。
    if (live && live.run && live.run.sessionId && live.run.sessionId !== sessionId) return send(res, json({ ok: false, error: 'agent run not found' }, 404));
    // 116c: pause/resume/stop/retry_node/steer_node 五个动作的实现搬到 agentRunActionCommand(同模块,
    // 零行为);本路由只做 HTTP 适配。其余动作(apply_isolation / pool_*)返回 null,继续走下面的原分支。
    {
      const cmd = await agentRunActionCommand({ sessionId, runId, action, nodeId: body.nodeId, text: body.text, cascade: body.cascade === true });
      if (cmd) return send(res, json(cmd.body, cmd.status));
    }
    if (action === 'apply_isolation') {
      if (live) return send(res, json({ ok: false, error: '请先等待当前运行结束' }, 409));
      const nodeId = String(body.nodeId || '').trim();
      const run = safeJsonParse(await fsp.readFile(agentRunFile(sessionId, runId), 'utf8').catch(() => ''), null);
      if (!run || run.sessionId !== sessionId) return send(res, json({ ok: false, error: 'agent run not found' }, 404));
      const applied = await applyAgentWorktree(run, nodeId).catch(e => ({ ok: false, error: String(e && (e.gitStderr || e.message) || e), ...(e && e.cleanupIncomplete ? { cleanupIncomplete: true } : {}), ...(e && e.applicationUnconfirmed ? { applicationUnconfirmed: true, applied: e.applied === true, commit: e.commit } : {}) }));
      return send(res, json(applied, applied.ok ? 200 : 409));
    }
    // 75b compatibility adapter: pool approval/rejection shares decideIntervention with the Mission contract.
    if (action === 'pool_approve' || action === 'pool_reject') {
      const poolId = String(body.poolId || '').trim();
      if (!poolId) return send(res, json({ ok: false, error: 'poolId required' }, 400));
      const result = await decideIntervention({
        missionId: sessionId,
        interventionId: poolId,
        requestRunId: runId,
        payload: { action: action === 'pool_approve' ? 'approve' : 'reject' },
        source: 'legacy_pool',
        contractRequest: false,
      });
      if (result.status !== 200) {
        const reason = String(result.body && result.body.reason || '');
        if (!live || live.closing) return send(res, json({ ok: false, error: '运行已结束;可在新运行中执行该任务' }, 409));
        if (reason === 'not_found') return send(res, json({ ok: false, error: '提案不存在' }, 404));
        const item = (Array.isArray(live.run.taskPool) ? live.run.taskPool : []).find(p => p && String(p.id) === poolId);
        if (item && item.status !== 'proposed') return send(res, json({ ok: false, error: `该提案已处理(${item.status})` }, 409));
        const message = result.body && result.body.error && result.body.error.message;
        return send(res, json({ ok: false, error: message || '运行已结束或提案已处理' }, result.status === 404 ? 404 : 409));
      }
      return send(res, json({
        ok: true,
        status: action === 'pool_approve' ? 'materialized' : 'rejected',
        poolId,
        ...(result.body.nodeId ? { nodeId: result.body.nodeId } : {}),
      }));
    }
    return send(res, json({ ok: false, error: 'unknown action' }, 400));
  }
  if (req.method === 'DELETE' && pathname.startsWith('/api/agent-runs/')) {
    const runId = safeSessionId(pathname.slice('/api/agent-runs/'.length));
    const sessionId = safeSessionId(new URL(req.url, 'http://x').searchParams.get('sessionId'));
    if (!sessionId || !runId) return send(res, json({ ok: false, error: 'sessionId/runId required' }, 400));
    if (activeAgentRuns.has(runId)) return send(res, json({ ok: false, error: '运行中的工作流不能删除' }, 409));
    try {
      const file = agentRunFile(sessionId, runId);
      const run = safeJsonParse(await fsp.readFile(file, 'utf8'), null);
      for (const node of (run && run.nodes || [])) if (node.isolation) await cleanupAgentWorktree(node.isolation);
      await fsp.unlink(file);
      AgentRunStore.invalidateDigest(file);   // digest 摘要缓存(08):文件没了条目一并撤
      // 对抗轮修(第25波): 删除快照必须连带删姊妹事件日志 —— 用户删「运行记录」的心智模型是数据消失,
      // 取证 ndjson(含时间线/错误切片)不该在删除后无限期残留。
      await fsp.unlink(agentRunEventsFile(sessionId, runId)).catch(() => {});
      await fsp.unlink(agentRunEventsFile(sessionId, runId) + '.gz').catch(() => {}); // v1.9 数据管家: 归档压缩变体一并删
    } catch { return send(res, json({ ok: false, error: 'agent run not found' }, 404)); }
    await bumpMissionChangeSeq(sessionId, {
      type: 'run_deleted', cursor: { runId }, detail: { runId },
    });
    RUYI_EVENTS.emit('thread.state', { sessionId });   // 128f-⑫:行上的「最后一次班组」换了一条(或没了)
    return send(res, json({ ok: true }));
  }
  if (req.method === 'GET' && pathname.startsWith('/api/agent-runs/')) {
    if (!tokenOk(req)) return send(res, apiFailure('auth.token_invalid', {}, 'missing or invalid workbench token', 403));
    const sessionId = safeSessionId(new URL(req.url, 'http://x').searchParams.get('sessionId'));
    const runId = safeSessionId(pathname.slice('/api/agent-runs/'.length));
    if (!sessionId || !runId) return send(res, apiFailure('agent_run.id_required', {}, 'sessionId/runId required', 400));
    // 第29波(§29a): live run 以【内存】对象下发 —— 增量客户端在 settle 类事件后靠本端点刷新单 run 状态,
    // 磁盘快照节流 1.5s 恒旧,读盘会让客户端 lastSeq 与状态错位(拿旧状态配新 seq)。JSON.stringify 同步
    // 执行,事件循环内原子,无撕裂读。归属校验与 POST action 的 live 分支同源(sessionId 不符 = 404)。
    const liveOne = activeAgentRuns.get(runId);
    if (liveOne && liveOne.run) {
      if (liveOne.run.sessionId !== sessionId) return send(res, json({ ok: false, error: 'agent run not found' }, 404));
      return send(res, json({ ok: true, run: { ...liveOne.run, live: true, paused: !!liveOne.paused } }));
    }
    try {
      const run = safeJsonParse(await fsp.readFile(agentRunFile(sessionId, runId), 'utf8'), null);
      if (!run) throw new Error('invalid run');
      if (EventStreamHooks.projectAgentMessageReceipts) EventStreamHooks.projectAgentMessageReceipts(run);
      return send(res, json({ ok: true, run }));
    } catch { return send(res, json({ ok: false, error: 'agent run not found' }, 404)); }
  }
  return false;
}

// ============================================================================
// 第75c波(Pretender P1):Mission / Intervention 可重建物化索引、revision cursor 与 ETag。
// 权威源始终是 session head、Intervention journal、run snapshot 与 usage ledger；本文件只维护可删缓存。
// ============================================================================
// 116-5b:2 -> 3。事项卡片的形状变了(加了 displayTitle 与 brief,见 13d buildMissionCard)。
// 不升号的话,盘上那些 sourceStamp 没变过的会话【不会重建】,它们的卡片会一直缺这两个键 —— 壳层
// 那句 displayTitle || title 于是一直回落到原话,而摘要明明已经写在会话头上了。索引是纯派生物
// (durable-state 清册记的就是 fully regenerable),升号的代价只是启动后第一次读时全量重建一次。
// 117p-S2:3 -> 4。卡片又加了 turnSeq 与 lastTurn(30 号文 §8.3,五态判据的新证据)。这次【必须】
// 强制整份重建,而不只是形状升级 —— 否则存量那些已经跑完的管家线程的旧卡片永远不会再刷新
// (它们的会话文件不会再变,sourceStamp 不动),无账本线程的五态就一直卡在「交办中」。
// 117r-D1:4 -> 5。这次变的不是卡片【形状】而是卡片的【产生条件】(见下方 buildPretenderSessionSlice:
// 管家关心的线程现在也有卡片)。不升号的话,存量索引里这些会话的行就是 card:null,而它们的会话文件
// 不会再变(sourceStamp 不动),增量刷新永远不碰它们 —— 用户已经有的那些速查线程会一直不出现在看板上。
// 与 117p-S2 同一条理由:索引是纯派生物,升号的代价只是启动后第一次读时全量重建一次。
// 121-K3:5 -> 6。这次卡片的【形状】与【产生条件】一起变了:行上新增 origin/watched 两个持久字段
// (cardRevision 也把它们算进哈希),产生条件从 watched 一条线换成 threadVisible 四条并集(§4.2)。
// 不升号的话,存量索引里用户自己在 2.0 开的那些会话仍是 card:null,而它们的会话文件不会再变
// (sourceStamp 不动),增量刷新永远不碰它们 —— 本刀要修的那个症状会原样留在存量机器上。
// 性能批 P3:6 -> 7。finalize 里切片的排序从 localeCompare 换成码位序:id 带大写 / 下划线 / 连字符时两种次序不同,
// 而 missionsRevision 是按行序算的哈希 —— 不升号,盘上旧索引的修订号会与同一份事实新算出来的对不上。代价同前:升级后
// 首次读全量重建一次。
// 62: card health summaries are new persistent projection facts; old source stamps must rebuild them.
const PRETENDER_INDEX_SCHEMA = 8;
const PRETENDER_INDEX_DIR = '.pretender';
const PRETENDER_INDEX_FILE = 'projection-index.json';
const PRETENDER_PAGE_DEFAULT = 100;
const PRETENDER_PAGE_MAX = 200;

const pretenderIndexRuntime = {
  value: null,
  diskStamp: '',
  persisted: false,
  building: null,
  fullDirty: false,
  dirtySessions: new Set(),
  usageDirty: new Set(),
  // 121-K3(34 号文 §13.3 登记的那条竞态):上一次【真的扫过 sessions 目录】时,那个目录的 mtime,
  // 以及那次扫描完成的时刻。两个值一起用才判得出「这次扫描可信不可信」,见下面 PRETENDER_DIR_SETTLE_MS。
  sourcesDirStamp: '',
  sourcesScannedAt: 0,
  // 性能批 P2:
  //   headMtimes —— 每条会话头文件的 mtime(每次给会话算源指纹时顺手记下)。「最近 N 条」窗口从这里排,
  //     不再每次刷新都把 sessions 目录里每个头文件 stat 一遍。
  //   verifyScan / lastVerifyAt / verifyTimer —— 目录变了只比对文件名单(一次 readdir),已有文件被外部原地替换
  //     这一种由后台低频全量校验兜住(PRETENDER_VERIFY_MS 一次,不在请求路径上)。
  //   persistTimer —— 增量刷新后的落盘合并成一次延迟写(冷重建仍立即落盘)。
  headMtimes: new Map(),
  verifyScan: null,             // 后台校验在建索引链之外先扫好的 { sources, dirStamp },建索引时只做比对
  lastVerifyAt: 0,
  verifyTimer: null,
  knownMasks: new Map(),        // 会话 id -> 文件组成(1 = 会话头,2 = Intervention journal),名单比对的基准
  usageSeq: null,               // 已吸收到的用量账变更序号(00-boot usageLedgerChangesSince);null = 基准未知,下一次整份对账
  // ownMarks —— 本进程写口打脏页的累计次数;ownMarksAtScan —— 上一次看目录(名单比对或全量扫描)时的
  //   pretenderOwnWriteSeq()(脏页次数 + 01 的 sessionsDirOwnWriteSeq:会话索引、搜索索引这类不打脏页、但同样落在
  //   sessions 目录里的原子写 —— 审查轮复现过:漏掉它们时每次落盘后的下一次读都多付一遍全量扫描)。
  //   目录指纹变了、而这期间本进程一次都没写过:这次变化只可能来自外部(导入 / 手工编辑 / 夹具原地替换),
  //   当次就做一遍全量比对(121-K3 的「下一次读就看得见」逐字保住);有本进程写入时照旧只比名单。
  ownMarks: 0,
  ownMarksAtScan: 0,
  persistTimer: null,
  writers: 0,
  writeChain: Promise.resolve(),
  sliceBytes: new WeakMap(),
  counters: { fullSourceScans: 0, nameDiffScans: 0, sliceBuilds: 0, persists: 0 },
};
// 后台全量校验的最短间隔。程序自己的写口都会打脏页(02/08 的 markPretenderIndexDirty),MCP 子进程写会话一律回环到
// 主进程 HTTP;需要这道校验的只剩外部导入 / 手工编辑 / 测试夹具「原地替换已有会话文件」—— 30 秒内被看到。
const PRETENDER_VERIFY_MS = 30000;
const PRETENDER_PERSIST_DEBOUNCE_MS = 1000;

// 121-K3:目录 mtime 的「沉降窗口」。
// 病根不是 K0b 修的那个(空目录时建出空索引并缓存),而是它的一般形式:**投影索引一旦进了进程内存,
// buildOrLoadPretenderIndex 的 `if (!value)` 就短路掉整段「扫目录 + sameSourceMap 比对」,此后外部
// 写进 sessions 目录的会话【永远】不被发现** —— 没有人给它们打脏页(markPretenderIndexDirty 只长在
// 应用自己的写口上)。导入、多进程写入、以及本仓大量「boot 之后才 seed」的夹具都是这个形状;
// 121-K1 那次全量真红(冷列表 300 条没读满)就是它。
// 自愈判据用【目录级】指纹:一次 stat(paths.sessions) 就够(NTFS/ext4 都在增删条目时更新父目录 mtime),
// 不必为每次读都付一遍 300 条会话 × 3 次 syscall 的全量扫描。
// 但 mtime 有粒度:扫描如果发生在最后一次写的【同一毫秒附近】,这个指纹就还没稳定下来 ——
// 那正是「一边写一边读」的现场。所以只信任「扫描时刻比目录 mtime 晚至少 1 秒」的那一次指纹;
// 更年轻的指纹一律重扫。代价有界:一阵写完之后,第一次落在 1 秒之外的扫描就把指纹变成可信的,
// 此后每次读只多一次 stat。
const PRETENDER_DIR_SETTLE_MS = 1000;

async function pretenderSessionsDirStamp() {
  try { return String(Math.trunc((await fsp.stat(paths.sessions)).mtimeMs)); } catch { return '-'; }
}
function pretenderSourcesTrusted(dirStamp) {
  if (pretenderIndexRuntime.sourcesDirStamp !== dirStamp) return false;
  const mtime = Number(dirStamp);
  if (!Number.isFinite(mtime)) return false;                       // 目录读不到:永远重扫(扫一次也很便宜)
  return pretenderIndexRuntime.sourcesScannedAt - mtime >= PRETENDER_DIR_SETTLE_MS;
}
function pretenderNoteSourcesScan(dirStamp) {
  pretenderIndexRuntime.sourcesDirStamp = dirStamp;
  pretenderIndexRuntime.sourcesScannedAt = Date.now();
  pretenderIndexRuntime.ownMarksAtScan = pretenderOwnWriteSeq();
}
function pretenderOwnWriteSeq() { return pretenderIndexRuntime.ownMarks + sessionsDirOwnWriteSeq; }

function pretenderIndexPath() {
  return path.join(paths.sessions, PRETENDER_INDEX_DIR, PRETENDER_INDEX_FILE);
}

// Called by authoritative writers in earlier source modules. A dirty mark never blocks the write; the next
// read refreshes only that session slice. `usage` is separate because refreshing it requires scanning ledgers.
function markPretenderIndexDirty(sessionId, reason = 'source') {
  const sid = safeSessionId(sessionId);
  pretenderIndexRuntime.ownMarks += 1;
  if (!sid) { pretenderIndexRuntime.fullDirty = true; return; }
  pretenderIndexRuntime.dirtySessions.add(sid);
  if (reason === 'usage') pretenderIndexRuntime.usageDirty.add(sid);
}

// Invalidation is synchronous with authoritative writes; readers never observe an unmarked commit.
RUYI_EVENTS.subscribe((name, payload) => {
  if (name === 'projection.invalidated') markPretenderIndexDirty(payload?.sessionId, payload?.reason);
});

function pretenderHash(value) {
  return crypto.createHash('sha256').update(typeof value === 'string' ? value : JSON.stringify(value), 'utf8').digest('hex').slice(0, 24);
}

async function pretenderFileStamp(file) {
  try {
    const st = await fsp.stat(file);
    return `${st.size}:${Math.trunc(st.mtimeMs)}`;
  } catch { return '-'; }
}

async function pretenderSessionSourceStamp(sessionId) {
  const sid = safeSessionId(sessionId);
  if (!sid) return '-';
  const head = await fsp.stat(sessionPath(sid)).catch(() => null);
  if (head) pretenderIndexRuntime.headMtimes.set(sid, Math.trunc(head.mtimeMs));
  else pretenderIndexRuntime.headMtimes.delete(sid);
  const parts = [
    'h=' + (head ? `${head.size}:${Math.trunc(head.mtimeMs)}` : '-'),
    'i=' + await pretenderFileStamp(interventionFilePath(sid)),
  ];
  const dir = agentRunDir(sid);
  let files = [];
  try { files = (await fsp.readdir(dir)).filter(f => /^run_[a-f0-9]+\.json$/i.test(f)).sort(); } catch { files = []; }
  for (const file of files) parts.push('r=' + file + ':' + await pretenderFileStamp(path.join(dir, file)));
  return pretenderHash(parts.join('|'));
}

// sessions 目录里「有会话头或有 Intervention journal」的会话 id(一次 readdir,不 stat)。
// 返回 id -> 文件组成(1 = 会话头,2 = Intervention journal)。审查轮:只比 id 的话,已有会话头的会话后来才长出
// journal(外部登记了一条待决)这一种会漏;比文件组成就能在这一次读里看见。
async function pretenderListSourceIds() {
  let files = [];
  try { files = await fsp.readdir(paths.sessions); } catch { files = []; }
  const masks = new Map();
  for (const file of files) {
    if (/^sess_[A-Za-z0-9_-]+\.json$/.test(file)) { const id = file.slice(0, -5); masks.set(id, (masks.get(id) || 0) | 1); }
    else if (/^sess_[A-Za-z0-9_-]+\.interventions\.ndjson$/.test(file)) { const id = file.slice(0, -'.interventions.ndjson'.length); masks.set(id, (masks.get(id) || 0) | 2); }
  }
  return masks;
}

async function scanPretenderSessionSources() {
  pretenderIndexRuntime.counters.fullSourceScans += 1;
  const masks = await pretenderListSourceIds();
  pretenderIndexRuntime.knownMasks = masks;
  for (const sid of [...pretenderIndexRuntime.headMtimes.keys()]) if (!masks.has(sid)) pretenderIndexRuntime.headMtimes.delete(sid);
  const ids = [...masks.keys()].sort();
  const sources = {};
  let cursor = 0;
  const workers = Array.from({ length: Math.min(16, Math.max(1, ids.length)) }, async () => {
    while (cursor < ids.length) {
      const sid = ids[cursor++];
      sources[sid] = await pretenderSessionSourceStamp(sid);
    }
  });
  await Promise.all(workers);
  return sources;
}

// 121-K3(34 号文 §4.1 第三条「最近 N 条」):任务索引窗口里那 N 个 sessionId。
// 按【会话文件 mtime】排,不按会话头里的 updatedAt —— 后者要把每个头都读出来解析一遍 JSON,
// 而这一步只是为了决定「要不要给它造卡片」,一次 readdir + 每文件一次 stat 就够
// (scanPretenderSessionSources 每条会话本来就付着更贵的 2 次 stat + 一次 readdir)。
// 两者的偏差只在「文件写过但 updatedAt 没动」这种退化情形,而那恰恰也算「最近动过」。
// N 取自配置(config.threadIndexRecent,清洗块已 clamp 到 [10,200]);读不到配置就用默认 30,
// 绝不因为配置读失败把索引缩成空(fail-open:这里是可见性窗口,不是权限门)。
async function pretenderRecentSessionIds() {
  const config = await readConfig().catch(() => null);
  const raw = Number(config && config.threadIndexRecent);
  const limit = Number.isFinite(raw)
    ? Math.min(THREAD_INDEX_RECENT_MAX, Math.max(THREAD_INDEX_RECENT_MIN, Math.round(raw)))
    : THREAD_INDEX_RECENT_DEFAULT;
  // 性能批 P2:mtime 取自 headMtimes(每次算源指纹时记下的),不再每次刷新都把全部会话头 stat 一遍。
  // 这张表在每次全量扫描、名单比对新增、脏页刷新时都会被更新,覆盖的正是 sessions 目录里现存的会话头。
  const rows = [...pretenderIndexRuntime.headMtimes.entries()];
  // 末位按 sessionId 降序兜确定性:同毫秒写入的两条会话不该因为目录枚举顺序漂移而轮流进窗口。
  rows.sort((a, b) => b[1] - a[1] || String(b[0]).localeCompare(String(a[0])));
  return new Set(rows.slice(0, limit).map(row => row[0]));
}

async function pretenderUsageSourceStamp() {
  let files = [];
  try { files = (await fsp.readdir(paths.usage)).filter(f => /^\d{4}-\d{2}\.jsonl$/.test(f)).sort(); } catch { files = []; }
  const parts = [];
  for (const file of files) parts.push(file + ':' + await pretenderFileStamp(path.join(paths.usage, file)));
  return pretenderHash(parts.join('|'));
}

function emptyMissionUsage() {
  return { inTok: 0, outTok: 0, cachedInTok: 0, turns: 0, subagentTurns: 0, costsByCurrency: {} };
}

function addMissionUsageRow(usage, row) {
  usage.inTok += Number(row && row.inTok) || 0;
  usage.outTok += Number(row && row.outTok) || 0;
  usage.cachedInTok += Number(row && row.cachedInTok) || 0;
  usage.turns += 1;
  if (row && row.kind === 'subagent') usage.subagentTurns += 1;
  const cost = Number(row && row.cost);
  const currency = row && typeof row.currency === 'string' ? row.currency : '';
  if (row && row.costTrusted !== false && currency && Number.isFinite(cost)) {
    usage.costsByCurrency[currency] = (usage.costsByCurrency[currency] || 0) + cost;
  }
}

function finishMissionUsage(usage) {
  for (const key of Object.keys(usage.costsByCurrency)) usage.costsByCurrency[key] = Math.round(usage.costsByCurrency[key] * 1e6) / 1e6;
  return usage;
}

// sessionIds(可选):只聚合这几条会话 —— 每轮对话后的增量刷新只需要被打了 usage 脏页的那几条(性能批 P1)。
async function buildMissionUsageMap(sessionIds = null) {
  const map = new Map();
  await forEachUsageRow(0, row => {
    const sid = String(row && row.sessionId || '');
    if (!sid) return;
    let usage = map.get(sid);
    if (!usage) map.set(sid, usage = emptyMissionUsage());
    addMissionUsageRow(usage, row);
  }, sessionIds ? { sessionIds } : {});
  for (const usage of map.values()) finishMissionUsage(usage);
  return map;
}

async function buildPretenderSessionSlice(sessionId, sourceStamp, usage, recentIds) {
  const sid = safeSessionId(sessionId);
  if (!sid) return null;
  pretenderIndexRuntime.counters.sliceBuilds += 1;
  const head = safeJsonParse(await fsp.readFile(sessionPath(sid), 'utf8').catch(() => ''), null);
  let ivMeta = await readInterventionsWithMeta(sid);
  if ((!head || !head.id) && ivMeta.bytes === 0) return null;
  // External/legacy journals also get bounded maintenance on a rebuild. Never compact degraded authority.
  if (!ivMeta.degraded && interventionJournalWorthCompacting(ivMeta)) {   // 判据与 02 自己的周期压实同一个(修前这里也是 ×3,永不触发)
    await compactInterventionJournal(sid).catch(() => {});
    ivMeta = await readInterventionsWithMeta(sid);
    sourceStamp = await pretenderSessionSourceStamp(sid);
  }
  const kind = head && head.id ? sessionKind(head) : 'orphan';
  const missionId = (head && sessionMissionId(head)) || sid;
  // ── 卡片的产生条件(121-K3,34 号文 §4.2「索引口径」)────────────────────────────────────
  // 117r-D1 把它从「只给 mission 造」放宽到「mission ∪ 管家关心的线程」,理由写在那一版注释里
  // (管家开的速查线程当时在看板上根本不存在)。但那一版仍是【一个判据管两件事】:
  // 「管家要不要动手」同时当成了「它要不要出现在索引里」,于是用户自己在 2.0 里开的普通会话
  // (missionId === sessionId、无 stewardQuick、无 launchedBy)永远不进 /api/missions ——
  // §1.3 数过的那条病根,而它当时被写成「刻意的,理由是噪音」。
  //
  // K3 把一个判据拆成两个(判据本体都在 06i,这里只消费,不新造):
  //   · watched = stewardWatchedThread —— 管家要不要为它动手(收件箱第四源用的还是这一条);
  //   · visible = threadVisible —— 它要不要进索引。四条并集:在途 ∪ 今天有动静 ∪ 最近 N 条 ∪ watched。
  // 噪音不再靠「把整类线程挡在门外」治,靠【窗口】治(§4.2):几百条旧会话既不在途、今天也没动静、
  // 又排不进最近 N 条,自然不进索引;进了索引的旧线程在界面上也只落「更早」组。
  //   · inFlight 是「五态非 done/stopped」的机器事实那一半:此刻有活回合,或挂着未决。
  //     两者都是这里现成的(activeChildren 与刚读出来的 ivMeta),不为它多读一次盘。
  //   · recentIds 由调用方一次算好整份(pretenderRecentSessionIds),每条会话只做一次 Set 查询。
  // 注:orphan(只有 Intervention journal、没有会话头)天然为 false —— 两个判据的第一行都挡住
  // head 为空的情况,不必在这里再写一道。
  const watched = stewardWatchedThread(head, sid, missionId);
  const origin = threadOriginOf(head);
  const inFlight = activeChildren.has(sid)
    || (Array.isArray(ivMeta.interventions) && ivMeta.interventions.some(iv => iv && iv.status === 'pending'));
  const carded = kind === 'mission' || threadVisible(head, {
    now: Date.now(),
    watched,
    inFlight,
    recent: recentIds instanceof Set ? recentIds.has(sid) : false,
  });
  const runs = carded ? await listAgentRuns(sid).catch(() => []) : [];
  const card = carded
    ? await buildMissionCard(head, runs, { interventions: ivMeta.interventions, persistent: true })
    : null;
  const usageFact = usage || emptyMissionUsage();
  const changeSeq = Math.max(0, Number(head && head.mission && head.mission.changeSeq) || 0);
  // 121-K3:origin/watched 进哈希。它们是【持久】字段(跟着切片落盘),不进哈希的话
  // 「用户按下交给管家盯」这种只改 stewardWatch 的写会拿不到新 ETag,左栏画的还是旧标。
  const cardRevision = pretenderHash({ missionId, changeSeq, card, origin, watched });
  const missionRevision = pretenderHash({ cardRevision, usage: usageFact });
  // Health is part of the semantic projection, but physical row/byte counts are not (compaction must keep
  // revision stable). A newly corrupt authority line therefore invalidates ETags even when valid facts match.
  const interventionRevision = pretenderHash({ interventions: ivMeta.interventions, degraded: ivMeta.degraded, corruptLines: ivMeta.corruptLines });
  return {
    sessionId: sid,
    missionId,
    kind,
    // 121-K3(§4.1):来源三值与「管家盯着没有」。两个都是从会话头派生的持久事实,行上直接带着 ——
    // 消费者(左栏、总览、收件箱)零改动即能画来源图形与「交给管家盯」的开关态。
    origin,
    watched,
    changeSeq,
    sourceStamp,
    indexedAt: nowIso(),
    card,
    usage: usageFact,
    interventions: ivMeta.interventions,
    integrity: { degraded: ivMeta.degraded, corruptLines: ivMeta.corruptLines, journalRows: ivMeta.rowCount, journalBytes: ivMeta.bytes },
    cardRevision,
    missionRevision,
    interventionRevision,
    revision: pretenderHash([missionRevision, interventionRevision]),
  };
}

function validatePretenderIndex(value) {
  if (!value || value.schemaVersion !== PRETENDER_INDEX_SCHEMA || !Array.isArray(value.sessions)) return false;
  if (!value.sources || typeof value.sources !== 'object' || typeof value.usageStamp !== 'string') return false;
  return value.sessions.every(row => row && typeof row.sessionId === 'string' && typeof row.revision === 'string');
}

async function readPretenderIndexDisk() {
  try {
    const value = safeJsonParse(await fsp.readFile(pretenderIndexPath(), 'utf8'), null);
    return validatePretenderIndex(value) ? value : null;
  } catch { return null; }
}

function sameSourceMap(a, b) {
  const ak = Object.keys(a || {}).sort(), bk = Object.keys(b || {}).sort();
  return ak.length === bk.length && ak.every((key, i) => key === bk[i] && a[key] === b[key]);
}

// 性能批 P2:大小估算按切片缓存(增量刷新之间没变的切片对象原样复用),不再每次 finalize 都把整份索引 stringify 一遍。
function pretenderSliceBytes(row) {
  let bytes = pretenderIndexRuntime.sliceBytes.get(row);
  if (bytes === undefined) { bytes = Buffer.byteLength(JSON.stringify(row), 'utf8') + 1; pretenderIndexRuntime.sliceBytes.set(row, bytes); }
  return bytes;
}
// 性能批 P3:热路径排序按码位比(localeCompare 走 ICU 排序规则,慢一个数量级;id 与 ISO 时间戳要的就是码位序)。
function pretenderCompareCodeUnits(a, b) { return a < b ? -1 : (a > b ? 1 : 0); }

function finalizePretenderIndex(sessions, sources, usageStamp, buildReason) {
  sessions.sort((a, b) => pretenderCompareCodeUnits(String(a.sessionId), String(b.sessionId)));
  const missionRows = sessions.filter(row => row.card);
  const missionsRevision = pretenderHash(missionRows.map(row => [row.missionId, row.cardRevision || row.missionRevision]));
  // 只进 ETag、不进分页游标:列表行上的费用来自切片用量,用量变了要换 ETag,但不该让翻到一半的分页 409(审查轮)。
  const missionsUsageRevision = pretenderHash(missionRows.map(row => row.missionRevision || ''));
  const interventionsRevision = pretenderHash(sessions.map(row => [row.sessionId, row.interventionRevision]));
  const revision = pretenderHash([missionsRevision, interventionsRevision]);
  const degradedSessions = sessions.filter(row => row.integrity && row.integrity.degraded).map(row => row.sessionId);
  const value = {
    schemaVersion: PRETENDER_INDEX_SCHEMA,
    revision,
    missionsRevision,
    missionsUsageRevision,
    interventionsRevision,
    builtAt: nowIso(),
    buildReason,
    sources,
    usageStamp,
    sessions,
    degraded: { active: degradedSessions.length > 0, sessions: degradedSessions },
  };
  let sliceBytes = 0;
  for (const row of sessions) sliceBytes += pretenderSliceBytes(row);
  value.estimatedBytes = sliceBytes + Buffer.byteLength(JSON.stringify({ ...value, sessions: [] }), 'utf8');
  return value;
}

// 所有写盘串在一条链上(审查轮:冷重建的立即写与延迟写交错时,旧的那份可能最后落地)。
function writePretenderIndexFile(value) {
  const run = pretenderIndexRuntime.writeChain.then(() => writePretenderIndexFileNow(value));
  pretenderIndexRuntime.writeChain = run.catch(() => false);
  return run;
}
async function writePretenderIndexFileNow(value) {
  const file = pretenderIndexPath();
  // writers:改名落盘到记下新 diskStamp 之间,盘上那份与 diskStamp 对不上是我们自己造成的,别当成「用户动了缓存」。
  pretenderIndexRuntime.writers += 1;
  try {
    await fsp.mkdir(path.dirname(file), { recursive: true });
    // 性能批 P2:紧凑 JSON(索引是可删缓存、没人读它;atomicWriteJson 缺省的两格缩进让 7 MB 的索引多出四成字节与序列化时间)
    await atomicWriteJson(file, JSON.stringify(value));
    pretenderIndexRuntime.counters.persists += 1;
    pretenderIndexRuntime.diskStamp = await pretenderFileStamp(file);
    return true;
  } catch {
    // Cache write failure never compromises authority or blocks reads. Keep the current in-memory projection.
    pretenderIndexRuntime.diskStamp = await pretenderFileStamp(file);
    return false;
  } finally { pretenderIndexRuntime.writers -= 1; }
}
// 冷重建(索引缺失/损坏/显式重建)立即落盘 —— 「坏索引读一次就原子重建回盘上」是既有承诺。
async function persistPretenderIndex(value) {
  pretenderIndexRuntime.persisted = await writePretenderIndexFile(value);
}
// 增量刷新(脏页、目录变化、用量变化)的落盘合并成一次延迟写,不放在请求路径上。进程退出时没写的那一份丢了也无妨:
// 索引是纯派生物,下次启动按源指纹只刷变了的那几片。
function schedulePretenderPersist() {
  if (pretenderIndexRuntime.persistTimer) return;
  pretenderIndexRuntime.persistTimer = setTimeout(() => {
    pretenderIndexRuntime.persistTimer = null;
    void flushPretenderPersist().catch(() => {});
  }, PRETENDER_PERSIST_DEBOUNCE_MS);
  if (pretenderIndexRuntime.persistTimer.unref) pretenderIndexRuntime.persistTimer.unref();
}
async function flushPretenderPersist() {
  while (pretenderIndexRuntime.building) await pretenderIndexRuntime.building.catch(() => {});
  const value = pretenderIndexRuntime.value;
  if (!value || pretenderIndexRuntime.persisted) return;
  // 数据目录已经被删了(清数据、测试收尾)就别再把它建回来(审查轮)
  if (!fs.existsSync(paths.sessions)) return;
  const ok = await writePretenderIndexFile(value);
  if (pretenderIndexRuntime.value === value) pretenderIndexRuntime.persisted = ok;
  else schedulePretenderPersist();   // 写的期间又刷新过:下一拍再写最新那一份
}
// 后台低频全量校验:到点先在链外扫好,再走一次 getPretenderProjectionIndex 做比对。
// 全量扫描(逐条 stat)在建索引链之外先做 —— 扫描期间来的请求不必排在它后面(审查轮);建索引时只拿结果做比对。
async function pretenderRunVerify() {
  pretenderIndexRuntime.lastVerifyAt = Date.now();
  if (!fs.existsSync(paths.sessions)) return null;
  const dirStamp = await pretenderSessionsDirStamp();
  const sources = await scanPretenderSessionSources();
  pretenderIndexRuntime.verifyScan = { sources, dirStamp };
  return getPretenderProjectionIndexShared();   // 自己这次构建不再武装下一轮:没人读时后台校验就停下,不空转
}
function pretenderScheduleVerify() {
  if (pretenderIndexRuntime.verifyTimer || pretenderIndexRuntime.verifyScan) return;
  const wait = Math.max(0, pretenderIndexRuntime.lastVerifyAt + PRETENDER_VERIFY_MS - Date.now());
  pretenderIndexRuntime.verifyTimer = setTimeout(() => {
    pretenderIndexRuntime.verifyTimer = null;
    void pretenderRunVerify().catch(() => {});
  }, wait);
  if (pretenderIndexRuntime.verifyTimer.unref) pretenderIndexRuntime.verifyTimer.unref();
}

async function rebuildPretenderIndexFull(reason, knownSources) {
  const sources = knownSources || await scanPretenderSessionSources();
  const usageMap = await buildMissionUsageMap();
  const recentIds = await pretenderRecentSessionIds();   // 121-K3:整份算一次,每条会话只做一次 Set 查询
  let ids = Object.keys(sources).sort(), cursor = 0;
  const sessions = [];
  const workers = Array.from({ length: Math.min(12, Math.max(1, ids.length)) }, async () => {
    while (cursor < ids.length) {
      const sid = ids[cursor++];
      const slice = await buildPretenderSessionSlice(sid, sources[sid], usageMap.get(sid), recentIds);
      if (slice) { sources[sid] = slice.sourceStamp; sessions.push(slice); }
    }
  });
  await Promise.all(workers);
  return finalizePretenderIndex(sessions, sources, await pretenderUsageSourceStamp(), reason);
}

async function refreshPretenderIndexSlices(base, dirtyIds, usageIds, reason) {
  const sources = { ...(base.sources || {}) };
  const rows = new Map(base.sessions.map(row => [row.sessionId, row]));
  const usageMap = usageIds.size ? await buildMissionUsageMap(usageIds) : null;
  // 先给这几条会话算源指纹(顺手更新 headMtimes),再排「最近 N 条」窗口 —— 121-K3:一条刚被写过的会话恰恰最可能
  // 【刚刚】挤进最近 N 条,拿旧窗口判它等于让新会话晚一整轮才上索引。
  // 性能批 P2:与全量重建同样按 12 路并发池跑(修前逐条串行 —— 启动后外部一次物化几百条会话时,这里一条一条等 IO)。
  // 每条会话只动自己那一格,行序由 finalize 统一排序,并发不改变结果。
  const ids = [...dirtyIds];
  const pool = async work => {
    let cursor = 0;
    await Promise.all(Array.from({ length: Math.min(12, Math.max(1, ids.length)) }, async () => {
      while (cursor < ids.length) await work(ids[cursor++]);
    }));
  };
  const stamps = new Map();
  await pool(async sid => { stamps.set(sid, await pretenderSessionSourceStamp(sid)); });
  const recentIds = await pretenderRecentSessionIds();
  await pool(async sid => {
    const stamp = stamps.get(sid);
    if (!fs.existsSync(sessionPath(sid)) && !fs.existsSync(interventionFilePath(sid))) { delete sources[sid]; rows.delete(sid); return; }
    sources[sid] = stamp;
    const previous = rows.get(sid);
    const usage = usageIds.has(sid) ? usageMap.get(sid) : (previous && previous.usage);
    const slice = await buildPretenderSessionSlice(sid, stamp, usage, recentIds);
    if (slice) { sources[sid] = slice.sourceStamp; rows.set(sid, slice); } else { delete sources[sid]; rows.delete(sid); }
  });
  const usageStamp = usageIds.size ? await pretenderUsageSourceStamp() : base.usageStamp;
  return finalizePretenderIndex([...rows.values()], sources, usageStamp, reason);
}

// 性能批 P2:账本变了(上次落盘之后又跑过回合)只重算每片的用量事实,不再把每条会话从盘上整份重建 ——
// 修前这是启动时最常见的一种「全量重建」(退出前最后几轮的用量还没随索引落盘)。
// 与 buildPretenderSessionSlice 里同一套算法:missionRevision = hash({cardRevision, usage}),revision = hash([missionRevision, interventionRevision])。
// sessionIds(可选):只对这几条会话重算(用量账变更日志说只有它们变了)。一片都没变就原样返回 base。
async function refreshPretenderUsageFacts(base, reason, sessionIds = null) {
  const usageMap = await buildMissionUsageMap(sessionIds);
  let changed = false;
  const sessions = base.sessions.map(row => {
    if (sessionIds && !sessionIds.has(row.sessionId)) return row;
    const usage = usageMap.get(row.sessionId) || emptyMissionUsage();
    if (JSON.stringify(usage) === JSON.stringify(row.usage)) return row;
    changed = true;
    const missionRevision = pretenderHash({ cardRevision: row.cardRevision, usage });
    return { ...row, usage, missionRevision, revision: pretenderHash([missionRevision, row.interventionRevision]) };
  });
  const usageStamp = await pretenderUsageSourceStamp();
  if (!changed && usageStamp === base.usageStamp) return base;
  return finalizePretenderIndex(sessions, { ...(base.sources || {}) }, usageStamp, reason);
}

function pretenderChangedSourceIds(before, after) {
  const ids = new Set([...Object.keys(before || {}), ...Object.keys(after || {})]);
  return new Set([...ids].filter(id => (before || {})[id] !== (after || {})[id]));
}

async function buildOrLoadPretenderIndex() {
  const indexFile = pretenderIndexPath();
  const currentDiskStamp = await pretenderFileStamp(indexFile);
  // User deleted/replaced/corrupted the cache while the process was live: discard memory and prove rebuild.
  // 性能批 P2:判据是「盘上那份不再是我们最后一次写 / 读到的那份」(diskStamp),不再要求 persisted —— 增量刷新改成
  // 延迟落盘之后,等写的那一秒里用户删了缓存,照样丢内存、从权威源重建(修前每次刷新都立即落盘,persisted 恒真)。
  if (pretenderIndexRuntime.value && pretenderIndexRuntime.writers === 0 && pretenderIndexRuntime.diskStamp
    && currentDiskStamp !== pretenderIndexRuntime.diskStamp) {
    pretenderIndexRuntime.value = null;
  }

  // ── 121-K3(§13.3):目录级自愈 ───────────────────────────────────────────────────────
  // 下面那句 `if (!value)` 是热路径的命根子(不能每次读都全量扫目录),但它同时也是 §13.3 那条
  // 竞态的病根:索引进了内存之后,外部写进 sessions 目录的会话【永远】不被发现。
  // 这里用一次 stat 把两件事都照顾到:目录指纹没变且已经沉降 -> 什么都不做(热路径逐字不变);
  // 指纹变了、或者变得太新(还在一边写一边读的窗口里)-> 看一眼目录,真有差异才按差异刷【那几片】。
  // 性能批 P2:「看一眼」从「每条会话 2 次 stat + 1 次 readdir」降成【一次 readdir 比对名单】—— 目录 mtime 在
  // 本进程每次原子落盘会话头时都会变,修前每次落盘后的下一次读都付一整遍全量扫描(2000 条会话约 300 ms)。
  // 新出现 / 消失的会话、已有会话新长出(或没了)journal,照旧在这一次读里就刷好(K3 的保证不变,比的是每条会话的
  // 文件组成);只有「外部原地替换 / 改写已有文件」这一种(名单与组成都不变),由后台全量校验兜住 —— 目录变过之后
  // 最多 PRETENDER_VERIFY_MS 看见。本进程自己的写口本来就打脏页,MCP 子进程写会话回环到主进程,都不靠这一步。
  // 例外(全量回归复现过,steward-thread-order ③):目录指纹变了、这期间本进程却一次脏页都没打 —— 变化只可能是外部的,
  // 名单比对看不见原地替换,就当次做一遍全量比对(与修前同价,只落在「纯外部改动」这一种上;本进程落盘后的读仍只比名单)。
  const dirStamp = await pretenderSessionsDirStamp();
  const verifyScan = pretenderIndexRuntime.verifyScan;
  pretenderIndexRuntime.verifyScan = null;
  if (pretenderIndexRuntime.value && verifyScan) {
    const base = pretenderIndexRuntime.value;
    pretenderNoteSourcesScan(verifyScan.dirStamp);
    if (!sameSourceMap(base.sources, verifyScan.sources)) {
      pretenderIndexRuntime.value = await refreshPretenderIndexSlices(base, pretenderChangedSourceIds(base.sources, verifyScan.sources), new Set(), 'sources_verify');
      pretenderIndexRuntime.persisted = false;
    }
  } else if (pretenderIndexRuntime.value && pretenderIndexRuntime.sourcesDirStamp !== dirStamp
    && pretenderOwnWriteSeq() === pretenderIndexRuntime.ownMarksAtScan) {
    const base = pretenderIndexRuntime.value;
    const sources = await scanPretenderSessionSources();
    pretenderNoteSourcesScan(dirStamp);
    pretenderIndexRuntime.lastVerifyAt = Date.now();
    if (!sameSourceMap(base.sources, sources)) {
      pretenderIndexRuntime.value = await refreshPretenderIndexSlices(base, pretenderChangedSourceIds(base.sources, sources), new Set(), 'sources_dir_changed');
      pretenderIndexRuntime.persisted = false;
    }
  } else if (pretenderIndexRuntime.value && !pretenderSourcesTrusted(dirStamp)) {
    const base = pretenderIndexRuntime.value;
    pretenderIndexRuntime.counters.nameDiffScans += 1;
    const masks = await pretenderListSourceIds();
    pretenderNoteSourcesScan(dirStamp);
    const known = pretenderIndexRuntime.knownMasks;
    const changed = new Set();
    for (const [id, mask] of masks) if (known.get(id) !== mask) changed.add(id);
    for (const id of known.keys()) if (!masks.has(id)) changed.add(id);
    // 索引里有、名单基准里没有的(不该发生,防御):也按名单对一遍
    for (const id of Object.keys(base.sources || {})) if (!masks.has(id)) changed.add(id);
    pretenderIndexRuntime.knownMasks = masks;
    if (changed.size) {
      pretenderIndexRuntime.value = await refreshPretenderIndexSlices(base, changed, new Set(), 'sources_dir_changed');
      pretenderIndexRuntime.persisted = false;   // 变过就得重新落盘(下面统一那一处写)
    }
  }

  let value = pretenderIndexRuntime.value;
  let cold = false;
  if (!value) {
    const disk = await readPretenderIndexDisk();
    const sources = await scanPretenderSessionSources();
    pretenderNoteSourcesScan(dirStamp);
    pretenderIndexRuntime.lastVerifyAt = Date.now();
    // 用量基准:先取变更序号、再算源指纹 —— 两者之间追加进来的行会让指纹对不上,走整份对账,不会漏。
    const usageBaseline = await usageLedgerChangesSince(Number.MAX_SAFE_INTEGER);
    pretenderIndexRuntime.usageSeq = usageBaseline.seq;
    const usageStamp = await pretenderUsageSourceStamp();
    if (!disk) {
      // 121-K0b(病根在此):原来的空目录守卫只长在 warmPretenderProjectionIndex 里,只护 boot 那一次
      // 预热。13i 的收件箱 tick 与其他任何调用方一样直接走 getPretenderProjectionIndex -> 这里,不经过
      // warm。当索引文件从未建过(currentDiskStamp === '-',即真·首次)且 sessions 目录此刻确实一份
      // sess_* 都没有(scanPretenderSessionSources 的 sources 为空)时,不能走下面的 rebuildPretenderIndexFull:
      // 那会把一份空索引落盘(persistPretenderIndex)并存进 pretenderIndexRuntime.value——下一次
      // 调用会发现 diskStamp 没变就直接信任这份【已缓存为已建】的空索引,永远不再重新发现
      // (`if (!value)` 短路)。管家默认开着(121-K0)之后,服务起来的第一拍收件箱 tick 就会撞上这个
      // 窗口——外部导入/多进程写入/本仓大量夹具都在 boot 之后才把会话物化到盘上。
      // 修法:直接 return 一份不落盘、不缓存为已建的空索引,下一次调用(不论隔多久)重新 scanPretenderSessionSources
      // 发现磁盘上的真会话。disk 索引已存在时(currentDiskStamp !== '-',对应下面 corrupt_index 分支)不受影响——
      // 那是「索引文件在但读不出来」,与「索引从未建过」是两回事,仍应立即重建并落盘。
      if (currentDiskStamp === '-' && Object.keys(sources).length === 0) {
        return finalizePretenderIndex([], sources, usageStamp, 'empty_sessions_dir');
      }
      value = await rebuildPretenderIndexFull(currentDiskStamp === '-' ? 'missing_index' : 'corrupt_index', sources);
      cold = true;
    } else {
      value = disk;
      if (!sameSourceMap(disk.sources, sources)) value = await refreshPretenderIndexSlices(disk, pretenderChangedSourceIds(disk.sources, sources), new Set(), 'source_changed');
      if (value.usageStamp !== usageStamp) value = await refreshPretenderUsageFacts(value, 'usage_source_changed');
      if (value === disk) {
        pretenderIndexRuntime.diskStamp = currentDiskStamp;
        pretenderIndexRuntime.persisted = true;
      }
    }
  }

  // 用量账变了哪些会话(00-boot 的变更日志,本进程追加与外部写进来的一视同仁):只重算那几片的用量事实。
  // 修前索引一旦进了内存,外部写账【永远】看不见(只在启动读盘那一次比 usageStamp)。冷重建刚从整份账算过,跳过。
  if (value && !cold) {
    const change = await usageLedgerChangesSince(pretenderIndexRuntime.usageSeq);
    if (change.all) value = await refreshPretenderUsageFacts(value, 'usage_source_changed');
    else if (change.sessionIds.size) value = await refreshPretenderUsageFacts(value, 'usage_source_changed', change.sessionIds);
    pretenderIndexRuntime.usageSeq = change.seq;
  }

  const forceFull = pretenderIndexRuntime.fullDirty;
  pretenderIndexRuntime.fullDirty = false;
  const dirtyIds = new Set(pretenderIndexRuntime.dirtySessions);
  const usageIds = new Set(pretenderIndexRuntime.usageDirty);
  pretenderIndexRuntime.dirtySessions.clear();
  pretenderIndexRuntime.usageDirty.clear();
  if (forceFull) {
    pretenderIndexRuntime.usageSeq = (await usageLedgerChangesSince(Number.MAX_SAFE_INTEGER)).seq;   // 基准先取,再整份算
    value = await rebuildPretenderIndexFull('explicit_rebuild');
    cold = true;
  }
  else if (dirtyIds.size) value = await refreshPretenderIndexSlices(value, dirtyIds, usageIds, usageIds.size ? 'usage_dirty' : 'source_dirty');

  if (value !== pretenderIndexRuntime.value || !pretenderIndexRuntime.persisted) {
    if (cold) await persistPretenderIndex(value);
    else { pretenderIndexRuntime.persisted = false; schedulePretenderPersist(); }
  }
  pretenderIndexRuntime.value = value;
  return value;
}

// 测试直调(unit/pretender-index-incremental):计数、立即走一次后台校验、立即落盘。不改任何行为。
const pretenderIndexTestHooks = {
  stats: () => ({ ...pretenderIndexRuntime.counters, persisted: pretenderIndexRuntime.persisted, verifyArmed: Boolean(pretenderIndexRuntime.verifyTimer) }),
  verifyNow: () => pretenderRunVerify(),
  flushPersist: () => flushPretenderPersist(),
};

// 审查轮:后台校验由【每一次真实读取】武装(PRETENDER_VERIFY_MS 一轮),不再只在「目录变过」之后武装一次 ——
// 修前原地改写已有文件(目录 mtime 不动)永远不会被看见,校验跑过一次之后也不再重来。
// 校验自己触发的那次构建走 getPretenderProjectionIndexShared,不武装:页面关了、没人读,后台就不再扫。
async function getPretenderProjectionIndex() {
  const index = await getPretenderProjectionIndexShared();
  if (pretenderIndexRuntime.value) pretenderScheduleVerify();
  return index;
}
async function getPretenderProjectionIndexShared() {
  if (pretenderIndexRuntime.building) return pretenderIndexRuntime.building;
  const current = buildOrLoadPretenderIndex();
  pretenderIndexRuntime.building = current;
  try { return await current; }
  finally { if (pretenderIndexRuntime.building === current) pretenderIndexRuntime.building = null; }
}

// Wave 80: warm an existing projection as soon as the local service is listening. The empty-directory
// guard here just skips the boot-time warm call entirely when there is nothing to warm yet (cheap early
// return, no index built, no disk touched) — it does not need to protect every caller against trusting an
// empty index. 121-K0b moved that protection to the root (buildOrLoadPretenderIndex above): every caller of
// getPretenderProjectionIndex, not only this boot-time warmer, now gets an unpersisted/uncached empty
// projection when sessions haven't materialized yet, so this function's own check is now redundant-but-
// harmless (kept for its boot-time short-circuit, not for correctness).
async function warmPretenderProjectionIndex() {
  let files = [];
  try { files = await fsp.readdir(paths.sessions); } catch { return null; }
  if (!files.some(file => /^sess_[A-Za-z0-9_-]+(?:\.json|\.interventions\.ndjson)$/.test(file))) return null;
  return getPretenderProjectionIndex();
}

function encodePretenderCursor(kind, revision, offset, limit) {
  return Buffer.from(JSON.stringify({ v: 1, k: kind, r: revision, o: offset, l: limit }), 'utf8').toString('base64url');
}

function decodePretenderCursor(raw) {
  try {
    const value = JSON.parse(Buffer.from(String(raw || ''), 'base64url').toString('utf8'));
    if (!value || value.v !== 1 || typeof value.k !== 'string' || typeof value.r !== 'string' || !Number.isInteger(value.o) || value.o < 0) return null;
    return value;
  } catch { return null; }
}

function paginatePretenderProjection(req, kind, revision, items) {
  const query = new URL(req.url, 'http://127.0.0.1').searchParams;
  const requestedLimit = Number(query.get('limit'));
  let limit = Number.isFinite(requestedLimit) && requestedLimit > 0 ? Math.floor(requestedLimit) : PRETENDER_PAGE_DEFAULT;
  limit = Math.max(1, Math.min(PRETENDER_PAGE_MAX, limit));
  let offset = 0;
  const rawCursor = query.get('cursor');
  if (rawCursor) {
    const cursor = decodePretenderCursor(rawCursor);
    if (!cursor || cursor.k !== kind) return { response: apiFailure('projection.invalid_cursor', { kind }, 'invalid pagination cursor', 400) };
    if (cursor.r !== revision) {
      return { response: apiFailure('projection.snapshot_changed', { cursorRevision: cursor.r, projectionRevision: revision, restartCursor: null }, 'projection changed; restart pagination', 409) };
    }
    offset = cursor.o;
    if (!query.has('limit') && Number.isInteger(cursor.l)) limit = Math.max(1, Math.min(PRETENDER_PAGE_MAX, cursor.l));
  }
  const pageItems = items.slice(offset, offset + limit);
  const nextOffset = offset + pageItems.length;
  const nextCursor = nextOffset < items.length ? encodePretenderCursor(kind, revision, nextOffset, limit) : null;
  return {
    items: pageItems,
    page: { limit, offset, count: pageItems.length, total: items.length, nextCursor, projectionRevision: revision },
  };
}

function pretenderEtag(kind, revision, page) {
  const suffix = page ? `-${page.offset}-${page.limit}` : '';
  return `W/\"${kind}-${revision}${suffix}\"`;
}

// ETag includes volatile overlay state, while pagination cursors deliberately carry only the persistent
// projection revision. A run/turn heartbeat therefore refreshes conditional reads without invalidating pages.
function pretenderLiveOverlayRevision(sessionId = '') {
  const sid = String(sessionId || '');
  const rows = [];
  const sessionIds = sid ? [sid] : (pretenderIndexRuntime.value && Array.isArray(pretenderIndexRuntime.value.sessions) ? pretenderIndexRuntime.value.sessions : []).map(row => row.sessionId);
  for (const id of sessionIds) rows.push(['execution', id, sessionExecutionSnapshot(id), stewardThreadTurnQueued(id)]);
  // 121-K3:活回合这一行带上 liveTail 摘要的三个值。修前它只有 ['turn', id] —— 一个回合从起跑到
  // 收工整段时间里 ETag 一动不动,而卡片上的「正在调什么」每几百毫秒就变一次,兜底轮询于是永远
  // 拿 304、永远画着第一帧。overlayMissionCard 往卡片里放了什么,这里就得跟着算什么。
  for (const [id, reg] of activeChildren) {
    if (sid && id !== sid) continue;
    const tail = (reg && reg.liveTail && typeof reg.liveTail === 'object') ? reg.liveTail : null;
    rows.push(['turn', id, tail ? String(tail.tool || '') : '', tail ? String(tail.updatedAt || '') : '',
      tail ? Math.max(0, Number(tail.iterations) || 0) : 0]);
  }
  // 同理:在场(§4.3 的 seatedBy)也进卡片,也就必须进这份 revision —— 用户从 X 换坐到 Y,
  // 两行卡片的 seatedBy 都变了,ETag 不动的话左栏要等到下一次会话头写盘才更新。
  try {
    const presence = typeof EventStreamHooks.presenceSnapshot === 'function' ? EventStreamHooks.presenceSnapshot() : [];
    for (const row of (Array.isArray(presence) ? presence : [])) {
      const seated = String((row && row.sessionId) || '');
      if (!seated || (row && row.lens) !== 'classic') continue;
      if (sid && seated !== sid) continue;
      rows.push(['seat', seated]);
    }
  } catch { /* 在场读不到就当没人坐着 —— 与 overlayMissionCard 同一条 fail-open */ }
  for (const runtime of activeAgentRuns.values()) {
    const run = runtime && runtime.run;
    if (!run || (sid && run.sessionId !== sid)) continue;
    rows.push(['run', run.sessionId, run.id, run.status, Number(run.eventSeq) || 0, run.updatedAt || '', Boolean(runtime.paused), agentRunHealth(run, true)]);
  }
  rows.sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b)));
  return pretenderHash(rows);
}

function pretenderNotModified(req, etag) {
  return String(req.headers['if-none-match'] || '').split(',').map(v => v.trim()).includes(etag);
}

function pretenderIndexMeta(index) {
  return {
    projectionRevision: index.revision,
    builtAt: index.builtAt,
    estimatedBytes: index.estimatedBytes,
    persisted: pretenderIndexRuntime.persisted,
    degraded: index.degraded,
  };
}

// overlayAt:批量调用方(GET /api/missions、聚合装配)传入同一个「叠加时刻」,省掉逐行 nowIso();不传则各取各的(其余调用方不变)。
function overlayMissionCard(slice, overlayAt) {
  const card = slice && slice.card;
  if (!card) return null;
  const liveRuns = [];
  for (const runtime of activeAgentRuns.values()) if (runtime && runtime.run && runtime.run.sessionId === slice.sessionId) liveRuns.push(runtime.run);
  liveRuns.sort((a, b) => String(a.updatedAt || '').localeCompare(String(b.updatedAt || '')));
  const latestLive = liveRuns.length ? liveRuns[liveRuns.length - 1] : null;
  const activeTurn = activeChildren.has(slice.sessionId);
  // hunt3:回合排在 13n 仲裁器里(还没进 activeChildren)—— 五态 queued 证据键,与 activeTurn 同一条「只活在叠加层」纪律。
  const queued = stewardThreadTurnQueued(slice.sessionId);
  // 117l D4(§11.9):「它在问你」只活在叠加层 —— 待决的死活与活回合都是此刻的事实,写进持久卡片
  // 就会在下一次重建前一直说谎(与 activeTurn / lastRun 同一条纪律)。判据单点同样是 06i 的 stewardAsksYou。
  // 117m-A2:判据单点从 stewardAsksYou 换成 stewardAsksYouForThread —— 后者认【四类待决】
  // (question > permission > plan > pool),而这里修前只挑 question,于是挂着 permission 的线程
  // 在看板行永远拿不到 asksYou(用户第六轮走查⑥:标着「需要你」的行上一枚 pill 都没有)。
  // 抽取待决行的那一段一并搬进 06i:两个调用面(13g 与本处)现在喂的是同一个入参形状。
  const pending = (Array.isArray(slice.interventions) ? slice.interventions : [])
    .filter(iv => iv && iv.status === 'pending');
  const asksYou = stewardAsksYouForThread({
    pending,
    activeTurn,
    lastAssistantText: String(card.lastSay || ''),
  });
  // 121-K3(§4.2「行加 liveTail 摘要」/ §5「左栏在跑组每行的第二行」):正在调什么工具、第几次、
  // 什么时候有的输出。**摘要不带正文** —— `text`/`full` 一个字都不进来(§6.1 的红线:观察面不承载
  // 工具输出正文;要正文的面走 GET /api/sessions/:id 的 liveTail,那里有自己的预算与门)。
  // 没有活回合就是 null,不编一个空壳出来让消费者分不清「没在跑」与「在跑但还没输出」。
  const liveReg = activeTurn ? activeChildren.get(slice.sessionId) : null;
  const liveTailReg = (liveReg && liveReg.liveTail && typeof liveReg.liveTail === 'object') ? liveReg.liveTail : null;
  const liveTail = liveTailReg ? {
    tool: String(liveTailReg.tool || ''),
    updatedAt: String(liveTailReg.updatedAt || ''),
    iterations: Math.max(0, Number(liveTailReg.iterations) || 0),
  } : null;
  // 121-K3(§4.3/§4.5):用户此刻是不是就坐在这条线程前面。事实源是 13r 的在场快照(SSE 连接自报的
  // lens/sessionId),经 00-boot 的延迟绑定命名空间取 —— 13e 拼在 13r 之前,直引 13r 的符号是前向边。
  // 钩子没填充(13r 还没加载 / 事件流关着)或抛错,一律当「没人坐着」:在场信号缺席时管家照旧行事,
  // 这是 fail-open,因为它管的是【打扰纪律】不是权限。
  let seatedBy = null;
  try {
    const presence = typeof EventStreamHooks.presenceSnapshot === 'function' ? EventStreamHooks.presenceSnapshot() : [];
    if (Array.isArray(presence) && presence.some(row => row && row.lens === 'classic' && String(row.sessionId || '') === slice.sessionId)) {
      seatedBy = 'user';
    }
  } catch { seatedBy = null; }
  return {
    ...card,
    // 121-K3:两个持久字段随卡片一起下发(切片上有,卡片上没有 —— 消费者读的是卡片)。
    origin: String(slice.origin || 'user'),
    watched: slice.watched === true,
    liveTail,
    seatedBy,
    activeTurn,
    execution: sessionExecutionSnapshot(slice.sessionId),
    queued,
    asksYou,
    runCount: Math.max(Number(card.runCount) || 0, liveRuns.length),
    lastRun: latestLive ? missionRunDigest(latestLive, true) : card.lastRun,
    healthRuns: [...new Map([
      ...(Array.isArray(card.healthRuns) ? card.healthRuns : []).map(run => [run.id, run]),
      ...liveRuns.map(run => [run.id, missionRunDigest(run, true)]),
    ]).values()],
    freshness: {
      persistentRevision: slice.cardRevision || slice.missionRevision,
      indexedAt: slice.indexedAt,
      liveOverlay: activeTurn || queued || liveRuns.length > 0,
      overlayAt: overlayAt || nowIso(),
    },
  };
}

// ============================================================================
// 第 116 波 116b(27 号文 §11.3「116b 收件箱与游标」)/ 116-2e 拆分:管家(Steward)收件箱轮询器与游标。
//
// 拆分来源(116-2e):本文件的全部内容原本是 `13g-steward.js` 的前半(第 1 行到 handleStewardApiRoutes
//   之前),零行为搬家 —— 函数体一行未改,只改了本文件头注释。拆分理由:13g 已 1993 行触到 SPEC §2 的
//   2000 行目标上限,116-2e 还要往它的 handleStewardApiRoutes 与工具管道里加东西。
// 落点(transport 层,manifest 中位于 13e-pretender-index.js 之后、13g-steward.js 之前):
//   只能【前置】—— `steward-runner.static` 同时锁着「13h 紧跟 13g」与「13h 紧邻 14-main」,
//   13g 与 13h 之间没有位置;前置模块只能承载 13g 的【上游】部分(收件箱),否则出前向边。
//
// 本文件把【三条现成的 seq 日志】增量读成【五类白名单事件】,落进管家自己的两个文件。
// 它不改任何执行语义 —— 只读别人的账,只写自己的箱。路由、决策日志、记忆存储与 21 个管家工具
// 仍住 13g(它拼接在本文件之后,引用本文件的符号全部是后向边)。
//
// 三个源(全部是既有权威源,本波不新增任何写入端):
//   ① Mission Change Ledger  `readMissionChangesWithMeta(sessionId, currentRevision)`(02-session-store.js)
//      —— per-session append-only,seq = mission.changeSeq(单调 revision)。
//   ② agent run 事件日志      `readAgentRunEvents(sessionId, runId, afterSeq, limit)`(08-agent-runs.js)
//      —— per-run append-only,seq = run.eventSeq(单调)。
//   ③ 待决投影                `getPretenderProjectionIndex()`(13e-pretender-index.js)
//      —— 可重建物化索引,给出每个会话的 pending Intervention 列表与 mission card(含预算耗尽标记)。
//
// 依赖纪律(§11.3「不得新增前向边」):
//   · 13i 只引用拼接顺序在它之前的模块符号(00/01/01b/02/08/13e/06i …),全部后向边;
//   · 13-http-router.js 【不得】直接引用本文件的任何符号 —— 那会是前向边。挂接改走延迟绑定:
//     13g 在加载时 `Object.assign(StewardHooks, { handleApiRoutes, stopInbox, inboxRead, inboxState })`,
//     其中后三个键的实现就在本文件里(13g → 13i 是后向边),13 只写 `StewardHooks.handleApiRoutes`;
//   · 14-main.js 在 startServer 返回(服务已监听)后调用 `startStewardInbox(config)`(14 → 13i 后向边)。
//
// 开关(§3.4 红线):`stewardEnabledV1 !== true` 时本文件【零副作用】—— 不起 interval、不建
// `<data>/steward/` 目录、不写任何文件;四条路由(住 13g)仍在(路由清册不因开关变化),start 返回 409
// `steward.disabled`,state 返回 enabled:false,inbox 读一个不存在的文件得空数组(不 mkdir)。
// ============================================================================
// ── 落盘常量 ────────────────────────────────────────────────────────────────
const STEWARD_DIR_NAME = 'steward';
const STEWARD_INBOX_FILE = 'inbox-v1.ndjson';
const STEWARD_CURSOR_FILE = 'cursor-v1.json';
const STEWARD_CURSOR_SCHEMA = 1;

// ── 归一化/合并常量 ──────────────────────────────────────────────────────────
// §11.3:同 sessionId 同 kind(同 runId)窗口内合并为一条。117m-A1:5s → 30s。5 秒窗口在真机上几乎
// 不合并任何东西 —— 同一条线程的失败/停滞信号往往隔十几秒才来第二条,于是管家一条一条汇报、一条起
// 一个回合(用户第六轮走查②「管家还是会一条条汇报,没有必要还费 Token」)。纯批处理收益:分组键
// (sessionId\0kind\0runId)与「同类 N 条」文案一字未动,只是把攒批的窗口拉长。
const STEWARD_MERGE_WINDOW_MS = 30000;
const STEWARD_SUMMARY_CHARS = 200;         // payload 摘要硬顶(与 STEWARD_DIGEST_LIMITS.lastSayChars 同数)
const STEWARD_MERGED_SEQS_MAX = 20;        // 合并行里回填的源 seq 上限(供重启重建去重集合)
const STEWARD_TICK_MAX_EVENTS = 200;       // 单轮入箱上限(防某次大补账把箱子灌爆)
const STEWARD_CARRY_MAX_EVENTS = 5000;     // 116-3 P0-3:跨轮结转队列硬顶(超出才真的丢,并落一条日志)

// ── 轮询成本常量 ────────────────────────────────────────────────────────────
const STEWARD_ACTIVE_WINDOW_MS = 24 * 60 * 60 * 1000; // 「活跃」= 有待决 / 未终态 / 24 小时内有变更
const STEWARD_RUN_EVENT_PAGE = 200;        // 单个 run 单轮最多读多少条事件(下轮继续)
const STEWARD_FIRST_SIGHT_MAX_REVISION = 200; // 首见会话:revision 不超过它才全读,否则只建基线
const STEWARD_FIRST_SIGHT_MAX_EVENT_SEQ = 500; // 首见 run:同上
const STEWARD_FIRST_SIGHT_MAX_TURNS = 50;  // 116-4 首见会话:回合数不超过它才补一条,否则只建基线

// ── 容量常量(游标不得无限增长) ───────────────────────────────────────────────
// 这三个上限管的是【落盘】的游标(cursor-v1.json 的体积与重启后读回的条数),不管进程内存里的游标。
// 修前 stewardSaveCursor 把它们同样用在内存游标上:第 501 个之后的会话每一拍都被裁掉,于是下一拍又算
// 「首见」—— 整份会话头 readFile + JSON.parse、开 .changes.ndjson、readdir agent-runs 全走一遍
// (2000 会话实测每拍约 700ms CPU、38k 次系统调用/分钟)。内存游标另有一档宽得多的上限,只防无界增长。
const STEWARD_CURSOR_MAX_SESSIONS = 500;
const STEWARD_CURSOR_MAX_RUNS = 500;
const STEWARD_CURSOR_MAX_PENDING = 2000;
const STEWARD_CURSOR_MEM_MAX_SESSIONS = 20000;   // 内存游标的会话条目上限(missionChanges / sessionTurns / budgetSeen 共用)
const STEWARD_CURSOR_MEM_MAX_RUNS = 20000;       // 内存游标的 run 条目上限

// ── 读取常量 ────────────────────────────────────────────────────────────────
const STEWARD_INBOX_LIMIT_DEFAULT = 50;
const STEWARD_INBOX_LIMIT_MAX = 200;       // §11.3:limit 夹 [1,200]
const STEWARD_INBOX_FULL_READ_BYTES = 8 * 1024 * 1024; // 超过它只读尾窗(首个半行丢弃)
const STEWARD_INBOX_TAIL_BYTES = 1024 * 1024;
const STEWARD_DEDUPE_TAIL_ROWS = 2000;     // 启动时从 inbox 尾部重建去重集合的行数上限
const STEWARD_SEEN_MAX_KEYS = 20000;       // 去重集合内存硬顶,超了就按同一口径从尾部重建
const STEWARD_INBOX_RETENTION_MS = 30 * 24 * 60 * 60 * 1000;
const STEWARD_INBOX_HISTORY_MAX = 5000;
const STEWARD_INBOX_MAINTENANCE_MS = 60 * 60 * 1000;

// ────────────────────────────────────────────────────────────────────────────
// 源事件 → 五类白名单的【唯一】映射表。
//
// 纪律(dev-harness/steward-events.static.e2e.js 机械对账):三个源在源码里写入端出现过的【每一个】
// type 字面量都必须在本表里登记 —— 登记为 null 也算登记。加了新事件却不登记 = 门红。
// 值的取值:五类之一('needs_you'|'failed'|'done'|'stalled'|'budget')、null(明确丢弃)、
// 或 '@<resolver>'(同一 type 的语义由 payload 决定,见下方三个 stewardResolve* 纯函数)。
// ────────────────────────────────────────────────────────────────────────────
const STEWARD_SOURCE_EVENT_MAP = Object.freeze({
  // ① Mission Change Ledger(02-session-store.js 的 MISSION_CHANGE_TYPES,9 种)
  missionChange: Object.freeze({
    mission_started: null,        // 新建任务账本,不是五类中任一(管家从总览就知道有这条线程)
    progress: null,               // 每回合一条的常规推进 = 心跳,按 §11.3「心跳丢弃」
    failure: 'failed',            // 回合失败(errorClass 在 detail 里)
    budget: null,                 // ← 用量入账(00-boot appendUsageLedger 的每回合 turn 行),是心跳不是触顶;
                                  //   真正的「预算触顶」由投影的 card.mission.budgetExhausted 承载(见 projection)
    intervention_pending: null,   // ← needs_you 统一由投影产出(去重键=interventionId),此处再产一次会双份
    intervention_resolved: null,  // 待决已解决 = 不再需要你,不入箱(投影侧 pendingIds 会自然移除)
    result: '@missionResult',     // 结果章:complete → done;stopped 带错误 → failed;stopped 无错误 → done
    rewind: null,                 // 回退检查点是用户自己的动作
    run_deleted: null,            // 删运行记录是用户自己的动作
    // 116-2b 新增(补 116b 登记的缺口):普通回合的两类信号,由 02 的写入端落账(带频控)。
    stalled: 'stalled',           // 主回合死循环纠偏等"还在跑但没往前走"(同会话 5 分钟一条)
    budget_tripped: 'budget',     // 回合 token 预算保护触顶(每回合最多一条;与心跳 'budget' 分开)
    // 116g:线程加入/移出事项、事项合并/拆分。它是【归属变更】,不是五类信号中的任何一个 ——
    // 用户自己(或管家替他)刚做完这个动作,不需要再被"通知"一次。登记为 null = 显式丢弃。
    mission_membership: null,
  }),
  // ② agent run 事件日志(全 src 扫 appendAgentRunEvent 的 type 字面量,22 种)
  agentRun: Object.freeze({
    run_created: null,            // 班组起跑
    run_end: '@runEnd',           // succeeded/stopped → done;failed/partial → failed
    run_paused: null,             // reason: 'user'(用户自己按的)/'persistence_degraded'(与下面的
                                  //   persistence_degraded 同一事实,只登记一次,避免双份)
    run_resumed: null,
    run_resume_requested: null,
    run_resume_deferred: 'stalled',   // 重启后按 resumeTier 不敢自动续 → 停在半路等你
    run_auto_resume: null,
    run_interrupted: 'stalled',       // 进程重启把 run 打断,停在半路
    run_stop_requested: null,
    run_pool: null,               // 任务池提案 → needs_you 由投影的 pool Intervention 统一产出
    run_replan: null,             // 重规划提案 → replan 不在四类待决白名单(§3.1),本波不入箱
    node_start: null,
    node_progress: null,          // 节点里程碑,高频进度
    node_wait: null,
    node_settled: '@nodeSettled', // status failed/rejected → failed;其余(succeeded/skipped/…)丢弃
    node_requeued: null,          // 与 node_settled 同一行三元表达式的另一支
    node_wrapup_requested: null,
    node_wrapup_forced: null,
    node_idle_aborted: 'stalled',      // 节点空闲超时被中止 = 停滞
    node_no_progress_aborted: 'stalled', // 语义死循环被中止 = 停滞
    persistence_degraded: 'failed',    // 快照连续写失败 = 硬故障
    persistence_recovered: null,
    // 116-2b 新增(补 116b 登记的缺口):班组内的两类信号,由 09 的节点事件壳落账(频控在 08 写入端)。
    run_stalled: 'stalled',            // subagent_no_progress / loop_recovery(同 run 5 分钟一条)
    run_budget_tripped: 'budget',      // 节点工具迭代预算耗尽(按节点天然去重)
  }),
  // ③ 待决投影里的 Intervention 类型(全 src 扫 registerIntervention 的 type 字面量,5 种)
  intervention: Object.freeze({
    permission: 'needs_you',
    question: 'needs_you',
    plan: 'needs_you',
    pool: 'needs_you',
    replan: null,                 // §3.1 四类待决只有 permission/question/plan/pool;replan 归 116-2
  }),
  // ④ 投影派生(没有对应的源事件 type,由 mission card 的持久标记推出)
  projection: Object.freeze({
    budget_exhausted: 'budget',   // m.budgetExhaustedAt 是一次性持久标记 → 每个事项只入箱一次
  }),
  // ④' 第四源 sessionTurns(116-4,27 号文 §11.7)。它没有「源码写入端的 type 字面量」可对账
  //    —— 事实来自会话头本身(turnSeq 前进 + 无活回合 = 这条线程的一个回合结束了),故与 projection
  //    一样【不】参与 116b 静态锁的三条双向等集判定,只在这里登记一条,让「新信号必须有人登记」这条
  //    纪律不被沉默绕过。语义由 payload(会话头上的 stewardLastTurn)决定,见 @sessionTurn 解析器。
  sessionTurn: Object.freeze({
    turn_settled: '@sessionTurn',
  }),
  // ④'' 第五源 threadAdopted(121-K3,34 号文 §4.4「交接」)。与上面两组同处境:没有「源码写入端的
  //    type 字面量」可对账 —— 事实来自用户在界面上按下的那枚「交给管家盯」(PATCH /api/sessions/:id
  //    写 stewardWatch:true,02 落盘后派一条 RUYI_EVENTS 的 thread.adopted{by:'user'})。本文件订阅
  //    那条总线事件、排进下一拍(见 stewardQueueThreadAdopted),故【不】参与 116b 静态锁的三条双向
  //    等集判定,只在这里登记一条,让「新信号必须有人登记一次」这条纪律不被沉默绕过。
  //    为什么不是 needs_you:用户把活交给管家【不是】一件等着用户拿主意的事,恰恰相反。
  //    为什么不复用 done:它也不是收工。第六类 adopted 是它自己,见 06i 的 STEWARD_EVENT_KINDS。
  threadAdopted: Object.freeze({
    thread_adopted: 'adopted',
  }),
  // ⑤ 只走 SSE、【故意】不落任何持久日志的进度信号(116-2b 登记)。收件箱只读三条带 seq 的持久
  //    日志,故这里的东西不可能入箱 —— 登记为 null 是为了让"新信号必须有人登记一次"这条纪律不被
  //    沉默绕过:下一个人加进度事件时,至少要来这张表里写一行"它是进度,不是信号"。
  //    这一组【不参与】116b 静态锁的三条双向等集判定(它扫的是三个持久写入端,这里没有写入端)。
  sseOnly: Object.freeze({
    adaptive_tool_budget: null,   // 子代理工具迭代预算自适应扩容 = 进度(还在往前走),不是触顶
  }),
});

// 只在这四个源事件里出现、但语义由 payload 决定的三个纯函数解析器(表里以 '@name' 指向)。
function stewardResolveMissionResultKind(detail) {
  const d = (detail && typeof detail === 'object') ? detail : {};
  const status = String(d.status || '');
  if (status === 'complete') return 'done';
  if (status === 'stopped') {
    // 「结果章 stopped 且带错误」→ failed;用户主动收工(无错误)→ done(终态,报一次)。
    if (d.errorClass || d.error || Number(d.failed) > 0) return 'failed';
    return 'done';
  }
  return null;
}
function stewardResolveRunEndKind(data) {
  const status = String((data && data.status) || '');
  if (status === 'succeeded' || status === 'stopped') return 'done';
  if (status === 'failed' || status === 'partial') return 'failed';
  return null;
}
function stewardResolveNodeSettledKind(data) {
  const status = String((data && data.status) || '');
  return (status === 'failed' || status === 'rejected') ? 'failed' : null;
}
// 116-4:会话头上的 stewardLastTurn(13g 在回合 settle 之后落的账)-> done | failed。
// 账缺席一律 done:「跑完了」这件事本身是真的(turnSeq 真的前进了),成败让管家自己去读线程 ——
// 绝不拿会话头 summary 里那句人话去猜(实测那是渲染,不是信号)。
// 用户主动停(aborted)按 done:与 @runEnd 的 'stopped' -> done 同口径,自己按的停不是故障。
function stewardResolveSessionTurnKind(last) {
  if (!last || typeof last !== 'object') return 'done';
  return (last.ok === false && last.aborted !== true) ? 'failed' : 'done';
}
const STEWARD_KIND_RESOLVERS = Object.freeze({
  '@sessionTurn': stewardResolveSessionTurnKind,
  '@missionResult': stewardResolveMissionResultKind,
  '@runEnd': stewardResolveRunEndKind,
  '@nodeSettled': stewardResolveNodeSettledKind,
});

// 表查询:返回五类之一或 null。未登记的 type 一律 null(丢弃)并由静态门在下一次改动时报红。
function stewardKindFor(source, type, payload) {
  const table = STEWARD_SOURCE_EVENT_MAP[source];
  if (!table || !Object.prototype.hasOwnProperty.call(table, String(type))) return null;
  const value = table[String(type)];
  if (value == null) return null;
  if (typeof value === 'string' && value.startsWith('@')) {
    const resolver = STEWARD_KIND_RESOLVERS[value];
    return resolver ? resolver(payload) : null;
  }
  return STEWARD_EVENT_KINDS.includes(value) ? value : null;
}

// ────────────────────────────────────────────────────────────────────────────
// 纯函数区(不碰磁盘、不读配置):归一化 / 去重键 / 合并。单测 unit/steward-inbox-core.test.js 直测。
// 入参一律是普通对象,不依赖任何源模块的运行时状态。
// ────────────────────────────────────────────────────────────────────────────
function stewardClipSummary(value) {
  const text = stewardSanitizeText(value).trim();
  return text.length > STEWARD_SUMMARY_CHARS ? text.slice(0, STEWARD_SUMMARY_CHARS) + '…' : text;
}

function stewardIsoAt(value) {
  const text = String(value == null ? '' : value);
  return Number.isFinite(Date.parse(text)) ? text : new Date(0).toISOString();
}

// 去重键 = sessionId + kind + runId + seq(§11.3「去重键 sessionId+kind+seq」;needs_you 的 seq
// 位就是 interventionId,budget 的 seq 位是 'exhausted@<用尽时刻>' —— 二者都是各自源的稳定游标)。
function stewardEventDedupeKey(evt) {
  const e = (evt && typeof evt === 'object') ? evt : {};
  return [String(e.sessionId || ''), String(e.kind || ''), String(e.runId || ''), String(e.seq)].join('\u0000');
}

// 125-P1(42 号文 §1 ②):下面三处 failed 摘要不再把 errorClass 拼进括号。机器词仍然原样落在
// payload.errorClass 上(去重、取证、前端都要它),但【给模型看的那一行】由 13p 的
// stewardEventLine 统一补上人话与下一步(取话口是 06i 的 stewardFailureExplain,查的是 06
// 那张既有 ERROR_CLASSES)。修前模型拿到的是 `会话第 3 回合失败(idle_timeout)` 这串原始
// 机器词,「这是什么意思、该怎么办」只能它自己编 —— 而工作台自己就有写好的答案。
// ① Mission Change Ledger 的一条 change record → 归一化事件 | null
function stewardNormalizeMissionChange(record) {
  const r = (record && typeof record === 'object') ? record : {};
  const seq = Number(r.seq);
  if (!Number.isSafeInteger(seq) || seq < 1) return null;
  const detail = (r.detail && typeof r.detail === 'object') ? r.detail : {};
  const cursor = (r.cursor && typeof r.cursor === 'object') ? r.cursor : {};
  const kind = stewardKindFor('missionChange', r.type, detail);
  if (!kind) return null;
  const payload = { source: 'mission_change', changeType: String(r.type || '') };
  if (detail.errorClass) payload.errorClass = stewardClipSummary(detail.errorClass);
  if (detail.status) payload.resultStatus = stewardClipSummary(detail.status);
  if (cursor.turnSeq != null) payload.turnSeq = Number(cursor.turnSeq) || 0;
  if (cursor.engine) payload.engine = stewardClipSummary(cursor.engine);
  // 116-2b:两个新 type 的摘要只取 detail 里的计数与原因(reason/tool/count/spent/budget),
  // 与 failure 同纪律 —— 永不带工具输出正文。
  if (detail.reason) payload.reason = stewardClipSummary(detail.reason);
  if (detail.tool) payload.tool = stewardClipSummary(detail.tool);
  if (detail.count != null) payload.count = Number(detail.count) || 0;
  if (detail.spent != null) payload.spent = Number(detail.spent) || 0;
  if (detail.budget != null) payload.budget = Number(detail.budget) || 0;
  payload.summary = stewardClipSummary(
    r.type === 'stalled'
      ? `会话停住了(${payload.reason || '无进展'}${payload.tool ? ' · ' + payload.tool : ''}${payload.count ? ' · 第 ' + payload.count + ' 次' : ''})`
      : r.type === 'budget_tripped'
        ? `回合 token 预算触顶(已用 ${payload.spent}/${payload.budget})`
        : kind === 'failed'
          ? `回合失败`
          : `任务结果章:${payload.resultStatus || ''}`);
  return {
    kind,
    sessionId: String(r.sessionId || ''),
    missionId: String(r.missionId || r.sessionId || ''),
    runId: '',
    seq,
    at: stewardIsoAt(r.occurredAt),
    payload,
  };
}

// ② agent run 事件 → 归一化事件 | null
function stewardNormalizeRunEvent(sessionId, missionId, runId, evt) {
  const e = (evt && typeof evt === 'object') ? evt : {};
  const seq = Number(e.seq);
  if (!Number.isSafeInteger(seq) || seq < 1) return null;
  const data = (e.data && typeof e.data === 'object') ? e.data : {};
  const kind = stewardKindFor('agentRun', e.type, data);
  if (!kind) return null;
  const payload = { source: 'agent_run', eventType: String(e.type || '') };
  if (e.nodeId) payload.nodeId = stewardClipSummary(e.nodeId);
  if (data.status) payload.runStatus = stewardClipSummary(data.status);
  if (data.errorClass) payload.errorClass = stewardClipSummary(data.errorClass);
  if (data.reason) payload.reason = stewardClipSummary(data.reason);
  // 刻意不带 data.text / data.nodes 等正文:payload 只放摘要与引用 id,永不带工具输出全文。
  // 116-2b:run_stalled / run_budget_tripped 的 data 带 reason/tool/count/limit,补进 payload 摘要。
  if (data.tool) payload.tool = stewardClipSummary(data.tool);
  if (data.count != null) payload.count = Number(data.count) || 0;
  if (data.limit != null) payload.limit = Number(data.limit) || 0;
  payload.summary = stewardClipSummary(
    kind === 'done' ? `班组 ${runId} 收工(${payload.runStatus || ''})`
      : kind === 'failed' ? `班组 ${runId} ${payload.nodeId ? '节点 ' + payload.nodeId + ' ' : ''}失败`
        : kind === 'budget' ? `班组 ${runId} ${payload.nodeId ? '节点 ' + payload.nodeId + ' ' : ''}用完了工具迭代预算(${payload.limit} 轮)`
          : `班组 ${runId} ${payload.nodeId ? '节点 ' + payload.nodeId + ' ' : ''}停滞(${payload.eventType}${payload.reason ? ' · ' + payload.reason : ''}${payload.tool ? ' · ' + payload.tool : ''})`);
  return {
    kind,
    sessionId: String(sessionId || ''),
    missionId: String(missionId || sessionId || ''),
    runId: String(runId || ''),
    seq,
    at: stewardIsoAt(e.ts),
    payload,
  };
}

// ③ 投影里一条 pending Intervention → 归一化 needs_you 事件 | null
function stewardNormalizePendingIntervention(sessionId, missionId, iv) {
  const v = (iv && typeof iv === 'object') ? iv : {};
  if (String(v.status || '') !== 'pending') return null;
  const id = String(v.id || '');
  if (!id) return null;
  const type = String(v.type || '');
  const kind = stewardKindFor('intervention', type, v);
  if (!kind) return null;
  const payload = { source: 'projection', interventionId: id, interventionType: type };
  if (v.toolName) payload.toolName = stewardClipSummary(v.toolName);
  if (v.tier) payload.tier = stewardClipSummary(v.tier);
  if (v.runId) payload.runId = stewardClipSummary(v.runId);
  // 一句话摘要:只取各类待决自己的摘要字段(问题原文/计划摘要/池任务),永不带 iv.input(可能含文件正文)。
  const summary = type === 'permission' ? `请求执行工具 ${payload.toolName || '(未知)'}${payload.tier ? ' · ' + payload.tier : ''}`
    : type === 'question' ? String(v.questionSummary || '在问你一个问题')
      : type === 'plan' ? String(v.planSummary || '提交了一份计划等你批')
        : String(v.task || '提了一个新任务等你批');
  payload.summary = stewardClipSummary(summary);
  // 121-K6a(§4.3 安静卡「needs_you 印问句前 22 字」):四类待决都给一句「问句」——前端只管截前 22 字,
  // 这里不重复截,给的是与 summary 同源的完整一句(权限/问题/计划/新任务四支择一)。
  payload.ask = payload.summary;
  // 只在【单问、有选项】这一种最常见形状下再加「候选答案按钮」要的两个 id 与选项表 —— 多问(≤3)
  // 或纯文本题不带,安静卡那时只画「去看」。answerQuestionId 是子问题自己的 id(与外层 interventionId
  // 不同,POST /api/chat/answer 的 answers[].questionId 要它)。
  if (type === 'question' && Array.isArray(v.questions) && v.questions.length === 1) {
    const q0 = v.questions[0] && typeof v.questions[0] === 'object' ? v.questions[0] : null;
    const opts = q0 && Array.isArray(q0.options) ? q0.options : [];
    if (q0 && opts.length) {
      payload.ask = stewardClipSummary(String(q0.question || v.questionSummary || ''));
      payload.answerQuestionId = String(q0.id || '');
      payload.options = opts.slice(0, 6).map(o => ({
        id: String((o && o.id) || ''),
        label: stewardClipSummary(String((o && o.label) || '')),
      })).filter(o => o.id && o.label);
    }
  }
  return {
    kind,
    sessionId: String(sessionId || ''),
    missionId: String(missionId || sessionId || ''),
    runId: String(v.runId || ''),
    seq: id, // needs_you 的去重游标就是 interventionId(同一待决只入箱一次)
    at: stewardIsoAt(v.requestedAt),
    payload,
  };
}

// ④ 投影派生:mission card 的预算耗尽标记 → budget 事件 | null(每个事项一次性)
// ⑤ 用户交接(121-K3,§4.4)-> 归一化事件 | null。来源是总线事件 thread.adopted{by:'user'},
// 不是磁盘日志 —— 所以它没有 seq 可用,拿【交接时刻】当去重位:同一条线程反复交出去/收回来
// 是合法的(用户改主意),两次交接必须是两行,而同一次交接重放多少遍都只有一行。
function stewardNormalizeThreadAdopted(record) {
  const r = (record && typeof record === 'object') ? record : {};
  const sessionId = String(r.sessionId || '');
  if (!sessionId) return null;
  const kind = stewardKindFor('threadAdopted', 'thread_adopted', r);
  if (!kind) return null;
  const at = stewardIsoAt(r.at);
  const title = stewardSanitizeText(r.title || '').slice(0, 120);
  const note = stewardSanitizeText(r.note || '').slice(0, 200);
  // 121-K6a:委托一句缝进人话里——管家下一回合读收件箱摘要时,「盯着」与「盯什么」在同一句里,
  // 不必再去查第二个字段。没带就是老行为(一字不变)。
  const summary = title
    ? `用户把线程「${title}」交给你盯${note ? `,说:「${note}」` : ''}`
    : `用户把一条线程交给你盯${note ? `,说:「${note}」` : ''}`;
  return {
    kind,
    sessionId,
    missionId: String(r.missionId || sessionId),
    runId: '',
    seq: at,
    at,
    payload: {
      source: 'threadAdopted',
      by: 'user',
      title,
      ...(note ? { note } : {}),
      summary: stewardClipSummary(summary),
    },
  };
}

function stewardNormalizeBudgetExhausted(sessionId, missionId, card) {
  const c = (card && typeof card === 'object') ? card : null;
  const mission = c && c.mission && typeof c.mission === 'object' ? c.mission : null;
  if (!mission || mission.budgetExhausted !== true) return null;
  const kind = stewardKindFor('projection', 'budget_exhausted', mission);
  if (!kind) return null;
  const budget = (mission.budget && typeof mission.budget === 'object') ? mission.budget : {};
  const spent = (mission.spent && typeof mission.spent === 'object') ? mission.spent : {};
  return {
    kind,
    sessionId: String(sessionId || ''),
    missionId: String(missionId || sessionId || ''),
    runId: '',
    seq: mission.budgetExhaustedAt ? 'exhausted@' + String(mission.budgetExhaustedAt) : 'exhausted',   // 带用尽时刻:任务重启后再次用尽是新的一行
    at: stewardIsoAt(mission.updatedAt || c.updatedAt),
    payload: {
      source: 'projection',
      autoTurns: Number(spent.autoTurns) || 0,
      maxAutoTurns: Number(budget.maxAutoTurns) || 0,
      tokens: Number(spent.tokens) || 0,
      maxTokens: Number(budget.maxTokens) || 0,
      summary: stewardClipSummary(`事项预算已用尽(自动回合 ${Number(spent.autoTurns) || 0}/${Number(budget.maxAutoTurns) || 0})`),
    },
  };
}

// ⑤ 116-4 第四源:一条会话的「某个回合结束了」-> done | failed 事件 | null。
// seq 位就是该会话的 turnSeq(它自己的单调游标),故去重键 = sid|kind|''|turnSeq —— 同一回合只报一次。
// 【成对改】下面这两句摘要会被前端【逐字】解析(public/js/steward-conversation.js 的
// STEWARD_INBOX_TURN_RE 靠它抠出回合号去挑那一回合的原文):动这里的措辞必须同刀改那条正则,
// 只改一边是静默解析失败(前端拿不到回合号只会悄悄退到「最后一条助手话」,不报错)。
function stewardNormalizeSessionTurn(sessionId, missionId, head, turnSeq) {
  const seq = Math.max(0, Number(turnSeq) || 0);
  if (seq < 1) return null;
  const h = (head && typeof head === 'object') ? head : {};
  // hunt2-steward ④:成败账只在盖得住【这一回合】时才算数(06i stewardCoveringLastTurn)。账是上一个
  // 管家回合留下的(这一回合是用户在 2.0 里自己聊的,不写账)→ 当作账缺席,按 done 报。
  const last = stewardCoveringLastTurn(h.stewardLastTurn, seq);
  const kind = stewardKindFor('sessionTurn', 'turn_settled', last);
  if (!kind) return null;
  const quick = !!(h.stewardQuick && typeof h.stewardQuick === 'object');
  const payload = { source: 'session_turn', turnSeq: seq };
  if (h.launchedBy) payload.launchedBy = stewardClipSummary(h.launchedBy);
  if (quick) payload.quick = true;                       // 13g 的 enrichInboxRows 会给它补 answer
  if (last && last.errorClass) payload.errorClass = stewardClipSummary(last.errorClass);
  if (last && last.aborted === true) payload.aborted = true;
  payload.summary = stewardClipSummary(kind === 'failed'
    ? `会话第 ${seq} 回合失败`
    : `会话第 ${seq} 回合跑完了${payload.aborted ? '(被停止)' : ''}`);
  return {
    kind,
    sessionId: String(sessionId || ''),
    missionId: String(missionId || sessionId || ''),
    runId: '',
    seq,
    at: stewardIsoAt((last && last.at) || h.updatedAt),
    payload,
  };
}

// 合并(纯函数):同 sessionId + 同 kind + 同 runId、且距该组【首条】不超过 windowMs 的事件并成一条。
// 组内:count 累加、at 取最早、seq 取最新;所有被并掉的源 seq 回填进 payload.mergedSeqs
// (上限 STEWARD_MERGED_SEQS_MAX),供重启时从 inbox 尾部重建完整去重集合。
//
// 116-3 P1-7(对抗审查):修前的分组键【不含 runId】,并且命中分组后 `group.payload = {...evt.payload}`
// 把先到的那条整份覆盖掉 —— 同一会话 5 秒内两个不同 run 的 failed(run_1/nodeX/timeout 与
// run_2/nodeY/oom)合并后只剩后者,run_1 的 nodeId/errorClass/summary 全部消失,管家永远看不到
// 「节点 X 因超时失败」。5 秒窗口的本意是「心跳/重复事件收敛」,不是「后到的吞掉先到的不同事件」。
// 两处修法:① 分组键补上 runId(与去重键同粒度);② payload 以【首条】为准,只把 nodeId /
// errorClass 累加成 nodeIds / errorClasses 列表(同 run 内多个节点先后失败仍能看全)。
// 键 -> 列表键。显式写死而不是 key + 's':errorClass 本身以 s 结尾,拼出来会是 errorClasss。
const STEWARD_MERGE_ACCUMULATE_KEYS = Object.freeze({ nodeId: 'nodeIds', errorClass: 'errorClasses' });
function stewardMergeAccumulate(base, incoming) {
  const prev = (base && typeof base === 'object') ? base : {};
  const from = (incoming && typeof incoming === 'object') ? incoming : {};
  // 其余字段仍取【最新】(既有口径,116b 的单测把它钉着);只有下面这两个键改成累加列表 ——
  // 它们是「到底是哪一步、因为什么挂的」这条信息的载体,被后到的事件盖掉就等于真的丢了信息。
  const merged = { ...from };
  for (const [key, listKey] of Object.entries(STEWARD_MERGE_ACCUMULATE_KEYS)) {
    const list = Array.isArray(prev[listKey])
      ? prev[listKey].slice()
      : (prev[key] != null && prev[key] !== '' ? [prev[key]] : []);
    const value = from[key];
    if (value != null && value !== '' && !list.includes(value)) list.push(value);
    if (list.length) merged[listKey] = list.slice(0, STEWARD_MERGED_SEQS_MAX);
  }
  return merged;
}
function stewardMergeInboxEvents(events, windowMs) {
  const window = Number.isFinite(Number(windowMs)) ? Number(windowMs) : STEWARD_MERGE_WINDOW_MS;
  const rows = (Array.isArray(events) ? events : []).filter(e => e && typeof e === 'object' && STEWARD_EVENT_KINDS.includes(e.kind));
  rows.sort((a, b) => String(a.at).localeCompare(String(b.at))
    || String(a.sessionId).localeCompare(String(b.sessionId))
    || String(a.kind).localeCompare(String(b.kind))
    || String(a.seq).localeCompare(String(b.seq)));
  const open = new Map(); // sessionId\0kind\0runId -> group(116-3 P1-7:分组键补上 runId)
  const out = [];
  for (const evt of rows) {
    const groupKey = String(evt.sessionId || '') + '\u0000' + String(evt.kind || '') + '\u0000' + String(evt.runId || '');
    const at = Date.parse(evt.at);
    const atMs = Number.isFinite(at) ? at : 0;
    const group = open.get(groupKey);
    if (group && atMs - group.__firstMs <= window) {
      group.count += 1;
      group.seq = evt.seq;
      group.payload = stewardMergeAccumulate(group.payload, evt.payload);   // 116-3 P1-7:累加,不整份覆盖
      if (group.__seqs.length < STEWARD_MERGED_SEQS_MAX) group.__seqs.push(evt.seq);
      continue;
    }
    const created = {
      kind: evt.kind,
      sessionId: String(evt.sessionId || ''),
      missionId: String(evt.missionId || evt.sessionId || ''),
      runId: String(evt.runId || ''),
      seq: evt.seq,
      at: evt.at,
      payload: { ...evt.payload },
      count: 1,
      __firstMs: atMs,
      __seqs: [evt.seq],
    };
    open.set(groupKey, created);
    out.push(created);
  }
  return out.map(group => {
    const row = { kind: group.kind, sessionId: group.sessionId, missionId: group.missionId, runId: group.runId, seq: group.seq, at: group.at, payload: group.payload, count: group.count };
    if (group.count > 1) row.payload = { ...row.payload, mergedSeqs: group.__seqs.slice(0, STEWARD_MERGED_SEQS_MAX) };
    return row;
  });
}

// 从一条已落盘的 inbox 行还原它覆盖的【全部】去重键(含被合并掉的源 seq)。
function stewardInboxRowDedupeKeys(row) {
  if (!row || typeof row !== 'object') return [];
  const base = { sessionId: row.sessionId, kind: row.kind, runId: row.runId };
  const seqs = [row.seq];
  const merged = row.payload && Array.isArray(row.payload.mergedSeqs) ? row.payload.mergedSeqs : [];
  for (const seq of merged.slice(0, STEWARD_MERGED_SEQS_MAX)) if (!seqs.includes(seq)) seqs.push(seq);
  return seqs.map(seq => stewardEventDedupeKey({ ...base, seq }));
}

// ────────────────────────────────────────────────────────────────────────────
// 落盘层。写原语与 session-changes NDJSON 同款:先 repairMissionChangeTornTail(尾部半行截干净),
// 再 fsp.appendFile 整行;全部经一条 per-process 串行链(不交错)。游标走 atomicWriteJson。
// ────────────────────────────────────────────────────────────────────────────
function stewardDir() { return path.join(paths.data, STEWARD_DIR_NAME); }
function stewardInboxPath() { return path.join(stewardDir(), STEWARD_INBOX_FILE); }
function stewardCursorPath() { return path.join(stewardDir(), STEWARD_CURSOR_FILE); }

const stewardRuntime = {
  timer: null,
  running: false,
  ticking: false,
  wakePending: false,
  generation: 0,        // stopStewardInbox 自增;在途 tick 发现代际变了就尽快退出
  loaded: false,
  cold: true,           // 本次装载时没有可用游标 = 冷启动(只建基线,不把历史灌进箱子)
  inboxSeq: 0,
  pollMs: 60000,
  lastTickAt: '',
  lastInboxAt: '',      // 116-4:最后一次【真的写进箱子】的时刻(lastTickAt 只说明轮询活着)
  lastMaintenanceAt: 0,
  sourcesSeen: { sessionTurns: 0 }, // 116-4:第四源本进程入箱条数,给 /api/steward/state 的诚实字段
  lastError: '',
  seen: new Set(),      // 去重集合(启动时从 inbox 尾部重建,上限 STEWARD_DEDUPE_TAIL_ROWS 行)
  // 116-3 P1-9:budget 类事件此前【没有】持久化去重游标,唯一保护是内存 seen 集合,而它无论启动重建
  // 还是运行时收缩都只回看 inbox 尾部 2000 行 —— 繁忙一天之后那条记录滑出窗口,而 card 上的
  // budgetExhausted 是持久标记,下一轮就会把同一件事重复写进箱子。budgetSeen 与 pendingIds 同款落盘。
  // 116-4:第四源 sessionTurns 的游标 —— sid -> { turnSeq, stamp }。stamp 是投影免费给的
  // 会话文件指纹(size:mtime 的哈希);它没变就连会话头都不用读,这是第四源不把轮询成本推高的关键。
  cursor: { missionChanges: {}, agentRuns: {}, pendingIds: new Set(), budgetSeen: new Set(), sessionTurns: {} },
  // 上一次【成功落盘】的游标内容指纹(不含 updatedAt)。stewardSaveCursor 每拍先算一遍当前指纹,
  // 与它相同就不写盘 —— 15 秒一拍的空转轮询不该每拍 temp+rename 重写一份 65KB 的游标。
  // 空串 = 本进程还没成功写过(装载/重置后的第一拍必写:冷启动基线、损坏游标的重建都靠这一拍)。
  cursorSig: '',
  // 116-3 P0-3:本轮因单轮上限没能写进箱子的【原始】事件。游标在 stewardCollectEvents 里已经越过
  // 它们(三条源日志的游标是「这一轮看到的最新版本号」,不管后面写没写进箱),所以不留在这里就是
  // 永久静默丢失 —— 而超出上限的恰恰是最新的那批 needs_you / failed。留到下一轮开头再入箱。
  carry: [],
  // 121-K3(§4.4「交接」):等着进下一拍的交接事件。来源是总线(02 落盘 stewardWatch:true 之后派的
  // thread.adopted{by:'user'}),不是任何一本磁盘日志 —— 所以它不走「游标 + 增量读」那一套,而是
  // 在这里排队,由下一拍 stewardCollectEvents 开头一次性取走。硬顶见 STEWARD_ADOPTED_QUEUE_MAX:
  // 管家关着时没人来取,队列不能无限长(溢出丢【最早】的 —— 最近那次交接才是用户还记得的那次)。
  adopted: [],
  adoptedRecent: new Map(),   // 135:重复交接去重窗口(sid+委托 -> 时刻),只在内存
  wakeTimers: [],             // 2026-10:待决一产生就提前补拍的定时器(见 stewardScheduleWake)
};
const STEWARD_ADOPTED_QUEUE_MAX = 50;
const STEWARD_ADOPTED_DEDUPE_MS = 10 * 60 * 1000;   // 135:同一线程同一句委托在 10 分钟内重复交接只算一次
let stewardAppendChain = Promise.resolve();

// 121-K3:订阅总线。装在模块加载期,进程生命周期内不卸(同 13r 的纪律)。它【只排队,不落盘】——
// 收件箱的写面只有 stewardTickOnce 一处,旁路事件不许绕过去重、合并、在场门三道工序。
RUYI_EVENTS.subscribe((name, payload) => {
  if (name !== 'thread.adopted') return;
  const data = (payload && typeof payload === 'object') ? payload : {};
  if (String(data.by || '') !== 'user') return;   // missionAttachThread 派的那一路是【归并到事项】,不是交接
  stewardQueueThreadAdopted(data);
});
// Lifecycle events wake the single inbox writer. A second pass covers events emitted
// before journal persistence. Coalesce without postponing existing deadlines: a busy
// event stream must never starve the first pass. Token/delta events do not wake it.
const STEWARD_WAKE_DELAYS_MS = Object.freeze([400, 2500]);
const STEWARD_WAKE_EVENTS = new Set([
  'thread.needs_you', 'thread.state', 'thread.done', 'thread.removed',
  'thread.created', 'background.completed',
]);
RUYI_EVENTS.subscribe((name, payload) => {
  if (!STEWARD_WAKE_EVENTS.has(name)) return;
  const sid = safeSessionId(payload && payload.sessionId);
  if (!sid || sid === STEWARD_SESSION_ID) return;
  stewardScheduleWake();
});
function stewardConsistencyMs(value) {
  const n = Number(value);
  return Number.isFinite(n) ? Math.min(120000, Math.max(60000, Math.round(n))) : 60000;
}
function stewardClearWake() {
  for (const timer of (Array.isArray(stewardRuntime.wakeTimers) ? stewardRuntime.wakeTimers : [])) clearTimeout(timer);
  stewardRuntime.wakeTimers = [];
}
function stewardScheduleWake() {
  if (!stewardRuntime.running) return;   // 管家关着 / 停机:没人取,不补拍
  if (stewardRuntime.ticking) stewardRuntime.wakePending = true;
  if (stewardRuntime.wakeTimers.length) return;
  const generation = stewardRuntime.generation;
  for (const delay of STEWARD_WAKE_DELAYS_MS) {
    const timer = setTimeout(() => {
      stewardRuntime.wakeTimers = stewardRuntime.wakeTimers.filter(item => item !== timer);
      if (!stewardRuntime.running || stewardRuntime.generation !== generation) return;
      void stewardRunTick();
    }, delay);
    if (timer && typeof timer.unref === 'function') timer.unref();
    stewardRuntime.wakeTimers.push(timer);
  }
}
function stewardQueueThreadAdopted(data) {
  const sid = safeSessionId(data && data.sessionId);
  if (!sid || sid === STEWARD_SESSION_ID) return;
  const note = String((data && data.note) || '').slice(0, 200);
  // 135(真机取证:收件箱 93/94 两条一模一样的 adopted 各叫醒一回合,管家第二回只能说「同上一条,
  // 不用重复处理」):同一条线程、同一句委托在窗口内再来一次就是重复投递,不再叫醒管家。
  // 委托换了一句话照常入箱 —— 那是用户补了新交代。只在内存里记,重置随运行时一起清。
  if (!(stewardRuntime.adoptedRecent instanceof Map)) stewardRuntime.adoptedRecent = new Map();
  const now = Date.now();
  for (const [key, at] of stewardRuntime.adoptedRecent) {
    if (now - at > STEWARD_ADOPTED_DEDUPE_MS) stewardRuntime.adoptedRecent.delete(key);
  }
  const dedupeKey = sid + '\n' + note;
  if (stewardRuntime.adoptedRecent.has(dedupeKey)) return;
  stewardRuntime.adoptedRecent.set(dedupeKey, now);
  stewardRuntime.adopted.push({
    sessionId: sid,
    missionId: String((data && data.missionId) || sid),
    title: String((data && data.title) || ''),
    // 121-K6a(§4.4「委托一句」):用户交接时顺手带的一句话(02 已经 trim+≤200 字)。这里只再夹一次
    // 防御性上限,不再改内容——它要原样出现在管家下一回合看到的人话里。
    note,
    at: String((data && data.at) || nowIso()),
  });
  while (stewardRuntime.adopted.length > STEWARD_ADOPTED_QUEUE_MAX) stewardRuntime.adopted.shift();
  stewardScheduleWake();
}

// ────────────────────────────────────────────────────────────────────────────
// 在场门(121-K3,34 号文 §4.3「在场信号与打扰纪律」)。
//
// 事实源是 13r 的在场快照(每条 SSE 连接自报的 lens 与 sessionId),经 00-boot 的延迟绑定命名空间
// 取 —— 13i 拼在 13r 之前,直引 13r 的符号是前向边。读不到(钩子未填充 / 事件流关着 / 抛错)一律
// 当「没人在壳里」= 今天的行为:这道门管的是【打扰纪律】,不是权限,fail-open 才对。
//
// 四种情形(§4.3 逐条):
//   ① 用户在工作台、且正坐在这条线程上 -> 事件【不入箱】(索引与徽标照常更新,他自己看得见);
//   ② 用户在工作台、但坐在别的线程     -> needs_you/failed/stalled/budget 照进箱并打 quiet:true
//                                        (前端安静卡读它);done 不进(§4.3 明说「done 只更新左栏」);
//   ③ 用户在管家视角                   -> 今天的行为,一个字不改;
//   ④ 没有任何连接                     -> 累积,今天的行为。
// ②里 stalled/budget 两类设计稿没点名:它们与 needs_you/failed 同属「有事要你知道」,按同一档处理
// (进箱 + quiet),而不是像 done 那样丢掉 —— 丢掉它们等于用户回到管家视角时永远补不上这两类。
// ③ 排在 ② 之前:两个视角同时连着时,管家视角开着就说明收件箱那一面正被人看着,它才是该收东西的那面。
// adopted 不过门:它是用户【刚刚亲手按下】的交接,他要的就是管家应一声,不存在打扰问题。
//
// 2026-10(用户:「如果用户在看提问、权限,管家被立刻唤醒也不要插手」):viewing(13r 头注)【不】在这道门里处理 ——
// 入箱的是事实与通知(安静卡、到访摘要都读它),用户正看着一道提问不该让那张安静卡消失。「管家不插手」落在两处:
// 13q 的回合排空器把被看着的待决扣在回合队列外(不为它起回合),13k stewardSeatedByUser 让代批 / 代答工具拒绝。
// 下面两个小工具给 13q 用(它们读的是本文件同一份在场快照)。
// ────────────────────────────────────────────────────────────────────────────
function stewardViewingSessionIds(presence) {
  const out = new Set();
  for (const row of (Array.isArray(presence) ? presence : [])) {
    for (const sid of (row && Array.isArray(row.viewing) ? row.viewing : [])) if (sid) out.add(String(sid));
  }
  return out;
}
function stewardPendingKeyOf(evt) {
  const iv = evt && evt.payload && evt.payload.interventionId;
  return iv ? String(evt.sessionId || '') + '\u0000' + String(iv) : '';
}
// 这条待决此刻还挂着吗(读本文件游标上那份全局待决集合;13q 放行被扣住的事件前问它)。
function stewardPendingStillOpen(evt) {
  const key = stewardPendingKeyOf(evt);
  return Boolean(key) && stewardRuntime.cursor.pendingIds.has(key);
}
function stewardPresenceRows() {
  try {
    const rows = typeof EventStreamHooks.presenceSnapshot === 'function' ? EventStreamHooks.presenceSnapshot() : [];
    return Array.isArray(rows) ? rows : [];
  } catch { return []; }
}
function stewardApplyPresenceGate(events) {
  const list = Array.isArray(events) ? events : [];
  const presence = stewardPresenceRows();
  if (!presence.length) return list;                       // ④
  const seated = new Set();
  let classicPresent = false, stewardPresent = false;
  for (const row of presence) {
    const lens = String((row && row.lens) || '');
    if (lens === 'steward') { stewardPresent = true; continue; }
    if (lens !== 'classic') continue;
    classicPresent = true;
    const sid = String((row && row.sessionId) || '');
    if (sid) seated.add(sid);
  }
  if (stewardPresent || !classicPresent) {                 // ③ 与「只有别的 lens 连着」
    return list.filter(evt => !seated.has(String((evt && evt.sessionId) || '')) || String((evt && evt.kind) || '') === 'adopted');
  }
  const out = [];
  for (const evt of list) {
    const sid = String((evt && evt.sessionId) || '');
    const kind = String((evt && evt.kind) || '');
    if (kind === 'adopted') { out.push(evt); continue; }
    if (seated.has(sid)) continue;                         // ①
    if (kind === 'done') continue;                         // ②:收工只更新左栏
    out.push({ ...evt, payload: { ...((evt && evt.payload && typeof evt.payload === 'object') ? evt.payload : {}), quiet: true } });
  }
  return out;
}

function stewardResetRuntimeState() {
  stewardRuntime.loaded = false;
  stewardRuntime.cold = true;
  stewardRuntime.inboxSeq = 0;
  stewardRuntime.lastTickAt = '';
  stewardRuntime.lastInboxAt = '';
  stewardRuntime.lastMaintenanceAt = 0;
  stewardRuntime.lastError = '';
  stewardRuntime.seen = new Set();
  stewardRuntime.cursor = { missionChanges: {}, agentRuns: {}, pendingIds: new Set(), budgetSeen: new Set(), sessionTurns: {} };
  stewardRuntime.cursorSig = '';   // 重置 = 磁盘上那份不再可信,下一拍必须重写
  stewardRuntime.carry = [];
  stewardRuntime.adopted = [];   // 121-K3:交接队列随运行时一起重置(它不落盘,重置即清)
  stewardRuntime.adoptedRecent = new Map();   // 135:重复交接的去重窗口,同上
}

// inbox 尾窗读取:小文件整读;大文件只读尾窗并丢弃首个半行(换行是单字节 0x0A,永不落在 UTF-8
// 多字节序列中 —— 与 readAgentRunEvents 的尾窗纪律同源)。文件不存在 = 空(绝不 mkdir)。
async function stewardReadInboxText() {
  const file = stewardInboxPath();
  let size = -1;
  try { size = (await fsp.stat(file)).size; } catch { return { text: '', droppedHead: false }; }
  if (size <= STEWARD_INBOX_FULL_READ_BYTES) {
    try { return { text: await fsp.readFile(file, 'utf8'), droppedHead: false }; } catch { return { text: '', droppedHead: false }; }
  }
  let fh = null;
  try {
    fh = await fsp.open(file, 'r');
    const buf = Buffer.alloc(STEWARD_INBOX_TAIL_BYTES);
    const { bytesRead } = await fh.read(buf, 0, STEWARD_INBOX_TAIL_BYTES, size - STEWARD_INBOX_TAIL_BYTES);
    return { text: buf.toString('utf8', 0, bytesRead), droppedHead: true };
  } catch { return { text: '', droppedHead: false }; }
  finally { if (fh) await fh.close().catch(() => {}); }
}

// 解析 inbox 文本为行对象。坏行/尾部半行一律跳过(append-only 日志的既有纪律)。
function stewardParseInboxText(text, droppedHead) {
  const lines = String(text || '').split('\n');
  const rows = [];
  for (let i = droppedHead ? 1 : 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const row = safeJsonParse(line, null);
    if (!row || typeof row !== 'object') continue;
    if (!Number.isSafeInteger(Number(row.inboxSeq)) || !STEWARD_EVENT_KINDS.includes(row.kind)) continue;
    rows.push(row);
  }
  return rows;
}

async function stewardReadInboxRows() {
  const { text, droppedHead } = await stewardReadInboxText();
  return stewardParseInboxText(text, droppedHead);
}

function stewardInboxPendingState(row, pending) {
  if (!pending) return 'unknown';
  const ids = new Set([row.payload?.interventionId, row.seq, ...(Array.isArray(row.payload?.mergedSeqs) ? row.payload.mergedSeqs : [])]
    .filter(id => typeof id === 'string' && id));
  for (const id of ids) if (pending.has(String(row.sessionId || '') + '\u0000' + id)) return 'pending';
  // 合并行只记录前 20 个源 id;id 不全时不能推断这一整组已经处理完。
  return !ids.size || Number(row.count) > ids.size ? 'unknown' : 'not_pending';
}

// 只整理通知副本,不动会话/待决/审计源。与 append 共用写链,读失败绝不能把原文件覆盖成空。
// 当前待决不受年龄/历史条数限制;最后一行保留作序号水位,重启和增量读取都不会倒退。
function stewardMaintainInbox(now = Date.now()) {
  if (now - stewardRuntime.lastMaintenanceAt < STEWARD_INBOX_MAINTENANCE_MS) return Promise.resolve();
  const pending = new Set(stewardRuntime.cursor.pendingIds);
  const next = stewardAppendChain.catch(() => {}).then(async () => {
    stewardRuntime.lastMaintenanceAt = now; // 故障也节流,坏文件/瞬时锁不能让每拍变成全量扫描。
    const file = stewardInboxPath();
    try { await fsp.stat(file); } catch (error) { if (error.code === 'ENOENT') return; throw error; }
    const input = fs.createReadStream(file, { encoding: 'utf8' });
    const lines = require('node:readline').createInterface({ input, crlfDelay: Infinity });
    const history = [], active = [];
    let latest = null, count = 0;
    try {
      for await (const line of lines) {
        if (!line.trim()) continue;
        const row = safeJsonParse(line, null);
        // 未知/损坏格式交给原有读取与修复纪律;整理器不擅自丢弃无法理解的数据。
        if (!row || !Number.isSafeInteger(Number(row.inboxSeq)) || !STEWARD_EVENT_KINDS.includes(row.kind)) throw new Error('steward.inbox_maintenance_invalid_row');
        count += 1;
        if (!latest || Number(row.inboxSeq) > Number(latest.inboxSeq)) latest = row;
        if (row.kind === 'needs_you' && stewardInboxPendingState(row, pending) !== 'not_pending') active.push(row);
        else if (!Number.isFinite(Date.parse(row.at)) || Date.parse(row.at) >= now - STEWARD_INBOX_RETENTION_MS) {
          history.push(row);
          if (history.length > STEWARD_INBOX_HISTORY_MAX) history.shift();
        }
      }
    } finally { lines.close(); input.destroy(); }
    const kept = active.concat(history);
    if (latest && !kept.includes(latest)) kept.push(latest);
    kept.sort((a, b) => Number(a.inboxSeq) - Number(b.inboxSeq));
    if (kept.length < count) await atomicWriteJson(file, kept.map(row => JSON.stringify(row)).join('\n') + '\n', { mode: 0o600 });
    stewardRuntime.lastMaintenanceAt = now;
  });
  stewardAppendChain = next.catch(() => {});
  return next;
}

// 游标读取。读坏/缺失 → 冷启动(inboxSeq 从 inbox 尾行恢复,去重集合从 inbox 尾部 N 行重建,
// 三源只建基线不补历史)。这条正是「cursor 读坏 → 从零开始但不重复已在 inbox 里的键」。
async function stewardLoadState() {
  if (stewardRuntime.loaded) return;
  stewardResetRuntimeState();
  const rows = await stewardReadInboxRows();
  const tail = rows.slice(-STEWARD_DEDUPE_TAIL_ROWS);
  for (const row of tail) for (const key of stewardInboxRowDedupeKeys(row)) stewardRuntime.seen.add(key);
  for (const row of rows) stewardRuntime.inboxSeq = Math.max(stewardRuntime.inboxSeq, Number(row.inboxSeq) || 0);

  // 116-3 P1-8:把「游标文件不存在」与「游标文件坏了」分开。前者是真冷启动(第一次跑,没有历史要补);
  // 后者按注释一直宣称的口径是「从零开始,重复由 seen 兜底」,而修前的实现是 cold 保持 true ->
  // stewardCollectEvents 把每个会话的基线【直接设成当前版本号】,于是从损坏那一刻回溯到最后一次成功
  // 保存之间的全部 mission-change / agent-run 增量被静默跳过,连一条错误日志都没有。
  let raw = null;
  let corrupt = false;
  try {
    raw = safeJsonParse(await fsp.readFile(stewardCursorPath(), 'utf8'), null);
    if (!raw) corrupt = true;                                   // 文件在,但不是合法 JSON
  } catch (error) {
    raw = null;
    if (!error || error.code !== 'ENOENT') corrupt = true;       // 文件在但读不动(权限/IO):同样按损坏处理
  }
  if (raw && typeof raw === 'object' && Number(raw.schema) !== STEWARD_CURSOR_SCHEMA) corrupt = true;
  if (raw && typeof raw === 'object' && Number(raw.schema) === STEWARD_CURSOR_SCHEMA) {
    const sources = (raw.sources && typeof raw.sources === 'object') ? raw.sources : {};
    const mc = (sources.missionChanges && typeof sources.missionChanges === 'object' && !Array.isArray(sources.missionChanges)) ? sources.missionChanges : {};
    const ar = (sources.agentRuns && typeof sources.agentRuns === 'object' && !Array.isArray(sources.agentRuns)) ? sources.agentRuns : {};
    for (const [sid, revision] of Object.entries(mc).slice(0, STEWARD_CURSOR_MAX_SESSIONS)) {
      const n = Number(revision);
      if (safeSessionId(sid) && Number.isSafeInteger(n) && n >= 0) stewardRuntime.cursor.missionChanges[sid] = n;
    }
    for (const [runId, seq] of Object.entries(ar).slice(0, STEWARD_CURSOR_MAX_RUNS)) {
      const n = Number(seq);
      if (safeSessionId(runId) && Number.isSafeInteger(n) && n >= 0) stewardRuntime.cursor.agentRuns[runId] = n;
    }
    const pending = Array.isArray(sources.pendingIds) ? sources.pendingIds : [];
    for (const key of pending.slice(0, STEWARD_CURSOR_MAX_PENDING)) if (typeof key === 'string' && key) stewardRuntime.cursor.pendingIds.add(key);
    // 116-3 P1-9:budget 类事件的持久去重集合(键 = sessionId)。缺这一段的老游标读出来是空集,
    // 于是重启后每个仍标着 budgetExhausted 的事项会再入箱一次 —— 那不算错(重启补一次是可接受的),
    // 真正被修掉的是「长跑进程里滑出 2000 行尾窗之后反复重复」。
    const budgetSeen = Array.isArray(sources.budgetSeen) ? sources.budgetSeen : [];
    for (const sid of budgetSeen.slice(0, STEWARD_CURSOR_MAX_SESSIONS)) if (typeof sid === 'string' && sid) stewardRuntime.cursor.budgetSeen.add(sid);
    // 116-4:第四源游标。老游标没有这一段 -> 读出来是空对象 = 每条会话都算「首见」,由首见纪律
    // (只有关心的 + 最近动过的 + 回合数不多的才补一条)兜住,不会把历史整份倒灌进箱子。
    const st = (sources.sessionTurns && typeof sources.sessionTurns === 'object' && !Array.isArray(sources.sessionTurns)) ? sources.sessionTurns : {};
    for (const [sid, value] of Object.entries(st).slice(0, STEWARD_CURSOR_MAX_SESSIONS)) {
      if (!safeSessionId(sid) || !value || typeof value !== 'object') continue;
      const turnSeq = Number(value.turnSeq);
      if (!Number.isSafeInteger(turnSeq) || turnSeq < 0) continue;
      stewardRuntime.cursor.sessionTurns[sid] = { turnSeq, stamp: String(value.stamp || '') };
    }
    const savedSeq = Number(raw.inboxSeq);
    if (Number.isSafeInteger(savedSeq) && savedSeq > stewardRuntime.inboxSeq) stewardRuntime.inboxSeq = savedSeq;
    stewardRuntime.cold = false;
  }
  if (corrupt) {
    // 「从零开始」= 三源首见时基线设 0、把历史增量真的读进来(上限仍是 STEWARD_FIRST_SIGHT_MAX_*),
    // 重复交给 seen 集合兜底(它已经从 inbox 尾部 2000 行重建过了)。并且【留下痕迹】:
    // 修前这条路径连 lastError 都不置,用户与后来的人根本不知道游标丢过。
    stewardRuntime.cold = false;
    stewardRuntime.lastError = 'cursor-v1.json 损坏或不可读,本次按「从零开始」重建(重复由去重集合兜底)';
    try { logEvent({ kind: 'steward_cursor_corrupt', detail: stewardRuntime.lastError }); } catch { /* 观测绝不反噬 */ }
  }
  stewardRuntime.loaded = true;
}

// append:与 session-changes 同款原语(repairMissionChangeTornTail + appendFile),per-process 串行。
function stewardAppendInboxRows(rows) {
  if (!rows.length) return Promise.resolve();
  const file = stewardInboxPath();
  const payload = rows.map(row => JSON.stringify(row)).join('\n') + '\n';
  const next = stewardAppendChain.catch(() => {}).then(async () => {
    await fsp.mkdir(stewardDir(), { recursive: true });
    await repairMissionChangeTornTail(file); // 尾部半行先截干净,再整行 append(防焊接)
    // Windows 上杀软/备份软件短暂持锁的 EBUSY/EPERM/EACCES:与 02 appendIntervention 同款有界重试。
    // 仍失败就抛给 stewardTickOnce —— 那里把这一批原始事件放回结转队列,下一拍重来(见那里的注释)。
    for (let attempt = 0; ; attempt++) {
      try { await fsp.appendFile(file, payload, 'utf8'); break; }
      catch (e) { if (attempt >= 3 || !/^(EPERM|EBUSY|EACCES)$/.test(String(e && e.code))) throw e; await new Promise(r => setTimeout(r, 10 + attempt * 20)); }
    }
    // 121-K2a(§6.1 第 3 条):箱子真的多了这些行之后才派。正文不进事件面 —— 只有「哪条线程、哪一类」;
    // 想看内容仍走 GET /api/steward/inbox(§6.1 红线:事件流不承载正文)。
    // 121-K6a(34 号文 §4.3 安静卡):补 quiet(在场门②情形打的旗)与卡上要印的一句话(ask)——
    // needs_you 是问句,failed/stalled/budget 是「一句事实」,两者在归一化函数里都已经写进
    // payload.ask/payload.summary(与 thread.done 的 summary 同一档:构造好的短句,不是正文,
    // §6.1 红线挡的是工具输出原文)。这里只挑一个已有字段透传,不新算一遍。
    for (const row of rows) {
      const payload = (row && row.payload && typeof row.payload === 'object') ? row.payload : {};
      const frame = { sessionId: String((row && row.sessionId) || ''), kind: String((row && row.kind) || '') };
      // 123-M2:两个【标识】字段。安静卡「稍后」要把 sourceRef 指回它是从哪一行来的
      // (37 号文 §3.5 的 `sourceRef:{inboxSeq, sessionId, kind}`),而 reminder 那一类可以完全不
      // 属于任何线程 —— 没有 taskId 就没有第二个身份可用,两条提醒会在前端合并成一张。
      // 两个都是 id/序号,不是正文(§6.1 红线挡的是工具输出原文)。
      if (Number(row && row.inboxSeq) > 0) frame.inboxSeq = Number(row.inboxSeq);
      if (payload.taskId) frame.taskId = String(payload.taskId);
      if (payload.quiet === true) frame.quiet = true;
      const ask = payload.ask || payload.summary || '';
      if (ask) frame.ask = String(ask).slice(0, 200);
      // interventionId 是 POST /api/chat/answer 顶层 questionId 要的那个键(pendingQuestions 的注册键,
      // 与子问题自己的 answerQuestionId 不是同一个 id)——安静卡「候选答案按钮」两个 id 都要,缺一不可。
      if (payload.interventionId) frame.interventionId = String(payload.interventionId);
      if (payload.answerQuestionId) frame.answerQuestionId = String(payload.answerQuestionId);
      if (Array.isArray(payload.options) && payload.options.length) frame.options = payload.options;
      RUYI_EVENTS.emit('inbox.appended', frame);
    }
  });
  stewardAppendChain = next.catch(() => {});
  return next;
}

// 按 order 的顺序从 source 里挑出「有游标条目」的键,一趟同时产出两份:
//   kept      —— 进程内存里留的(至多 memMax 条);
//   persisted —— 写进 cursor-v1.json 的(至多 persistMax 条,恒为 kept 的前缀,所以「活跃的先留」的优先级不变)。
// 计数用局部计数器,【不要】在循环里对累积对象再取 Object.keys(obj).length —— 那是 O(n^2),
// 把上限调到 2 万之后 2000 会话一次 save 就阻塞事件循环 460ms(实测)。
function stewardTrimCursorMap(order, source, memMax, persistMax) {
  const kept = {};
  const persisted = {};
  let keptCount = 0;
  let persistedCount = 0;
  for (const key of order) {
    if (keptCount >= memMax) break;
    if (!Object.prototype.hasOwnProperty.call(source, key)) continue;
    if (Object.prototype.hasOwnProperty.call(kept, key)) continue;   // order 里重复的键只算一次
    kept[key] = source[key];
    keptCount += 1;
    if (persistedCount < persistMax) { persisted[key] = source[key]; persistedCount += 1; }
  }
  return { kept, persisted };
}

// 游标收紧 + 落盘。两档容量:内存游标保留本轮还见得到的全部会话/run(硬顶见 STEWARD_CURSOR_MEM_MAX_*,
// 会话被删了自然被清掉),落盘只取其中排在最前(活跃优先)的 STEWARD_CURSOR_MAX_* 条 —— 重启后读回的
// 语义与修前一致(超出落盘上限的会话重启后仍算首见),但运行期不再每拍把它们重新当首见。
// 落盘只在内容真的变了时才写(指纹见 stewardRuntime.cursorSig),并且写紧凑 JSON(没人读缩进)。
async function stewardSaveCursor(activeSessionIds, activeRunIds) {
  const mc = stewardTrimCursorMap(activeSessionIds, stewardRuntime.cursor.missionChanges, STEWARD_CURSOR_MEM_MAX_SESSIONS, STEWARD_CURSOR_MAX_SESSIONS);
  const ar = stewardTrimCursorMap(activeRunIds, stewardRuntime.cursor.agentRuns, STEWARD_CURSOR_MEM_MAX_RUNS, STEWARD_CURSOR_MAX_RUNS);
  stewardRuntime.cursor.missionChanges = mc.kept;
  stewardRuntime.cursor.agentRuns = ar.kept;
  const pendingIds = [...stewardRuntime.cursor.pendingIds].slice(0, STEWARD_CURSOR_MAX_PENDING);
  // 落盘容量不能裁掉内存中的当前待决,否则超出 2000 的部分每拍重复入箱,整理时还会被误认已处理。
  // 116-3 P1-9:budgetSeen 与另外两源同款做容量控制 —— 只留【本轮还见得到的会话】(会话没了就没有
  // 再去重的对象),再夹一次硬顶。它不像 pendingIds 那样每轮整份重算(预算触顶是一次性持久标记,
  // 不会「自然消失」),所以裁剪必须显式做,否则长跑进程里它只增不减。
  const activeSet = new Set(activeSessionIds);
  const budgetKept = [];
  for (const key of stewardRuntime.cursor.budgetSeen) {
    if (budgetKept.length >= STEWARD_CURSOR_MEM_MAX_SESSIONS) break;
    if (activeSet.has(String(key).split('\u0000')[0])) budgetKept.push(key);   // 键 = 会话 id(+ \u0000 + 用尽时刻)
  }
  stewardRuntime.cursor.budgetSeen = new Set(budgetKept);
  const budgetSeen = budgetKept.slice(0, STEWARD_CURSOR_MAX_SESSIONS);
  // 116-4:第四源游标同款裁剪 —— 只留本轮还见得到的会话(会话被删了就没有再去重的对象),再夹硬顶。
  const st = stewardTrimCursorMap(activeSessionIds, stewardRuntime.cursor.sessionTurns, STEWARD_CURSOR_MEM_MAX_SESSIONS, STEWARD_CURSOR_MAX_SESSIONS);
  stewardRuntime.cursor.sessionTurns = st.kept;
  const missionChanges = mc.persisted;
  const agentRuns = ar.persisted;
  const sessionTurns = st.persisted;
  const sig = stewardRuntime.inboxSeq + '|' + JSON.stringify({ missionChanges, agentRuns, pendingIds, budgetSeen, sessionTurns });
  if (sig === stewardRuntime.cursorSig) return { written: false };
  await fsp.mkdir(stewardDir(), { recursive: true });
  await atomicWriteJson(stewardCursorPath(), JSON.stringify({
    schema: STEWARD_CURSOR_SCHEMA,
    inboxSeq: stewardRuntime.inboxSeq,
    updatedAt: nowIso(),
    sources: { missionChanges, agentRuns, pendingIds, budgetSeen, sessionTurns },
  }));
  stewardRuntime.cursorSig = sig;   // 写成功才记:写失败下一拍照旧重试
  return { written: true };
}

// ── 116-4 第四源 sessionTurns(27 号文 §11.7)─────────────────────────────────
// 为什么需要它:前三源全都挂在【事项】上 —— 02 的 bumpMissionChangeSeq 读会话头,`!head.mission`
// 就直接返回 null,而管家自己开的线程(steward_quick_ask / steward_thread_new)恰恰【没有】 mission
// 容器。于是它们跑完之后三条源日志一个字都不写,收件箱永远是空的,管家也就永远不会被唤醒。
// 116-4 复现:开一条速查 + 一条委托线程,两条都真跑完,inbox 0 行、cursor 里两条会话 changeSeq 全 0
// —— 与用户机器上的证据逐条对上。
//
// 事实来源是会话头本身:turnSeq 前进 + 当前无活回合 = 这条线程的一个回合结束了。成败读 13g 在回合
// settle 之后落的 stewardLastTurn(会话头上本来没有任何回合成败字段,实测过)。
// 成本:先拿投影免费给的 sourceStamp(会话文件的 size:mtime 指纹)比一次,没变就连头都不读。
async function stewardReadTurnHead(sessionId) {
  try { return safeJsonParse(await fsp.readFile(sessionPath(sessionId), 'utf8'), null); } catch { return null; }
}

// 「管家关心这条会话吗」的唯一判据(§11.7)【定义已搬到 06i-steward-core.js】——
// 117r-D1 起第二个消费者是 13e 的卡片产生条件(看板正文的唯一数据源 GET /api/missions),
// 而 13e 拼在 13i 之前,引用 13i 会是前向边。这里【不】留第二份实现,也不留同名薄封装:
// 本文件下面那处 stewardCollectSessionTurn 直接调 06i 的那一份(后向边,已在依赖图里)。

// 2026-09-24(用户:「线程没跑完交付就一直把进度同步给我」):回合收了、但这条线程还有后台活儿在跑
// (后台命令 / 活着的子代理与班组 run)时,这一回合不算交付。按「回合还在跑」同一纪律不入箱、不推基线,
// 等后台活儿全部落地后的那一轮再报【一次】—— 否则管家先报一遍「回合跑完了」(那一回合以工具调用收尾,
// 没有收口的话,交付卡只能画「没取到原文」),后台跑完再被「班组收工」叫醒报第二遍。
// 读的是进程内真值(11 的后台 shell 表经 EventStreamHooks 延迟绑定、07 的 activeAgentRuns),不读盘。
const STEWARD_RUN_TERMINAL = new Set(['succeeded', 'failed', 'partial', 'stopped', 'cancelled', 'skipped']);
function stewardThreadBackgroundBusy(sid) {
  try {
    const shells = EventStreamHooks.backgroundShells;
    if (shells && typeof shells.rows === 'function' && shells.rows(sid).length) return true;
  } catch { /* 读不到按没有:这道门管的是打扰纪律,fail-open 回到修前行为 */ }
  for (const [, live] of activeAgentRuns) {
    const run = live && live.run;
    if (run && run.sessionId === sid && !STEWARD_RUN_TERMINAL.has(String(run.status || ''))) return true;
  }
  return false;
}
// 本轮因「后台活儿没完」按住回合报告的【被看管】线程。它们的班组 done 由那条迟到的回合报告一并交代,
// 不再单独叫醒管家(failed / 预算触顶照报 —— 那是「有事要你知道」)。每轮 stewardCollectEvents 开头清空。
const stewardHeldTurnSessions = new Set();

// 返回本轮该为这条会话入箱的事件(至多一条)或 null;顺带维护它自己的游标。
async function stewardCollectSessionTurn(sid, missionId, row, now) {
  const stamp = String((row && row.sourceStamp) || '');
  const known = stewardRuntime.cursor.sessionTurns[sid];
  if (known && known.stamp && stamp && known.stamp === stamp) return null;   // 文件一个字节没动:零磁盘读
  const head = await stewardReadTurnHead(sid);
  if (!head || !head.id) return null;
  const turnSeq = Math.max(0, Number(head.turnSeq) || 0);
  // 3.0 收口走查(第四波):再加 turnSettlers(10 runSessionTurn 从起手到收尾整段登记)。activeChildren 挡不住两个窗口 ——
  // 起手:turnSeq 已 +1 落盘、引擎还没登记进 activeChildren(中间隔着 captureWorkspaceTurnBaseline,大工作区好几秒);
  // 收尾:activeChildren 已删、turnOutcomePending 还没加(中间是 reconcile / 存会话 / onTurnEnd 几次 await)。
  // 修前已见过的线程落在这两个窗口里会被报一条「跑完了」并把基线推到 N,真正的结果(尤其是失败)再也报不出来。
  // 首见那一支早有 inFlight 判据兜同一个窗口;这里对所有线程统一用 turnSettlers。
  if (activeChildren.has(sid) || turnOutcomePending.has(sid) || turnSettlers.has(sid)) {
    // (turnOutcomePending:回合已收、成败账正在写 —— 同样等下一拍,见 04 的头注)
    // 回合还在跑:不入箱,而且【不】记指纹 —— 记了下一轮就会跳过这个头,等它跑完再也没人看它一眼。
    // 117p(用户第七轮走查:「2.0 回合已经跑完了,管家没有收到体现也没收工」):首见就撞上活回合时,
    // 基线必须是【这一回合之前】那个号。turnSeq 在回合【开始】那一刻就 +1 落盘(05:88 / 09:1292,
    // 都紧跟 saveSession),所以此刻头上的号就是【正在跑】的那一回合 —— 记成基线 = 把它算作已报过,
    // 等它真的跑完 turnSeq 没再前进,唯一那条 done 被永久吞掉。真机证据(2026-09-08):
    // sess_e97b29759a586485 头上 turnSeq:1 + stewardLastTurn{seq:1,ok:true},游标记着 {turnSeq:1},
    // inbox 里这条会话零行 —— 管家开的线程第一回合几乎必然命中(轮询 15 秒,那条线程跑了 11 分钟)。
    stewardRuntime.cursor.sessionTurns[sid] = { turnSeq: known ? known.turnSeq : Math.max(0, turnSeq - 1), stamp: '' };
    return null;
  }
  const watched = stewardWatchedThread(head, sid, missionId);
  if (turnSeq > 0 && stewardThreadBackgroundBusy(sid)) {
    // 同上一支:基线停在已报过的那一回合(首见退到上一回合;冷启动只建基线,不把老回合倒灌进箱),
    // stamp 置空保证下一轮一定重读这个头。后台活儿跑完的那一轮 turnSeq > 基线,照常报一次。
    const heldBaseline = known ? known.turnSeq : (stewardRuntime.cold ? turnSeq : Math.max(0, turnSeq - 1));
    stewardRuntime.cursor.sessionTurns[sid] = { turnSeq: heldBaseline, stamp: '' };
    if (watched && turnSeq > heldBaseline) stewardHeldTurnSessions.add(sid);
    return null;
  }
  if (known == null) {
    // 首见。【不能】一律按「基线 = 当前 turnSeq」:速查线程从建到跑完只要几秒,而轮询 15 秒一轮 ——
    // 第一次看见它时回合早就结束了,按当前 turnSeq 建基线等于把唯一那条 done 永久吞掉(这正是本波
    // 要修的那个洞的另一半)。故:关心的 + 最近动过的 + 回合数不多的线程,首见就补这一条;
    // 冷启动(本次装载没有可用游标)与存量老线程仍然只建基线,不把历史倒灌进箱子。
    const updatedMs = Date.parse(String(head.updatedAt || ''));
    const fresh = Number.isFinite(updatedMs) && (now - updatedMs) <= STEWARD_ACTIVE_WINDOW_MS;
    const backfill = watched && fresh && !stewardRuntime.cold && turnSeq > 0 && turnSeq <= STEWARD_FIRST_SIGHT_MAX_TURNS;
    // 117p ②(同一条真机证据的另一半):上面 activeChildren.has(sid) 那道判据挡不住「回合已起手、
    // 还没登记进 activeChildren」的窗口 —— 09-workflow.js 把 turnSeq 落盘(1292)与
    // activeChildren.set(1381)之间隔着 captureWorkspaceTurnBaseline(大工作区要好几秒)。首见正好
    // 落在这个窗口里时,backfill 会当场报一条「这回合跑完了」(其实还在跑),并把基线推到当前
    // turnSeq —— 真跑完时反而再也报不出来。判据用确定性落盘证据,不猜时间/心跳:管家发起的线程由
    // 13g 的 stewardRecordLaunchOutcome 在 settle 之后写 stewardLastTurn,last.seq >= turnSeq 才算
    // 这一回合真的结束了。只在 known == null 这一次用它:之后 known != null,普通的
    // turnSeq > baseline 就够了 —— 否则用户在 2.0 视窗里自己接着聊的那些回合(它们不写
    // stewardLastTurn)会被永久判成「还没结束」,那是把一个洞换成另一个洞。
    const last = (head.stewardLastTurn && typeof head.stewardLastTurn === 'object') ? head.stewardLastTurn : null;
    const inFlight = String(head.launchedBy || '') === 'steward'
      && !(Math.max(0, Number(last && last.seq) || 0) >= turnSeq);
    if (backfill && inFlight) {
      // 回合已起手、还没登记进 activeChildren 的窗口:这一轮什么都不报,基线退到上一回合,
      // 等 13g 的成败账落盘之后的某一轮再报 —— stamp 置空,保证下一轮一定会重读这个头。
      stewardRuntime.cursor.sessionTurns[sid] = { turnSeq: Math.max(0, turnSeq - 1), stamp: '' };
      return null;
    }
    stewardRuntime.cursor.sessionTurns[sid] = { turnSeq: backfill ? 0 : turnSeq, stamp: backfill ? '' : stamp };
    if (!backfill) return null;
  }
  const baseline = Math.max(0, Number(stewardRuntime.cursor.sessionTurns[sid].turnSeq) || 0);
  stewardRuntime.cursor.sessionTurns[sid] = { turnSeq, stamp };
  if (!watched || turnSeq <= baseline) return null;
  const evt = stewardNormalizeSessionTurn(sid, missionId, head, turnSeq);
  if (evt) stewardRuntime.sourcesSeen.sessionTurns += 1;
  return evt;
}

// ────────────────────────────────────────────────────────────────────────────
// 轮询一轮。
//
// 成本纪律(§11.3「不得每次全量扫所有会话」):先取投影索引(进程内可重建缓存,脏页增量刷新),
// 只对【活跃】会话与 run 做增量磁盘读:
//   · Mission Ledger:只有 row.changeSeq > 已记游标才读(投影里的 changeSeq 就是免费的「有没有新变化」);
//   · agent run 事件:只读活跃会话里【未终态 或 24 小时内更新过】的 run;
//   · 待决:直接来自投影内存数组,零磁盘读。
// ────────────────────────────────────────────────────────────────────────────
async function stewardCollectEvents() {
  const index = await getPretenderProjectionIndex();
  const now = Date.now();
  const events = [];
  const activeSessionIds = [];   // 活跃会话优先(游标硬顶到了先丢不活跃的,见 stewardSaveCursor)
  const idleSessionIds = [];
  const activeRunIds = [];
  const nextPending = new Set();
  stewardHeldTurnSessions.clear();

  // ── ⑤ 用户交接(121-K3,§4.4)。取走这一拍之前排进来的全部交接事件 —— 它不读盘、不走游标,
  //    排在最前是因为它发生得最早(用户按下开关的那一刻),排序器随后会按 at 再排一遍。
  const adoptedQueue = stewardRuntime.adopted;
  stewardRuntime.adopted = [];
  for (const record of adoptedQueue) {
    const evt = stewardNormalizeThreadAdopted(record);
    if (evt) events.push(evt);
  }

  for (const row of (index && Array.isArray(index.sessions) ? index.sessions : [])) {
    const sid = row && safeSessionId(row.sessionId);
    if (!sid) continue;
    // 116f 排除面之一:管家会话自己【绝不】进收件箱(否则管家的每个回合都会变成下一个回合的输入,
    // 一条自激励循环)。这里按固定 id 判(06i 的 STEWARD_SESSION_ID)而不是按会话头原始 kind:投影行
    // 里的 kind 是 sessionKind() 归一后的值(会把 steward 说成 quick_ask),拿到原始 kind 要为每行多读
    // 一次会话头 —— 每 15 秒一轮的轮询器不该为一个恒等判断付这个代价。双保险:13e 的扫描器只认
    // /^sess_/ 前缀的会话文件,取名 'steward' 的管家会话本来就到不了这个循环。
    if (sid === STEWARD_SESSION_ID) continue;
    const missionId = String(row.missionId || sid);
    const card = row.card || null;
    const updatedMs = Date.parse(String((card && card.updatedAt) || ''));
    const recent = Number.isFinite(updatedMs) && (now - updatedMs) <= STEWARD_ACTIVE_WINDOW_MS;

    // ── 待决(全局,不受活跃集限制:待决就是「需要你」,不能因为线程安静就漏报) ──
    let hasPending = false;
    for (const iv of (Array.isArray(row.interventions) ? row.interventions : [])) {
      if (!iv || iv.status !== 'pending') continue;
      hasPending = true;
      const id = String(iv.id || '');
      if (!id) continue;
      const pendingKey = sid + '\u0000' + id;
      nextPending.add(pendingKey);
      if (stewardRuntime.cursor.pendingIds.has(pendingKey)) continue;
      const evt = stewardNormalizePendingIntervention(sid, missionId, iv);
      if (evt) events.push(evt);
    }

    // ── 预算触顶(一次性持久标记) ──
    // 116-3 P1-9:去重键进游标(与 pendingIds 同款持久化),不再只靠内存 seen 集合的 2000 行尾窗。
    // 代码走查 C7:键是「会话 + 这一次用尽的时刻」。修前只按会话 id 去重,任务重启后再次用尽永远不再提醒。
    // 旧游标里的裸会话 id 认作「当前这一次已经提醒过」,换成新键(升级时不重复提醒)。
    const budgetEvt = stewardNormalizeBudgetExhausted(sid, missionId, card);
    // 卡片还没带上用尽时刻(升级前落盘的索引切片)时,旧键原样留着、照样当「已提醒」,等带上了再换。
    const exhaustedAt = String((card && card.mission && card.mission.budgetExhaustedAt) || '');
    const budgetKey = sid + '\u0000' + exhaustedAt;
    const budgetSeen = stewardRuntime.cursor.budgetSeen;
    if (budgetEvt && budgetSeen.has(sid)) { if (exhaustedAt) { budgetSeen.delete(sid); budgetSeen.add(budgetKey); } }
    else if (budgetEvt && !budgetSeen.has(budgetKey)) {
      budgetSeen.add(budgetKey);
      events.push(budgetEvt);
    }

    // ── ④ 会话回合(116-4 第四源) ──
    // 位置纪律:必须在下面那条「不活跃且账本没新版本就 continue」【之前】。速查线程没有 mission 卡片,
    // card.updatedAt 是空的 -> recent 恒 false -> active 恒 false;第二轮开始它就会被那条 continue
    // 直接跳过,放在后面等于第四源只在会话首见那一轮生效。
    const turnEvt = await stewardCollectSessionTurn(sid, missionId, row, now);
    if (turnEvt) events.push(turnEvt);

    const active = hasPending || recent;
    const knownRevision = Object.prototype.hasOwnProperty.call(stewardRuntime.cursor.missionChanges, sid)
      ? Number(stewardRuntime.cursor.missionChanges[sid]) : null;
    const revision = Math.max(0, Number(row.changeSeq) || 0);
    if (!active && knownRevision != null && revision <= knownRevision) { idleSessionIds.push(sid); continue; }
    (active ? activeSessionIds : idleSessionIds).push(sid);

    // ── ① Mission Change Ledger 增量 ──
    if (knownRevision == null) {
      // 首见:冷启动(或存量老会话)只建基线,不把历史灌进箱子;真正的新会话(revision 很小)照常全读。
      const baseline = (stewardRuntime.cold || revision > STEWARD_FIRST_SIGHT_MAX_REVISION) ? revision : 0;
      stewardRuntime.cursor.missionChanges[sid] = baseline;
      if (baseline < revision) {
        const meta = await readMissionChangesWithMeta(sid, revision).catch(() => null);
        for (const record of (meta && Array.isArray(meta.records) ? meta.records : [])) {
          if (Number(record.seq) <= baseline) continue;
          const evt = stewardNormalizeMissionChange({ ...record, sessionId: sid, missionId });
          if (evt) events.push(evt);
        }
        stewardRuntime.cursor.missionChanges[sid] = Math.max(baseline, revision);
      }
    } else if (revision > knownRevision) {
      const meta = await readMissionChangesWithMeta(sid, revision).catch(() => null);
      for (const record of (meta && Array.isArray(meta.records) ? meta.records : [])) {
        if (Number(record.seq) <= knownRevision) continue;
        const evt = stewardNormalizeMissionChange({ ...record, sessionId: sid, missionId });
        if (evt) events.push(evt);
      }
      stewardRuntime.cursor.missionChanges[sid] = Math.max(knownRevision, revision);
    }

    // ── ② agent run 事件增量(只看活跃会话里的活跃 run) ──
    if (!active) continue;
    const runs = await listAgentRuns(sid).catch(() => []);
    for (const run of runs) {
      const runId = run && safeSessionId(run.id);
      if (!runId) continue;
      const terminal = ['succeeded', 'failed', 'partial', 'stopped'].includes(String(run.status || ''));
      const runUpdatedMs = Date.parse(String(run.completedAt || run.updatedAt || run.createdAt || ''));
      const runRecent = Number.isFinite(runUpdatedMs) && (now - runUpdatedMs) <= STEWARD_ACTIVE_WINDOW_MS;
      if (terminal && !runRecent) continue;
      activeRunIds.push(runId);
      const eventSeq = Math.max(0, Number(run.eventSeq) || 0);
      const knownSeq = Object.prototype.hasOwnProperty.call(stewardRuntime.cursor.agentRuns, runId)
        ? Number(stewardRuntime.cursor.agentRuns[runId]) : null;
      let afterSeq;
      // 首见的 run:只有「本进程已经热过 + 这个 run 最近才动过 + 事件不多」三条同时成立才从 0 全读;
      // 否则只建基线(冷启动/老 run 复活都不把历史倒灌进箱,也就不依赖去重集合去兜底)。
      if (knownSeq == null) afterSeq = (stewardRuntime.cold || !runRecent || eventSeq > STEWARD_FIRST_SIGHT_MAX_EVENT_SEQ) ? eventSeq : 0;
      else afterSeq = knownSeq;
      stewardRuntime.cursor.agentRuns[runId] = afterSeq;
      const page = await readAgentRunEvents(sid, runId, afterSeq, STEWARD_RUN_EVENT_PAGE).catch(() => ({ events: [] }));
      let maxSeq = afterSeq;
      for (const evt of (page && Array.isArray(page.events) ? page.events : [])) {
        maxSeq = Math.max(maxSeq, Number(evt.seq) || 0);
        const normalized = stewardNormalizeRunEvent(sid, missionId, runId, evt);
        // 班组收工与本线程的回合报告是同一件事:回合报告这一轮就在箱里(turnEvt)或正被按住等后台落地时,
        // done 不再单独叫醒管家(游标照推,事件视为已消费)。failed/budget 不受影响。
        if (normalized && normalized.kind === 'done' && (turnEvt || stewardHeldTurnSessions.has(sid))) continue;
        if (normalized) events.push(normalized);
      }
      stewardRuntime.cursor.agentRuns[runId] = maxSeq;
    }
  }

  stewardRuntime.cursor.pendingIds = nextPending;
  return { events, activeSessionIds: [...activeSessionIds, ...idleSessionIds], activeRunIds };
}

async function stewardTickOnce() {
  const generation = stewardRuntime.generation;
  await stewardLoadState();
  const { events, activeSessionIds, activeRunIds } = await stewardCollectEvents();
  if (generation !== stewardRuntime.generation) return { written: 0, aborted: true };
  // 116-3 P0-3:上一轮结转下来的事件排在最前(它们更早发生,游标也早已越过它们)。
  const carried = stewardRuntime.carry;
  stewardRuntime.carry = [];
  // 121-K3(§4.3):在场门只作用于【本轮新收的】事件。结转下来的那批上一轮已经过过门了,
  // 再过一次会拿【此刻】的在场状态去重判一件几分钟前发生的事,那是两个时刻的事实相互污染。
  const gated = stewardApplyPresenceGate(events);
  const fresh = carried.concat(gated)
    .filter(evt => !stewardRuntime.seen.has(stewardEventDedupeKey(evt)))
    .sort((a, b) => String(a.at).localeCompare(String(b.at)));
  // 截断改在【合并之前】、对原始事件做,超出的部分原样结转到下一轮 —— 旧写法是「合并后 slice(0,200)」,
  // 被切掉的那些事件的游标已经前移,下一轮再也读不到它们(P0-3 的根因)。
  const head = fresh.slice(0, STEWARD_TICK_MAX_EVENTS);
  const rest = fresh.slice(STEWARD_TICK_MAX_EVENTS);
  if (rest.length) {
    const kept = rest.slice(0, STEWARD_CARRY_MAX_EVENTS);
    stewardRuntime.carry = kept;
    logEvent({ kind: 'steward_inbox_deferred', deferred: kept.length, dropped: rest.length - kept.length });
  }
  const merged = stewardMergeInboxEvents(head, STEWARD_MERGE_WINDOW_MS);
  const seqBefore = stewardRuntime.inboxSeq;
  const rows = [];
  for (const row of merged) {
    stewardRuntime.inboxSeq += 1;
    rows.push({
      inboxSeq: stewardRuntime.inboxSeq,
      kind: row.kind,
      sessionId: row.sessionId,
      missionId: row.missionId,
      runId: row.runId,
      seq: row.seq,
      at: row.at,
      payload: row.payload,
      count: row.count,
    });
  }
  // 116-2e(§11.1 第 2 项「速查线程」):落盘【前】给速查会话的 done 行补 quick:true 与 answer
  // (最后一句助手原话)。实现住 13g(它要装载会话正文),经 06i 的延迟绑定命名空间调 —— 直接写
  // 13g 的函数名会是前向边。旁路纪律:钩子未填充或抛错都不影响这一轮已经归一好的行。
  if (rows.length && typeof StewardHooks.enrichInboxRows === 'function') {
    try { await StewardHooks.enrichInboxRows(rows); } catch { /* 增强失败只是少两个字段,不反噬轮询器 */ }
  }
  // 落盘失败(有界重试之后仍是 EBUSY/EIO/ENOSPC …)不许丢事件:四源游标、待决集合、budgetSeen、交接队列
  // 在 stewardCollectEvents 里都已经越过了这一批 —— 修前异常直接冒出去,这些事件从此永远读不回来
  // (一条「需要你」的权限请求就此从收件箱里消失)。这里不去逐个回滚游标(交接队列与 budgetSeen 是内存态,
  // 回滚不全),而是把这一批【原始】事件整批放回结转队列的最前面 —— 与 P0-3 的单轮上限结转同一条通路:
  // 下一拍它们排在最前、照样过去重、不再过在场门(已经过过一次)。inboxSeq 退回本批之前,
  // 不留空号;游标这一拍不落盘(异常照旧冒到 stewardRunTick 记 lastError),重启则从旧游标重读 + seen 去重。
  if (rows.length) {
    try { await stewardAppendInboxRows(rows); }
    catch (error) {
      stewardRuntime.inboxSeq = seqBefore;
      stewardRuntime.carry = head.concat(stewardRuntime.carry).slice(0, STEWARD_CARRY_MAX_EVENTS);
      try { logEvent({ kind: 'steward_inbox_append_failed', code: String((error && error.code) || ''), requeued: head.length }); } catch { /* 观测绝不反噬 */ }
      throw error;
    }
  }
  if (rows.length) stewardRuntime.lastInboxAt = nowIso();   // 116-4:唤醒链诚实 —— 「箱子最后一次真的收到东西」
  for (const row of rows) for (const key of stewardInboxRowDedupeKeys(row)) stewardRuntime.seen.add(key);
  // 去重集合在长跑进程里只增不减 —— 超过硬顶就按「装载时」的口径从 inbox 尾部重建(旧键本来也已经
  // 被游标挡住了,重建只是把内存占用重新压回上限)。
  if (stewardRuntime.seen.size > STEWARD_SEEN_MAX_KEYS) {
    const recent = (await stewardReadInboxRows()).slice(-STEWARD_DEDUPE_TAIL_ROWS);
    const rebuilt = new Set();
    for (const row of recent) for (const key of stewardInboxRowDedupeKeys(row)) rebuilt.add(key);
    stewardRuntime.seen = rebuilt;
  }
  // 冷启动只建基线,基线本身也必须落盘 —— 否则下次仍是冷启动,永远补不上历史增量。
  await stewardSaveCursor(activeSessionIds, activeRunIds);
  // 独立于入箱成功与否:整理失败不能把已落盘的一批重新投递,也不能阻止唤醒管家。
  try { await stewardMaintainInbox(); }
  catch (error) { try { logEvent({ kind: 'steward_inbox_maintenance_failed', code: String(error.code || error.message || '').slice(0, 100) }); } catch { /* 旁路 */ } }
  stewardRuntime.cold = false;
  stewardRuntime.lastTickAt = nowIso();
  // 116f: 本轮真的写进箱子的行交给回合运行器(13h 去抖 5 秒后起一个收件箱回合)。经 06i 的延迟绑定
  // 命名空间调(13g → 06i 是后向边;直接写 13h 的函数名会是前向边)。它是【旁路】:钩子未填充、
  // 抛错或运行器熔断,都不影响这一轮已经落盘的收件箱与游标。
  if (rows.length && typeof StewardHooks.onInboxBatch === 'function') {
    try { StewardHooks.onInboxBatch(rows); } catch { /* 运行器故障绝不反噬轮询器 */ }
  }
  return { written: rows.length, aborted: false };
}

async function stewardRunTick() {
  if (stewardRuntime.ticking) { stewardRuntime.wakePending = true; return { skipped: true }; }
  stewardRuntime.ticking = true;
  try {
    const result = await stewardTickOnce();
    stewardRuntime.lastError = '';
    return result;
  } catch (error) {
    stewardRuntime.lastError = String((error && error.message) || error || '').slice(0, 300);
    try { logEvent({ kind: 'steward_tick_error', error: stewardRuntime.lastError }); } catch { /* 观测绝不反噬 */ }
    return { error: stewardRuntime.lastError };
  } finally {
    stewardRuntime.ticking = false;
    if (stewardRuntime.wakePending || stewardRuntime.carry.length) {
      stewardRuntime.wakePending = false;
      stewardScheduleWake();
    }
  }
}

// ────────────────────────────────────────────────────────────────────────────
// 生命周期。开关关时 startStewardInbox 立即返回且【不做任何事】(不建目录、不起 interval)。
// ────────────────────────────────────────────────────────────────────────────
async function startStewardInbox(config) {
  const cfg = (config && typeof config === 'object') ? config : {};
  if (cfg.stewardEnabledV1 !== true) return { ok: false, running: false, enabled: false };
  const pollMs = stewardConsistencyMs(cfg.stewardPollMs);
  stewardRuntime.pollMs = pollMs;
  // 116f: start 同时解除回合队列的停机(stop 把轮询与回合一起停,start 把两者一起放开)。
  if (typeof StewardHooks.resumeRunner === 'function') { try { StewardHooks.resumeRunner(); } catch { /* 旁路 */ } }
  if (stewardRuntime.running) { await stewardRunTick(); return { ok: true, running: true, enabled: true }; } // 幂等:重复 start 只补一轮
  stewardRuntime.running = true;
  stewardRuntime.generation += 1;
  // hunt2-steward ⑥:认的是【本次起跑的代际】,不是 running 这一个布尔 —— start → stop → start 交错时,
  // 第二次 start 已经把 running 重新置 true 并挂上了自己的 interval,第一次 start 醒来只看 running
  // 会再挂一个、把第二个的句柄覆盖掉,之后 stop 只清得掉一个,另一个轮询器永远停不下来。
  const generation = stewardRuntime.generation;
  await stewardRunTick();
  if (!stewardRuntime.running) return { ok: true, running: false, enabled: true }; // 起跑途中被 stop
  if (stewardRuntime.generation !== generation) return { ok: true, running: true, enabled: true }; // 起跑途中被 stop 又 start:后来者挂 interval
  if (stewardRuntime.timer) clearInterval(stewardRuntime.timer);   // 兜底:任何时候最多一个轮询器
  stewardRuntime.timer = setInterval(() => { void stewardRunTick(); }, pollMs);
  if (stewardRuntime.timer && typeof stewardRuntime.timer.unref === 'function') stewardRuntime.timer.unref();
  return { ok: true, running: true, enabled: true };
}

function stopStewardInbox() {
  // 116f(§8.6「一键停机常驻且永远可点」):停机停的是【轮询 + 在途管家回合 + 回合队列】三样。
  // 放在最前:即使下面清 timer 抛错,回合队列也已经停了。线程自己的回合不受影响(那由线程的权限门管)。
  if (typeof StewardHooks.stopRunner === 'function') { try { StewardHooks.stopRunner(); } catch { /* 旁路 */ } }
  if (stewardRuntime.timer) { clearInterval(stewardRuntime.timer); stewardRuntime.timer = null; }
  stewardClearWake();
  stewardRuntime.wakePending = false;
  stewardRuntime.running = false;
  stewardRuntime.generation += 1; // 在途 tick 看到代际变化即放弃写入
  return { ok: true, running: false };
}

// ── 只读数据面(116c 的 steward_inbox_read 与 117 壳层复用同一实现) ──────────────
async function stewardInboxRead(opts) {
  const o = (opts && typeof opts === 'object') ? opts : {};
  const since = Math.max(0, Math.round(Number(o.since) || 0));
  const rawLimit = Number(o.limit);
  const limit = Number.isFinite(rawLimit) && rawLimit > 0
    ? Math.min(STEWARD_INBOX_LIMIT_MAX, Math.max(1, Math.round(rawLimit)))
    : STEWARD_INBOX_LIMIT_DEFAULT;
  const rows = await stewardReadInboxRows();
  const matched = rows.filter(row => Number(row.inboxSeq) > since).sort((a, b) => Number(a.inboxSeq) - Number(b.inboxSeq));
  const items = o.order === 'desc' ? matched.slice(-limit).reverse() : matched.slice(0, limit);
  return {
    items,
    since,
    limit,
    hasMore: matched.length > limit,
    inboxSeq: rows.reduce((max, row) => Math.max(max, Number(row.inboxSeq) || 0), 0),
  };
}

// 收件箱的「按类计数 + 最大 inboxSeq」备忘。/api/steward/state 由前端 30 秒(SSE 断时 5–15 秒)轮询,
// 每个管家回合的状态块也会取一次;修前每次都把整份 inbox-v1.ndjson(全读上限 8MB)重读重解析,
// 只为数这两样(7MB / 1.7 万行实测每次 80–130ms)。
// 备忘的键是文件自己的 stat 指纹(路径 + size + mtimeMs + ino):追加、截断、被外部改写都会让指纹变,
// 变了就照旧整份重算 —— 所以输出与修前逐位一致,而不是靠「每处写入都记得同步计数」的约定。
// 先 stat 后读:读到的内容只可能【不早于】键所代表的那一刻,竞态下最坏是下次多重算一回,不会读到陈旧值。
let stewardInboxCountsMemo = null;   // { key, byKind, inboxSeq }
async function stewardInboxCounts() {
  const file = stewardInboxPath();
  let key = '', size = 0;
  try {
    const st = await fsp.stat(file);
    size = st.size;
    key = [file, st.size, st.mtimeMs, st.ino].join('|');
  } catch { /* 文件不存在:下面按空箱子算,不进备忘 */ }
  if (key && stewardInboxCountsMemo && stewardInboxCountsMemo.key === key) return stewardInboxCountsMemo;
  const rows = await stewardReadInboxRows();
  const byKind = {};
  for (const kind of STEWARD_EVENT_KINDS) byKind[kind] = 0;
  let inboxSeq = 0;
  for (const row of rows) {
    inboxSeq = Math.max(inboxSeq, Number(row.inboxSeq) || 0);
    if (Object.prototype.hasOwnProperty.call(byKind, row.kind)) byKind[row.kind] += 1;
  }
  const counts = { key, byKind, inboxSeq };
  // 文件非空却一行都没读出来:多半是这一次读撞上瞬时锁(stewardReadInboxText 吞掉错误回空串;Windows 杀软 / 索引器
  // 常见),别把「空箱子」记进备忘 —— 否则文件不再变就一直报零(审查轮复现过)。下一次照旧重读。
  stewardInboxCountsMemo = key && (size === 0 || rows.length > 0) ? counts : null;
  return counts;
}

async function stewardInboxState(config) {
  const cfg = (config && typeof config === 'object') ? config : await readConfig().catch(() => ({}));
  const counted = await stewardInboxCounts();
  const byKind = { ...counted.byKind };   // 拷一份:备忘对象不外泄,调用方随便改也污染不了下一次
  const inboxSeq = counted.inboxSeq;
  return {
    enabled: cfg.stewardEnabledV1 === true,
    running: stewardRuntime.running,
    inboxSeq: Math.max(inboxSeq, stewardRuntime.inboxSeq),
    pollMs: stewardConsistencyMs(cfg.stewardPollMs),
    lastTickAt: stewardRuntime.lastTickAt,
    // 116-4(§11.7 第 3 项「唤醒链诚实」):前端要能分清三件事 —— 轮询活着(lastTickAt 在动)、
    // 箱子真的收到过东西(lastInboxAt)、第四源真的在工作(sourcesSeen.sessionTurns)。
    // 修前只有 lastTickAt,一个「每 15 秒空转一次」的收件箱和一个真在干活的收件箱长得一模一样。
    lastInboxAt: stewardRuntime.lastInboxAt,
    sourcesSeen: { sessionTurns: Number(stewardRuntime.sourcesSeen.sessionTurns) || 0 },
    lastError: stewardRuntime.lastError,
    counts: { byKind },
    retention: { historyDays: 30, historyMax: STEWARD_INBOX_HISTORY_MAX, preservesPending: true,
      maintenanceIntervalMs: STEWARD_INBOX_MAINTENANCE_MS, lastMaintenanceAt: stewardRuntime.lastMaintenanceAt ? new Date(stewardRuntime.lastMaintenanceAt).toISOString() : '' },
  };
}

// ============================================================================
// 第 117 波 T1(32 号文 §2.1「拆 13g-steward.js」):管家工具面的共享底座。
//
// 落点(transport 层,manifest 中位于 13i-steward-inbox.js 之后、13k-steward-threads.js 之前)。
// T1 拆分:原 13g-steward.js 已 2088 行,`steward-runner.static.e2e.js` ①「13g 不超过 SPEC 目标
// 2000 行」在 HEAD 上长期是红的,而 31 号文七轴还要往管家里加 8-12 个工具。按「谁被谁引用」把它
// 拆成四个文件,拼接顺序即依赖方向,零新增前向边:
//   · 13j-steward-tool-base.js(本文件)—— 两个工具族都要用的共享面:常量、稳定信封、门控壳用的
//     失败信封、会话头读取与线程小工具、决策日志(写与只读)、记忆存储、深读预算、每回合配额桶、
//     速查线程的两条判据。它被下面三个文件引用,故排在最前;
//   · 13k-steward-threads.js —— 线程族(tier edit):派活原语 + thread_* / quick_ask /
//     threads_search / 收件箱行增强;
//   · 13l-steward-ops.js —— 观察族 / 决策族 / 记忆族 / 设置族 / 内容管理族;
//   · 13g-steward.js —— 管家域路由、记忆面板、工具门控壳与 StewardHooks 注册表(排在最后,
//     因为注册表要引用上面两个文件里的 stewardImpl*,排在后面才是后向边)。
// 本次拆分是【纯搬家】:所有函数体逐字节不变,新写的只有各文件的头部注释。
//
// 依赖纪律(§11.3「不得新增前向边」):本文件只引用拼接顺序在它之前的模块符号
// (00/01/02/04/06i/13i …),全部后向边;它自己的符号只被 13k/13l/13g/13h 引用,同样是后向边。
//
// 下面这段 116c 的横幅逐字节原样保留。其中「真实实现全在这里」如今指的是
// 13j/13k/13l/13g 这四个文件合起来的「13g 族」,不再只是一个文件;四条铁律一字未改,
// 对整个族同样成立。
// ============================================================================

// ════════════════════════════════════════════════════════════════════════════
// 第 116 波 116c(27 号文 §3.5 工具面 / §4 记忆层 / §11.2 读预算):管家工具集实现。
//
// 定位:12-tool-dispatch.js 里的 17 个 steward_* handler 只写一行 `StewardHooks.xxx(args, ctx)`,
// 真实实现全在这里。这样 12(工具层)→ 06i(引擎层命名空间)是后向边,13g(传输层)单向往 06i 挂方法,
// 全程零新增前向边。
//
// 铁律(§3.4 红线 + §3.3):
//   ① 管家「动如意」,不「动世界」—— 本文件不提供任何文件读写/shell/桌面/浏览器/联网/git 写能力;
//      要动手就 steward_thread_new / steward_thread_continue 委派给线程,由线程按自己的权限档执行。
//   ② 双重 fail-closed:stewardEnabledV1 !== true -> steward.disabled(零写入);
//      ctx.session.kind !== 'steward' -> steward.forbidden(普通会话即使拿到工具名也调不动)。
//   ③ 管家只能收紧,不能放宽:放行范围一律经 06i 的 stewardMayAct(目标线程 permissionMode, ...);
//      永久豁免清单(stewardToolPermanentlyExempt)在任何权限档都返回 propose_required。
//   ④ 每个写动作追加一行决策日志 `<data>/steward/decisions-v1.ndjson`,带 undoRef 与依据。
// ════════════════════════════════════════════════════════════════════════════

// ── 落盘常量(两个新面,已登记进 durable-state-inventory)────────────────────────────────────
const STEWARD_DECISIONS_FILE = 'decisions-v1.ndjson';
const STEWARD_MEMORY_FILE = 'memory-v1.json';
const STEWARD_MEMORY_SCHEMA = 1;

// ── 工具面数值口径 ──────────────────────────────────────────────────────────────────────
const STEWARD_SEARCH_LIMIT_DEFAULT = 10, STEWARD_SEARCH_LIMIT_MAX = 50;
const STEWARD_READ_TAIL_DEFAULT = 6, STEWARD_READ_TAIL_MAX = 20;
const STEWARD_READ_CHARS_DEFAULT = 12000, STEWARD_READ_CHARS_MIN = 1000, STEWARD_READ_CHARS_MAX = 12000;
const STEWARD_READ_CALLS_PER_TURN = 6;      // §11.2:每回合 ≤6 次深读
const STEWARD_READ_ROW_OVERHEAD = 16;       // 每行的行首开销(角色/回合号那一截),算预算时按行计
const STEWARD_READ_CLIP_MARK = '…';         // 117s-H3:被截了头的那一行的行首标记
const STEWARD_AUDIT_LIMIT_DEFAULT = 20, STEWARD_AUDIT_LIMIT_MAX = 100;
const STEWARD_MISSIONS_LIMIT_DEFAULT = 50, STEWARD_MISSIONS_LIMIT_MAX = 200;   // 第二轮走查 F7:steward_missions 的条数帽子
const STEWARD_TITLE_MAX = 80;
const STEWARD_STEER_TEXT_MAX = 2000;
// 116-2b steward_thread_note:管家给【已在跑】的线程补一句上下文。600 字上限比 steer_node 的 2000
// 紧得多 —— 它是"补一句",不是"改任务";前缀由服务端加,与 [用户插话] 的前缀纪律同精神(用户一眼
// 就能分清哪句是自己说的、哪句是管家加的)。
const STEWARD_NOTE_TEXT_MAX = 600;
const STEWARD_NOTE_PREFIX = '（管家补充）';
const STEWARD_PENDING_SUMMARY_MAX = 12;     // thread_status 里最多列几条待决摘要
const STEWARD_RUNS_MAX = 20;                // runs_status 单次最多返回几个 run digest
// 116-2e:同义合并时保留的来源 ref 上限(§4 ⑥「mergedFrom 最多 5 个来源 ref」)。
const STEWARD_MEMORY_MERGED_FROM_MAX = 5;
const STEWARD_MEMORY_NEW_WINDOW_MS = 24 * 60 * 60 * 1000;  // §4 ⑤「新写入 24 小时内带『新』标记」
const STEWARD_PLAYBOOK_DRAFTS_PER_TURN = 1;                // §3.5 内容管理:起草要调模型,每回合一次
const STEWARD_QUICK_ASKS_PER_TURN = 2;                     // §11.1 第 2 项:速查线程每回合最多两条

// ── 稳定信封 ────────────────────────────────────────────────────────────────────────────
// 形状与 105a observation_recall 同源:{ ok:false, error:<稳定码>, message:<人话> }。error 是模型要
// 分支的机器码,message 只给人看;调用方(模型)对 propose_required / quota_exceeded / steward.busy
// 一律不重试 —— schema description 里写明了。
function stewardFail(code, message, extra) {
  return { ok: false, error: String(code), message: String(message || code), ...(extra && typeof extra === 'object' ? extra : {}) };
}

// ── 小工具 ──────────────────────────────────────────────────────────────────────────────
function stewardClampInt(value, min, max, dflt) {
  const n = Number(value);
  if (!Number.isFinite(n)) return dflt;
  return Math.min(max, Math.max(min, Math.round(n)));
}
// 会话头的原始 kind(未经 sessionKind 归一)。管家会话过滤与目标合法性判定都靠它。
async function stewardReadSessionHead(sessionId) {
  const sid = safeSessionId(sessionId);
  if (!sid) return null;
  try {
    const head = safeJsonParse(await fsp.readFile(sessionPath(sid), 'utf8'), null);
    // 116-2a: 这条读路径绕过 loadSession(只要头,不装正文),所以要自己盖一次会话级权限档的内存
    // 覆盖表 —— 否则用户刚在活回合期间切了档、还没落盘,管家读到的就是旧档(见 02 的覆盖表头注)。
    return head && typeof head === 'object' ? applySessionPermissionModeOverride(head) : head;
  } catch { return null; }
}
function stewardRawKind(head) {
  const k = head && head.kind;
  return (typeof k === 'string' && k) ? k : (head && head.mission ? 'mission' : 'quick_ask');
}
// 线程的【生效】权限档 = resolvePermissionMode 的会话级 > 全局两层(§3.3「新线程用全局默认权限」)。
// 116-2a:改为直调 01-config 的解析器,与回合执行侧(runSessionTurn)用的是同一个函数、同一张白名单 ——
// 管家判「我能不能替它答」与线程实际按哪档执行,从此不可能各算各的。请求级那一层是回合内临时值,
// 不在会话头上,管家看不到也不该看到(它只对那一单当前执行链有效)。
function stewardThreadPermissionMode(head, config) {
  return resolvePermissionMode({ session: head, config });
}
function stewardLastAssistantText(session) {
  const messages = Array.isArray(session && session.messages) ? session.messages : [];
  for (let i = messages.length - 1; i >= 0; i--) {
    const m = messages[i];
    if (m && m.role === 'assistant' && String(m.content || '').trim()) return String(m.content);
  }
  return String((session && session.summary) || '');
}
// 117s-H1:这一回合的交付正文 = turnSeq 对得上的【最后一条】助手话(09-workflow.js:3079 落盘时每条
// 助手消息都带 turnSeq);不知道回合号、或那一回合没有非空正文时退到整份会话的最后一条非空助手话
// (与 stewardLastAssistantText 同一口径,但【不】退到 session.summary —— 摘要不是交付)。
function stewardTurnAssistantText(session, turnSeq) {
  const messages = Array.isArray(session && session.messages) ? session.messages : [];
  const want = Math.max(0, Number(turnSeq) || 0);
  let matched = '', last = '';
  for (const m of messages) {
    if (!m || m.role !== 'assistant') continue;
    const text = String(m.content == null ? '' : m.content);
    if (!text.trim()) continue;
    last = text;
    if (want > 0 && Number(m.turnSeq) === want) matched = text;
  }
  return matched || last;
}

// 117s-H1:这一回合写过的文件。事实源是【既有的】改动账 —— 02-session-store.js:1513 foldTurnSummaries,
// 也就是 13d:986 给 /api/missions 详情(「看改动」面板)算 filesChanged 的那一份,不新造任何跟踪器。
// fold 按 path 后写胜去重,故同一路径被后面的回合又改过时它归属那个更新的回合 —— 本函数只在
// 【刚跑完的那一回合】上调用,是 fold 里最新的那一层,不受这条影响。
const STEWARD_DELIVERABLE_FILES_MAX = 20;
function stewardTurnFiles(session, turnSeq) {
  const want = Math.max(0, Number(turnSeq) || 0);
  if (!want) return [];
  let folded = null;
  try { folded = foldTurnSummaries(session); } catch { return []; }
  const files = [];
  for (const f of ((folded && folded.filesChanged) || [])) {
    if (!f || !f.path || Number(f.turnSeq) !== want) continue;
    const p = stewardSanitizeText(f.path);
    if (p && !files.includes(p)) files.push(p);
    if (files.length >= STEWARD_DELIVERABLE_FILES_MAX) break;
  }
  return files;
}

function stewardEngineOf(head) {
  const route = (head && head.engineRoute && typeof head.engineRoute === 'object') ? head.engineRoute : null;
  if (!route) return { engine: '', model: '' };
  return {
    engine: route.engine === 'openai' ? 'openai' : (route.agentCliType || 'claude'),
    model: String(route.model || ''),
    providerId: String(route.providerId || ''),
  };
}

// ── 决策日志(§3.5「所有写工具返回 undoRef,决策日志记录」)───────────────────────────────
// 与 inbox 同款 append-only 纪律:先 repairMissionChangeTornTail 把尾部半行截干净,再整行 appendFile,
// 全部经一条 per-process 串行链。开关关时根本走不到这里(门控壳先返回 steward.disabled)。
const stewardDecisionsPath = () => path.join(stewardDir(), STEWARD_DECISIONS_FILE);
let stewardDecisionChain = Promise.resolve();
let stewardDecisionSeq = 0;
// 116-2b:自理动作的溯源基底。13h 在【工具入参】上挂一个内部字段 stewardBasis({inboxSeq,auto,origin}),
// 由下面两个实现并进决策日志的 basis —— 事后能分清「这一次重试是管家自理做的、由第 N 条收件箱
// 事件触发」。它不在工具 schema 里(additionalProperties:false),模型即使编造出来也只影响日志注解,
// 不影响任何判定;args 照旧只记摘要字段,这一坨不进 args。
function stewardBasisOf(args, extra) {
  const raw = (args && typeof args.stewardBasis === 'object' && args.stewardBasis) ? args.stewardBasis : null;
  const base = (extra && typeof extra === 'object') ? { ...extra } : {};
  if (!raw) return base;
  if (raw.inboxSeq != null) base.inboxSeq = Number(raw.inboxSeq) || 0;
  if (raw.auto != null) base.auto = raw.auto === true;
  if (raw.origin) base.origin = String(raw.origin).slice(0, 40);
  // 「没做完就续」自理动作的理由(计划进度 / 回合没收口 / 第几次),给行动流水点开时看;只是注解,不参与任何判定。
  if (raw.reason) base.reason = String(raw.reason).slice(0, 120);
  return base;
}

function stewardAppendDecision(row) {
  const record = {
    seq: ++stewardDecisionSeq,
    at: nowIso(),
    tool: String((row && row.tool) || ''),
    args: (row && row.args && typeof row.args === 'object') ? row.args : {},
    targetSessionId: String((row && row.targetSessionId) || ''),
    permissionMode: String((row && row.permissionMode) || ''),
    mayAct: String((row && row.mayAct) || ''),
    undoRef: (row && row.undoRef) || null,
    basis: (row && row.basis && typeof row.basis === 'object') ? row.basis : {},
  };
  const line = JSON.stringify(record) + '\n';
  stewardDecisionChain = stewardDecisionChain.then(async () => {
    await fsp.mkdir(stewardDir(), { recursive: true });
    const file = stewardDecisionsPath();
    await repairMissionChangeTornTail(file);
    await fsp.appendFile(file, line, 'utf8');
  }).catch(() => {}); // 记账失败绝不回滚已经做完的动作(与 usage ledger 同款 fire-and-forget 纪律)
  return record;
}

// ── 决策日志的只读面(117e 第 0 步 · §8.6「行动流水」)────────────────────────────────────
// 在 117e 之前决策日志【只有】工具 `steward_audit_tail` 能读 —— 也就是说,只有模型看得见管家做过
// 什么,用户看不见。§8.6 明写「行动流水页按时间列出管家做过的每件事(依据、线程权限、undoRef、
// 费用),支持按线程与按日期过滤」,那需要一条 HTTP 只读面。
//
// 纪律与 inbox 尾窗读取同源(13i stewardReadInboxText/ParseInboxText 的形状):小文件整读、大文件只读
// 尾窗并丢首个半行、坏行整行跳过、文件不存在 = 空(绝不 mkdir —— 开关关时零持久化写入的红线)。
const STEWARD_DECISIONS_LIMIT_DEFAULT = 50;
const STEWARD_DECISIONS_LIMIT_MAX = 200;
const STEWARD_DECISIONS_FULL_READ_BYTES = 8 * 1024 * 1024;
const STEWARD_DECISIONS_TAIL_BYTES = 1024 * 1024;
const STEWARD_DECISIONS_MASK = '••••';

// args 里像密钥的值一律掩码。**判据复用 116-2e 的那一条**(06i 的 STEWARD_CONFIG_SECRET_PATTERN,
// `/apiKey|token|secret|password/i`)—— 不另写第二份正则:两份正则迟早会漂移,而漂移的方向永远是
// 「新面漏掉了旧面拦住的东西」。按【键名】判定(值本身可能是任意串,按值猜是猜不准的),对象递归,
// 深度与宽度都有硬顶(决策日志的 args 本就只记摘要字段,超了说明写日志的地方出了别的问题)。
function stewardMaskDecisionArgs(value, depth = 0) {
  if (depth > 4 || value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.slice(0, 50).map(item => stewardMaskDecisionArgs(item, depth + 1));
  const out = {};
  for (const [key, item] of Object.entries(value).slice(0, 50)) {
    if (STEWARD_CONFIG_SECRET_PATTERN.test(key)) { out[key] = STEWARD_DECISIONS_MASK; continue; }
    out[key] = stewardMaskDecisionArgs(item, depth + 1);
  }
  return out;
}

async function stewardReadDecisionsText() {
  const file = stewardDecisionsPath();
  let size = -1;
  try { size = (await fsp.stat(file)).size; } catch { return { text: '', droppedHead: false }; }
  if (size <= STEWARD_DECISIONS_FULL_READ_BYTES) {
    try { return { text: await fsp.readFile(file, 'utf8'), droppedHead: false }; } catch { return { text: '', droppedHead: false }; }
  }
  // 117q-B6(30 号文 P2-10):open/alloc/read/close 收编进 01-config.js 的 readFileTail —— 本处早已按
  // bytesRead 定界(无 bug),这里只是把手写的四步换成共用原语,行为不变。
  try {
    const { buf, bytesRead } = await readFileTail(file, STEWARD_DECISIONS_TAIL_BYTES);
    return { text: buf.toString('utf8', 0, bytesRead), droppedHead: true };
  } catch { return { text: '', droppedHead: false }; }
}

// { limit, sessionId, since } -> { ok, rows, total, limit }
//   · rows 按时间【倒序】(最近的在最前),这是行动流水页的自然阅读序;
//   · since 认 ISO 时间串(比 seq 稳:seq 是 per-process 计数器,重启即从 1 重来),给了就只回
//     `at > since` 的行;非法值当没给(不是报错 —— 只读面对坏参数一律降级为「不过滤」);
//   · total = 尾窗内命中过滤的总行数(不是全量文件行数,尾窗外的行本来就读不到)。
async function stewardDecisionsRead(opts) {
  const o = (opts && typeof opts === 'object') ? opts : {};
  const rawLimit = Number(o.limit);
  const limit = Number.isFinite(rawLimit) && rawLimit > 0
    ? Math.min(STEWARD_DECISIONS_LIMIT_MAX, Math.max(1, Math.round(rawLimit)))
    : STEWARD_DECISIONS_LIMIT_DEFAULT;
  const sessionId = safeSessionId(String(o.sessionId || ''));
  const sinceRaw = String(o.since || '').trim().slice(0, 40);
  const since = sinceRaw && !Number.isNaN(Date.parse(sinceRaw)) ? sinceRaw : '';
  const { text, droppedHead } = await stewardReadDecisionsText();
  const lines = String(text || '').split('\n');
  const matched = [];
  for (let i = droppedHead ? 1 : 0; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;
    const row = safeJsonParse(line, null);
    if (!row || typeof row !== 'object' || Array.isArray(row) || !row.tool) continue;  // 坏行整行跳过
    const at = String(row.at || '');
    if (sessionId && String(row.targetSessionId || '') !== sessionId) continue;
    if (since && !(at > since)) continue;
    matched.push({
      seq: Number(row.seq) || 0,
      at,
      tool: String(row.tool || ''),
      args: stewardMaskDecisionArgs((row.args && typeof row.args === 'object') ? row.args : {}),
      targetSessionId: String(row.targetSessionId || ''),
      permissionMode: String(row.permissionMode || ''),
      mayAct: String(row.mayAct || ''),
      undoRef: (row.undoRef && typeof row.undoRef === 'object') ? row.undoRef : null,
      basis: (row.basis && typeof row.basis === 'object') ? stewardMaskDecisionArgs(row.basis) : {},
      ...(row.cost != null ? { cost: Number(row.cost) || 0 } : {}),
    });
  }
  matched.reverse();
  return { ok: true, rows: matched.slice(0, limit), total: matched.length, limit };
}

// **住在 13j 不住在 06i**:实测 manifest 里 06i@18 排在 06d@19 【之前】—— 06i 引用 06d 的
// projectKeyForCwd 是前向边,而且会连带造出 7 条循环边(依赖图 --check 当场报)。这与 125-P1
// 「06i 读 06 会造 7 条循环边」是同一个坑、同一个文件:**06i 之后的 06 系模块,06i 一律够不着。**
// 13j@39 在 06d 之后、在 13l/13g/13o 之前,是这组函数唯一站得住的落点。
// ── 126-M01(44 号文 §1.2 / §6 ①):记忆的作用域 ──────────────────────────────────────
// 取值两态:空串 = 全局;`project:<16 位十六进制>` = 只在那个项目里成立。键复用工作台库的
// projectKeyForCwd(06d,后向边)—— **两库同一口径**,与 M02 复用 memoryIsExpired 是同一条理由。
//
// **键永远由服务端从一条真实会话的 cwd 推出来,模型只说「这条是不是项目级的」**。这一条是故意的:
// 31 号文 §2.6 的红线要的是「用户自己说的稳定事实」,让模型自己填一个项目键 = 让它推断
// 「这条管得着谁」,正是那条红线禁止的事。
//
// 非法值一律回落全局 —— **绝不静默当成某个项目**(那会让一条本该到处成立的偏好凭空消失一半)。
const STEWARD_SCOPE_PROJECT_PREFIX = 'project:';
function stewardMemoryScopeOf(cwd) {
  const key = cwd ? projectKeyForCwd(cwd) : '';
  return key ? STEWARD_SCOPE_PROJECT_PREFIX + key : '';
}
function stewardNormalizeMemoryScope(raw) {
  const value = String(raw || '');
  if (!value.startsWith(STEWARD_SCOPE_PROJECT_PREFIX)) return '';
  const key = value.slice(STEWARD_SCOPE_PROJECT_PREFIX.length);
  return /^[0-9a-f]{16}$/.test(key) ? value : '';
}
